    setCurrentView('tasks');
  };

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  useEffect(() => {
    const root = document.documentElement;
    const themeColors = THEMES[primaryColor] || THEMES.indigo;

    Object.keys(themeColors).forEach((key) => {
      root.style.setProperty(`--color-primary-${key}`, themeColors[Number(key)]);
    });

    const fontMap: Record<string, string> = {
      'Plus Jakarta Sans': "'Plus Jakarta Sans', sans-serif",
      'Inter UI': "'Inter', sans-serif",
      'Montserrat': "'Montserrat', sans-serif",
      'Outfit': "'Outfit', sans-serif",
      'Lexend': "'Lexend', sans-serif",
      'Playfair': "'Playfair Display', serif",
    };
    root.style.setProperty('--font-family', fontMap[fontFamily] || "'Inter', sans-serif");

    const sizeMap: Record<string, string> = {
      'Small': '14px',
      'Medium': '16px',
      'Large': '17px',
      'XL': '18px'
    };
    root.style.setProperty('--base-font-size', sizeMap[density] || '16px');
    root.style.fontSize = sizeMap[density] || '16px';

  }, [primaryColor, fontFamily, density]);

  const toggleTheme = () => setIsDark(!isDark);

  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50,
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: 'Bayas Ahamed',
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    } as Contact;
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddAccount = (newAccount: Account) => {
    setAccounts(prevAccounts => [...prevAccounts, newAccount]);
  };

  const handleUpdateAccount = (updatedAccount: Account) => {
    setAccounts(prevAccounts => prevAccounts.map(a => 
      a.id === updatedAccount.id ? updatedAccount : a
    ));
  };

  const handleDeleteAccount = (accountId: string) => {
    setAccounts(prevAccounts => prevAccounts.filter(a => a.id !== accountId));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddMeeting = (newMeeting: Meeting) => {
    setMeetings(prev => [...prev, newMeeting]);
  };

  const handleUpdateMeeting = (updatedMeeting: Meeting) => {
    setMeetings(prev => prev.map(m => m.id === updatedMeeting.id ? updatedMeeting : m));
  };

  const handleDeleteMeeting = (meetingId: string) => {
    setMeetings(prev => prev.filter(m => m.id !== meetingId));
  };

  const handleAddDeal = (newDeal: Deal) => {
    const activities = newDeal.activities && newDeal.activities.length > 0 
      ? newDeal.activities 
      : [{
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }];

    const dealWithActivity = {
      ...newDeal,
      activities
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({ id: Date.now().toString() + 's', type: 'stage_change', description: `Stage updated to ${updatedDeal.stage}`, timestamp });
      }
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({ id: Date.now().toString() + 'v', type: 'value_change', description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`, timestamp });
      }
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({ id: Date.now().toString() + 'p', type: 'probability_change', description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`, timestamp });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);
      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({ id: Date.now().toString() + 'u', type: 'update', description: `Deal details updated`, timestamp });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const handleAddTask = (newTask: Task) => {
    setTasks(prev => [newTask, ...prev]);
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const handleAddCampaign = (newCampaign: Campaign) => {
    setCampaigns(prev => [...prev, newCampaign]);
  };

  const handleUpdateCampaign = (updatedCampaign: Campaign) => {
    setCampaigns(prev => prev.map(c => c.id === updatedCampaign.id ? updatedCampaign : c));
  };

  const handleDeleteCampaign = (campaignId: string) => {
    setCampaigns(prev => prev.filter(c => c.id !== campaignId));
  };

  const handleAddDocument = (newDoc: Document) => {
    setDocuments(prev => [newDoc, ...prev]);
  };

  const handleDeleteDocument = (docId: string) => {
    setDocuments(prev => prev.filter(d => d.id !== docId));
  };

  const handleUpdateDocument = (updatedDoc: Document) => {
    setDocuments(prev => prev.map(d => d.id === updatedDoc.id ? updatedDoc : d));
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
      case 'leads':
        return <Leads 
            leads={leads}
            accounts={accounts} 
            contacts={contacts}
            onAddLead={handleAddLead} 
            onUpdateLead={handleUpdateLead} 
            onDeleteLeads={handleDeleteLeads} 
            onAddDeal={handleAddDeal} 
            onViewOpportunities={() => setCurrentView('pipeline')}
            onAddDocument={handleAddDocument}
            documents={documents}
            onUpdateDocument={handleUpdateDocument}
            onDeleteDocument={handleDeleteDocument}
        />;
      case 'pipeline':
        return <Pipeline 
            deals={deals}
            accounts={accounts}
            contacts={contacts}
            onAddDeal={handleAddDeal} 
            onUpdateDeal={handleUpdateDeal} 
            pipelineGoal={pipelineGoal} 
            onSetGoal={handleSetPipelineGoal} 
        />;
      case 'tasks':
        return <Tasks tasks={tasks} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />;
      case 'meetings':
        return <Meetings 
          meetings={meetings} 
          contacts={contacts}
          accounts={accounts}
          onAddMeeting={handleAddMeeting} 
          onUpdateMeeting={handleUpdateMeeting} 
          onDeleteMeeting={handleDeleteMeeting}
        />;
      case 'contacts':
        return <Contacts 
          contacts={contacts} 
          accounts={accounts}
          onAddContact={handleAddContact} 
          onUpdateContact={handleUpdateContact} 
        />;
      case 'accounts':
        return <Accounts 
          accounts={accounts} 
          contacts={contacts} 
          deals={deals}
          leads={leads}
          meetings={meetings}
          calls={calls}
          onAddAccount={handleAddAccount} 
          onUpdateAccount={handleUpdateAccount} 
          onDeleteAccount={handleDeleteAccount}
          onAddContact={handleAddContact}
          onAddCall={handleAddCall}
          onAddDocument={handleAddDocument}
        />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} accounts={accounts} onAddCall={handleAddCall} />;
      case 'campaigns': 
        return <Campaigns 
          campaigns={campaigns} 
          onAddCampaign={handleAddCampaign} 
          onUpdateCampaign={handleUpdateCampaign} 
          onDeleteCampaign={handleDeleteCampaign} 
        />;
      case 'documents':
        return <Documents 
          documents={documents}
          onAddDocument={handleAddDocument}
          onUpdateDocument={handleUpdateDocument}
          onDeleteDocument={handleDeleteDocument}
        />;
      case 'templates':
        return <Templates />;
      case 'settings':
        return <Settings 
          isDark={isDark} 
          toggleTheme={toggleTheme} 
          primaryColor={primaryColor} 
          setPrimaryColor={setPrimaryColor} 
          pipelineGoal={pipelineGoal}
          setPipelineGoal={handleSetPipelineGoal}
          fontFamily={fontFamily}
          setFontFamily={setFontFamily}
          density={density}
          setDensity={setDensity}
          weekStart={weekStart}
          setWeekStart={setWeekStart}
          dateFormat={dateFormat}
          setDateFormat={setDateFormat}
          timeZone={timeZone}
          setTimeZone={setTimeZone}
          timeFormat={timeFormat}
          setTimeFormat={setTimeFormat}
          workingDays={workingDays}
          setWorkingDays={setWorkingDays}
          fiscalYearStart={fiscalYearStart}
          setFiscalYearStart={setFiscalYearStart}
        />;
      case 'visits': return <PlaceholderModule title="Visits" />;
      case 'projects': return <PlaceholderModule title="Projects" />;
      default: return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-primary-500/30 transition-colors duration-300">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}
      <Sidebar 
        currentView={currentView} 
        setView={(view) => { setCurrentView(view); setSidebarOpen(false); }} 
        isOpen={sidebarOpen}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <div className="absolute inset-0 z-0 pointer-events-none bg-grid-pattern dark:bg-grid-pattern-dark bg-grid opacity-[0.03] dark:opacity-[0.05]"></div>

        <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300 z-10">
          <div className="flex items-center">
            <button onClick={() => setSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
              <IconMenu className="w-6 h-6" />
            </button>
            <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
          </div>
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </header>
        {currentView !== 'settings' && (
            <div className="hidden md:block absolute top-6 right-8 z-20">
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </div>
        )}
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-transparent relative z-0 p-4 md:p-8 pt-4 md:pt-8 custom-scrollbar">
          {renderContent()}
        </main>
        <AIChat leads={leads} deals={deals} />
      </div>
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { Lead, Deal, Account, Contact, Document } from '../types';
import { 
  IconSearch, IconPlus, IconArrowUp, IconArrowDown, IconTrash, IconUser
} from './Icons';
import LeadDetail from './LeadDetail';
import LeadForm from './LeadForm';

interface LeadsProps {
  leads: Lead[];
  accounts?: Account[];
  contacts?: Contact[];
  onAddLead: (lead: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (ids: string[]) => void;
  onAddDeal: (deal: Deal) => void;
  onViewOpportunities?: () => void;
  onAddDocument: (doc: Document) => void;
  documents?: Document[];
  onUpdateDocument?: (doc: Document) => void;
  onDeleteDocument?: (id: string) => void;
}

type ViewMode = 'list' | 'detail' | 'create' | 'edit';
type SortKey = keyof Lead;

const Leads: React.FC<LeadsProps> = ({ 
    leads, 
    accounts = [], 
    contacts = [], 
    onAddLead, 
    onUpdateLead, 
    onDeleteLeads, 
    onAddDeal, 
    onViewOpportunities, 
    onAddDocument,
    documents = [],
    onUpdateDocument,
    onDeleteDocument
}) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  const [searchQuery, setSearchQuery] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    if (selectedLead) {
      const updatedLead = leads.find(l => l.id === selectedLead.id);
      if (updatedLead) setSelectedLead(updatedLead);
    }
  }, [leads, selectedLead]);

  const filteredLeads = useMemo(() => {
    return leads.filter(lead => {
      const matchesSearch = 
        lead.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
        lead.company.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lead.email.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesSearch;
    });
  }, [leads, searchQuery]);

  const sortedLeads = useMemo(() => {
    let items = [...filteredLeads];
    if (sortConfig) {
      items.sort((a, b) => {
        // @ts-ignore
        const aVal = a[sortConfig.key] || '';
        // @ts-ignore
        const bVal = b[sortConfig.key] || '';
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return items;
  }, [filteredLeads, sortConfig]);

  const handleSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const toggleSelectLead = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedLeadIds(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === sortedLeads.length) {
      setSelectedLeadIds(new Set());
    } else {
      setSelectedLeadIds(new Set(sortedLeads.map(l => l.id)));
    }
  };

  const handleDeleteSelected = () => {
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} leads?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  if (viewMode === 'create' || (viewMode === 'edit' && selectedLead)) {
    return (
      <LeadForm 
        onCancel={() => { setViewMode('list'); setSelectedLead(null); }}
        onSave={(lead) => { 
            if (viewMode === 'create') onAddLead(lead);
            else if (selectedLead) onUpdateLead({ ...lead, id: selectedLead.id });
            setViewMode('list'); 
            setSelectedLead(null);
        }}
        initialData={viewMode === 'edit' ? selectedLead : null}
        accounts={accounts}
        contacts={contacts}
      />
    );
  }

  if (viewMode === 'detail' && selectedLead) {
    return (
      <LeadDetail 
        lead={selectedLead} 
        onBack={() => { setViewMode('list'); setSelectedLead(null); }}
        onEdit={() => setViewMode('edit')}
        onDelete={() => { onDeleteLeads([selectedLead.id]); setViewMode('list'); setSelectedLead(null); }}
        onNurture={() => {}}
        isNurturing={false}
        leads={leads}
        onComposeEmail={() => {}}
        onAddDeal={onAddDeal}
        onUpdateLead={onUpdateLead}
        onViewOpportunities={onViewOpportunities}
        onAddDocument={onAddDocument}
        documents={documents}
        onUpdateDocument={onUpdateDocument}
        onDeleteDocument={onDeleteDocument}
      />
    );
  }

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
      <div className="flex justify-between items-center flex-shrink-0">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Leads</h1>
        <div className="flex items-center gap-3">
          {selectedLeadIds.size > 0 && (
            <button onClick={handleDeleteSelected} className="px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors flex items-center">
              <IconTrash className="w-4 h-4 mr-2" /> Delete ({selectedLeadIds.size})
            </button>
          )}
          <button onClick={() => setViewMode('create')} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center">
            <IconPlus className="w-4 h-4 mr-2" /> New Lead
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
           <div className="relative max-w-md w-full">
             <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
             <input type="text" placeholder="Search leads..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" />
           </div>
        </div>

        <div className="overflow-auto flex-1">
          <table className="w-full text-left text-sm border-collapse">
            <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 font-semibold border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
              <tr>
                <th className="px-6 py-4 w-12">
                  <input type="checkbox" checked={selectedLeadIds.size === sortedLeads.length && sortedLeads.length > 0} onChange={toggleSelectAll} className="rounded border-slate-300 text-primary-600 focus:ring-primary-500 cursor-pointer w-4 h-4" />
                </th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('name')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Name {getSortIcon('name')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('company')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Company {getSortIcon('company')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('email')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Email {getSortIcon('email')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('status')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Status {getSortIcon('status')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('score')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Score {getSortIcon('score')}</div></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {sortedLeads.map((lead, index) => (
                <tr 
                    key={lead.id} 
                    className={`group transition-all duration-200 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800/60 ${index % 2 === 0 ? 'bg-white dark:bg-slate-900' : 'bg-slate-50/50 dark:bg-slate-900/40'}`}
                    onClick={() => { setSelectedLead(lead); setViewMode('detail'); }}
                >
                  <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                    <input type="checkbox" checked={selectedLeadIds.has(lead.id)} onChange={() => toggleSelectLead(lead.id)} className="rounded border-slate-300 text-primary-600 focus:ring-primary-500 cursor-pointer w-4 h-4" />
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center">
                        <div className="w-9 h-9 rounded-full bg-gradient-to-br from-slate-100 to-slate-200 dark:from-slate-800 dark:to-slate-700 text-slate-600 dark:text-slate-300 flex items-center justify-center mr-3 text-sm font-bold border border-slate-200 dark:border-slate-700 shadow-sm">{lead.name.charAt(0)}</div>
                        <div><span className="font-semibold text-slate-900 dark:text-white block">{lead.name}</span><span className="text-xs text-slate-500 dark:text-slate-400 md:hidden">{lead.title}</span></div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-slate-600 dark:text-slate-300 font-medium">{lead.company}</td>
                  <td className="px-6 py-4 text-slate-500 dark:text-slate-400">{lead.email}</td>
                  <td className="px-6 py-4">
                    <span className={`px-3 py-1 text-xs font-semibold rounded-full border ${lead.status === 'New' ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' : lead.status === 'Contacted' ? 'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800' : lead.status === 'Qualified' ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' : 'bg-slate-50 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700'}`}>{lead.status}</span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                        <div className="w-16 h-2 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full ${lead.score > 70 ? 'bg-emerald-500' : lead.score > 40 ? 'bg-amber-500' : 'bg-red-500'}`} style={{ width: `${lead.score}%` }}></div>
                        </div>
                        <span className={`text-sm font-bold ${lead.score > 70 ? 'text-emerald-600 dark:text-emerald-400' : lead.score > 40 ? 'text-amber-600 dark:text-amber-400' : 'text-red-600 dark:text-red-400'}`}>{lead.score}</span>
                    </div>
                  </td>
                </tr>
              ))}
              {sortedLeads.length === 0 && (
                  <tr>
                      <td colSpan={6} className="px-6 py-16 text-center text-slate-500 dark:text-slate-400">
                          <div className="flex flex-col items-center justify-center">
                              <div className="p-4 bg-slate-50 dark:bg-slate-800/50 rounded-full mb-3"><IconUser className="w-8 h-8 text-slate-300 dark:text-slate-600" /></div>
                              <p className="text-lg font-semibold text-slate-900 dark:text-white">No leads found</p>
                              <p className="text-sm mt-1">Try adjusting your search filters or add a new lead.</p>
                          </div>
                      </td>
                  </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

