import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Deal, Activity, Account, Contact, Task } from '../types';
import { IconX, IconMail, IconPhone, IconFilter, IconHistory, IconClock, IconCalendar, IconCheckCircle, IconTarget, IconBuilding, IconUser, IconZap, IconBriefcase, IconSparkles } from './Icons';

interface PipelineProps {
