                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Pending</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{pendingCount}</h3>
                        </div>
                        <div className="p-2 bg-amber-50 dark:bg-amber-900/20 rounded-lg text-amber-600 dark:text-amber-400">
                            <IconClock className="w-5 h-5" />
                        </div>
                    </div>
                </div>
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Completed</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{completedCount}</h3>
                        </div>
                        <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg text-emerald-600 dark:text-emerald-400">
                            <IconCheckCircle className="w-5 h-5" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Controls */}
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
                <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                    <div className="relative flex-1 max-w-md">
                        <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="Search visits..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div className="flex items-center gap-3">
                        <select 
                            value={statusFilter}
                            onChange={(e) => setStatusFilter(e.target.value)}
                            className="px-3 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 dark:text-slate-200 cursor-pointer"
                        >
                            <option value="All">All Status</option>
                            {VISIT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                </div>

                <div className="flex-1 overflow-auto custom-scrollbar p-4 space-y-3">
                    {filteredVisits.length > 0 ? (
                        filteredVisits.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(visit => (
                            <div 
                                key={visit.id}
                                onClick={() => handleOpenModal(visit)}
                                className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl p-4 hover:shadow-md transition-all cursor-pointer group"
                            >
                                <div className="flex flex-col md:flex-row justify-between gap-4">
                                    <div className="flex items-start gap-4">
                                        <div className="flex flex-col items-center min-w-[60px] p-2 bg-slate-50 dark:bg-slate-900/50 rounded-lg border border-slate-100 dark:border-slate-700">
                                            <span className="text-xs font-bold text-red-500 uppercase">{new Date(visit.date).toLocaleString('default', { month: 'short' })}</span>
                                            <span className="text-xl font-bold text-slate-900 dark:text-white">{new Date(visit.date).getDate()}</span>
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <h3 className="font-bold text-slate-900 dark:text-white text-lg group-hover:text-primary-600 transition-colors">{visit.title}</h3>
                                                <span className={`px-2 py-0.5 text-xs font-bold rounded-full ${getStatusColor(visit.status)}`}>
                                                    {visit.status}
                                                </span>
                                            </div>
                                            <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 text-sm text-slate-500 dark:text-slate-400">
                                                <div className="flex items-center gap-1.5">
                                                    <IconBuilding className="w-4 h-4" />
                                                    {visit.relatedTo}
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <IconClock className="w-4 h-4" />
                                                    {visit.startTime} - {visit.endTime}
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <IconMapPin className="w-4 h-4" />
                                                    {visit.location}
                                                </div>
                                                {visit.mapLink && (
                                                    <a 
                                                        href={visit.mapLink}
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        onClick={(e) => e.stopPropagation()}
                                                        className="flex items-center gap-1.5 text-indigo-600 dark:text-indigo-400 hover:underline"
                                                    >
                                                        <IconGlobe className="w-3.5 h-3.5" />
                                                        View on Map
                                                    </a>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2 self-start md:self-center">
                                        {visit.status === 'Scheduled' && (
                                            <button 
                                                onClick={(e) => handleCheckIn(visit, e)}
                                                className="px-3 py-1.5 bg-primary-600 hover:bg-primary-500 text-white text-xs font-bold rounded-lg transition-colors shadow-sm"
                                            >
                                                Check In
                                            </button>
                                        )}
                                        {visit.status === 'In Progress' && (
                                            <button 
                                                onClick={(e) => handleComplete(visit, e)}
                                                className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded-lg transition-colors shadow-sm"
                                            >
                                                Complete
                                            </button>
                                        )}
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDeleteVisit(visit.id); }}
                                            className="p-2 text-slate-400 hover:text-red-500 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg transition-colors"
                                        >
                                            <IconTrash className="w-4 h-4" />
                                        </button>
                                        <IconChevronRight className="w-5 h-5 text-slate-300 dark:text-slate-600" />
                                    </div>
                                </div>
                            </div>
                        ))
                    ) : (
                        <div className="flex flex-col items-center justify-center h-64 text-center">
                            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                                <IconMapPin className="w-8 h-8 text-slate-400" />
                            </div>
                            <h3 className="text-lg font-medium text-slate-900 dark:text-white">No visits found</h3>
                            <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 max-w-sm">
                                Try adjusting your search filters or schedule a new visit to get started.
                            </p>
                        </div>
                    )}
                </div>
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                        <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                                <IconMapPin className="w-5 h-5 mr-3 text-primary-500" />
                                {selectedVisit ? 'Edit Visit' : 'Schedule Visit'}
                            </h2>
                            <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors">
                                <IconX className="w-6 h-6" />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="p-6 space-y-4 overflow-y-auto max-h-[80vh]">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Subject <span className="text-red-500">*</span></label>
                                <input 
                                    type="text" 
                                    value={formData.title} 
                                    onChange={(e) => setFormData({...formData, title: e.target.value})} 
                                    placeholder="e.g. Site Inspection at HQ"
                                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    required 
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Related To <span className="text-red-500">*</span></label>
                                    <input 
                                        type="text" 
                                        value={formData.relatedTo} 
                                        onChange={(e) => setFormData({...formData, relatedTo: e.target.value})} 
                                        placeholder="Account Name"
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                        required 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Type</label>
                                    <select 
                                        value={formData.type} 
                                        onChange={(e) => setFormData({...formData, type: e.target.value as VisitType})}
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    >
                                        {VISIT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Location</label>
                                <div className="flex gap-2">
                                    <input 
                                        type="text" 
                                        value={formData.location} 
                                        onChange={(e) => setFormData({...formData, location: e.target.value})} 
                                        placeholder="Address or Place Name"
                                        className="flex-1 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    />
                                    <button 
                                        type="button" 
                                        onClick={handleVerifyLocation}
                                        disabled={isLookingUpMap || !formData.location}
                                        className="px-3 py-2 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 disabled:opacity-50"
                                        title="Find exact location on Google Maps"
                                    >
                                        {isLookingUpMap ? <span className="animate-spin text-lg">⟳</span> : <IconSearch className="w-4 h-4" />}
                                    </button>
                                </div>
                                {formData.mapLink && (
                                    <a 
                                        href={formData.mapLink} 
                                        target="_blank" 
                                        rel="noopener noreferrer" 
                                        className="text-xs text-indigo-600 dark:text-indigo-400 mt-1 block hover:underline"
                                    >
                                        Location Verified (Open Map)
                                    </a>
                                )}
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Date <span className="text-red-500">*</span></label>
                                    <input 
                                        type="date" 
                                        value={formData.date} 
                                        onChange={(e) => setFormData({...formData, date: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                        required 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Status</label>
                                    <select 
                                        value={formData.status} 
                                        onChange={(e) => setFormData({...formData, status: e.target.value as VisitStatus})}
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    >
                                        {VISIT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Start Time</label>
                                    <input 
                                        type="time" 
                                        value={formData.startTime} 
                                        onChange={(e) => setFormData({...formData, startTime: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">End Time</label>
                                    <input 
                                        type="time" 
                                        value={formData.endTime} 
                                        onChange={(e) => setFormData({...formData, endTime: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Notes</label>
                                <textarea 
                                    rows={3}
                                    value={formData.notes || ''} 
                                    onChange={(e) => setFormData({...formData, notes: e.target.value})} 
                                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    placeholder="Additional instructions..."
                                />
                            </div>

                            <div className="pt-4 flex justify-end gap-3 border-t border-slate-100 dark:border-slate-800">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 dark:text-slate-300 dark:hover:text-white transition-colors">Cancel</button>
                                <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors shadow-lg shadow-primary-500/20">
                                    {selectedVisit ? 'Save Changes' : 'Schedule Visit'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Visits;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Visit, VisitStatus, VisitType, Account } from '../types';
import { 
    IconMapPin, IconCalendar, IconClock, IconPlus, IconSearch, 
    IconFilter, IconCheckCircle, IconX, IconUser, IconBuilding,
    IconArrowUp, IconArrowDown, IconEdit, IconTrash, IconChevronRight,
    IconSparkles, IconGlobe
} from './Icons';
import { findPlace } from '../services/geminiService';

interface VisitsProps {
    visits: Visit[];
    accounts?: Account[];
    onAddVisit: (visit: Visit) => void;
    onUpdateVisit: (visit: Visit) => void;
    onDeleteVisit: (id: string) => void;
}

const VISIT_TYPES: VisitType[] = ['Sales', 'Site Inspection', 'Service', 'Delivery', 'Demo'];
const VISIT_STATUSES: VisitStatus[] = ['Scheduled', 'In Progress', 'Completed', 'Cancelled'];

const Visits: React.FC<VisitsProps> = ({ visits, accounts = [], onAddVisit, onUpdateVisit, onDeleteVisit }) => {
    const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('All');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedVisit, setSelectedVisit] = useState<Visit | null>(null);
    const [formData, setFormData] = useState<Partial<Visit>>({
        date: new Date().toISOString().split('T')[0],
        startTime: '09:00',
        endTime: '10:00',
        status: 'Scheduled',
        type: 'Sales',
        assignedTo: 'Alex Chen',
        location: '',
        mapLink: ''
    });

    // Account Autocomplete State
    const [showAccountSuggestions, setShowAccountSuggestions] = useState(false);
    const [filteredAccounts, setFilteredAccounts] = useState<Account[]>([]);
    const accountWrapperRef = useRef<HTMLDivElement>(null);

    // Loading state for map lookup
    const [isLookingUpMap, setIsLookingUpMap] = useState(false);

    // Click outside to close suggestions
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (accountWrapperRef.current && !accountWrapperRef.current.contains(event.target as Node)) {
                setShowAccountSuggestions(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [accountWrapperRef]);

    // Metrics
    const today = new Date().toISOString().split('T')[0];
    const todayVisits = visits.filter(v => v.date === today);
    const completedCount = todayVisits.filter(v => v.status === 'Completed').length;
    const pendingCount = todayVisits.filter(v => v.status === 'Scheduled' || v.status === 'In Progress').length;

    const filteredVisits = useMemo(() => {
        return visits.filter(visit => {
            const matchesSearch = 
                visit.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                visit.relatedTo.toLowerCase().includes(searchQuery.toLowerCase()) ||
                visit.location.toLowerCase().includes(searchQuery.toLowerCase());

            const matchesStatus = statusFilter === 'All' || visit.status === statusFilter;

            return matchesSearch && matchesStatus;
        });
    }, [visits, searchQuery, statusFilter]);

    const handleOpenModal = (visit?: Visit) => {
        if (visit) {
            setSelectedVisit(visit);
            setFormData(visit);
        } else {
            setSelectedVisit(null);
            setFormData({
                date: new Date().toISOString().split('T')[0],
                startTime: '09:00',
                endTime: '10:00',
                status: 'Scheduled',
                type: 'Sales',
                assignedTo: 'Alex Chen',
                title: '',
                relatedTo: '',
                location: '',
                mapLink: ''
            });
        }
        setFilteredAccounts([]);
        setIsModalOpen(true);
    };

    const handleRelatedToChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setFormData({ ...formData, relatedTo: value });

        if (value && accounts.length > 0) {
            const matches = accounts.filter(a => a.name.toLowerCase().includes(value.toLowerCase()));
            setFilteredAccounts(matches);
            setShowAccountSuggestions(matches.length > 0);
        } else {
            setShowAccountSuggestions(false);
        }
    };

    const selectAccount = (account: Account) => {
        setFormData(prev => ({
            ...prev,
            relatedTo: account.name,
            location: account.address || prev.location,
            mapLink: account.address ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(account.address)}` : prev.mapLink
        }));
        setShowAccountSuggestions(false);
    };

    const handleVerifyLocation = async () => {
        if (!formData.location) {
            alert("Please enter a location name or address first.");
            return;
        }
        setIsLookingUpMap(true);
        const result = await findPlace(formData.location);
        if (result) {
            setFormData(prev => ({ 
                ...prev, 
                location: result.address, 
                mapLink: result.mapLink 
            }));
        }
        setIsLookingUpMap(false);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.title || !formData.relatedTo || !formData.date) {
            alert('Please fill in all required fields.');
            return;
        }

        const visitData = {
            id: selectedVisit ? selectedVisit.id : `V-${Date.now()}`,
            ...formData
        } as Visit;

        if (selectedVisit) {
            onUpdateVisit(visitData);
        } else {
            onAddVisit(visitData);
        }
        setIsModalOpen(false);
    };

    const handleCheckIn = (visit: Visit, e: React.MouseEvent) => {
        e.stopPropagation();
        onUpdateVisit({ ...visit, status: 'In Progress' });
    };

    const handleComplete = (visit: Visit, e: React.MouseEvent) => {
        e.stopPropagation();
        onUpdateVisit({ ...visit, status: 'Completed', outcome: 'Visit completed successfully.' });
    };

    const getStatusColor = (status: VisitStatus) => {
        switch (status) {
            case 'Scheduled': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
            case 'In Progress': return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400';
            case 'Completed': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
            case 'Cancelled': return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
            default: return 'bg-slate-100 text-slate-600';
        }
    };

    return (
        <div className="space-y-6 h-full flex flex-col animate-fade-in">
            {/* Header */}
            <div className="flex justify-between items-center flex-shrink-0">
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Field Visits</h1>
                <button 
                    onClick={() => handleOpenModal()}
                    className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
                >
                    <IconPlus className="w-4 h-4 mr-2" /> Schedule Visit
                </button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-shrink-0">
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Today's Visits</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{todayVisits.length}</h3>
                        </div>
                        <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg text-blue-600 dark:text-blue-400">
                            <IconMapPin className="w-5 h-5" />
                        </div>
                    </div>
                </div>
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Pending</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{pendingCount}</h3>
                        </div>
                        <div className="p-2 bg-amber-50 dark:bg-amber-900/20 rounded-lg text-amber-600 dark:text-amber-400">
                            <IconClock className="w-5 h-5" />
                        </div>
                    </div>
                </div>
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Completed</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{completedCount}</h3>
                        </div>
                        <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg text-emerald-600 dark:text-emerald-400">
                            <IconCheckCircle className="w-5 h-5" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Controls */}
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
                <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                    <div className="relative flex-1 max-w-md">
                        <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="Search visits..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div className="flex items-center gap-3">
                        <select 
                            value={statusFilter}
                            onChange={(e) => setStatusFilter(e.target.value)}
                            className="px-3 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 dark:text-slate-200 cursor-pointer"
                        >
                            <option value="All">All Status</option>
                            {VISIT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                </div>

                <div className="flex-1 overflow-auto custom-scrollbar p-4 space-y-3">
                    {filteredVisits.length > 0 ? (
                        filteredVisits.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(visit => (
                            <div 
                                key={visit.id}
                                onClick={() => handleOpenModal(visit)}
                                className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl p-4 hover:shadow-md transition-all cursor-pointer group"
                            >
                                <div className="flex flex-col md:flex-row justify-between gap-4">
                                    <div className="flex items-start gap-4">
                                        <div className="flex flex-col items-center min-w-[60px] p-2 bg-slate-50 dark:bg-slate-900/50 rounded-lg border border-slate-100 dark:border-slate-700">
                                            <span className="text-xs font-bold text-red-500 uppercase">{new Date(visit.date).toLocaleString('default', { month: 'short' })}</span>
                                            <span className="text-xl font-bold text-slate-900 dark:text-white">{new Date(visit.date).getDate()}</span>
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <h3 className="font-bold text-slate-900 dark:text-white text-lg group-hover:text-primary-600 transition-colors">{visit.title}</h3>
                                                <span className={`px-2 py-0.5 text-xs font-bold rounded-full ${getStatusColor(visit.status)}`}>
                                                    {visit.status}
                                                </span>
                                            </div>
                                            <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 text-sm text-slate-500 dark:text-slate-400">
                                                <div className="flex items-center gap-1.5">
                                                    <IconBuilding className="w-4 h-4" />
                                                    {visit.relatedTo}
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <IconClock className="w-4 h-4" />
                                                    {visit.startTime} - {visit.endTime}
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <IconMapPin className="w-4 h-4" />
                                                    {visit.location}
                                                </div>
                                                {visit.mapLink && (
                                                    <a 
                                                        href={visit.mapLink}
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        onClick={(e) => e.stopPropagation()}
                                                        className="flex items-center gap-1.5 text-indigo-600 dark:text-indigo-400 hover:underline"
                                                    >
                                                        <IconGlobe className="w-3.5 h-3.5" />
                                                        View on Map
                                                    </a>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2 self-start md:self-center">
                                        {visit.status === 'Scheduled' && (
                                            <button 
                                                onClick={(e) => handleCheckIn(visit, e)}
                                                className="px-3 py-1.5 bg-primary-600 hover:bg-primary-500 text-white text-xs font-bold rounded-lg transition-colors shadow-sm"
                                            >
                                                Check In
                                            </button>
                                        )}
                                        {visit.status === 'In Progress' && (
                                            <button 
                                                onClick={(e) => handleComplete(visit, e)}
                                                className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded-lg transition-colors shadow-sm"
                                            >
                                                Complete
                                            </button>
                                        )}
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDeleteVisit(visit.id); }}
                                            className="p-2 text-slate-400 hover:text-red-500 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg transition-colors"
                                        >
                                            <IconTrash className="w-4 h-4" />
                                        </button>
                                        <IconChevronRight className="w-5 h-5 text-slate-300 dark:text-slate-600" />
                                    </div>
                                </div>
                            </div>
                        ))
                    ) : (
                        <div className="flex flex-col items-center justify-center h-64 text-center">
                            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                                <IconMapPin className="w-8 h-8 text-slate-400" />
                            </div>
                            <h3 className="text-lg font-medium text-slate-900 dark:text-white">No visits found</h3>
                            <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 max-w-sm">
                                Try adjusting your search filters or schedule a new visit to get started.
                            </p>
                        </div>
                    )}
                </div>
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                        <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                                <IconMapPin className="w-5 h-5 mr-3 text-primary-500" />
                                {selectedVisit ? 'Edit Visit' : 'Schedule Visit'}
                            </h2>
                            <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors">
                                <IconX className="w-6 h-6" />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="p-6 space-y-4 overflow-y-auto max-h-[80vh]">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Subject <span className="text-red-500">*</span></label>
                                <input 
                                    type="text" 
                                    value={formData.title} 
                                    onChange={(e) => setFormData({...formData, title: e.target.value})} 
                                    placeholder="e.g. Site Inspection at HQ"
                                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    required 
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="relative" ref={accountWrapperRef}>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Related To <span className="text-red-500">*</span></label>
                                    <div className="relative">
                                        <input 
                                            type="text" 
                                            value={formData.relatedTo} 
                                            onChange={handleRelatedToChange} 
                                            onFocus={() => { if(formData.relatedTo && accounts.length) setShowAccountSuggestions(true); }}
                                            placeholder="Account Name"
                                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                            required 
                                            autoComplete="off"
                                        />
                                        <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                                        {showAccountSuggestions && (
                                            <div className="absolute z-50 w-full mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-2xl max-h-48 overflow-y-auto custom-scrollbar">
                                                {filteredAccounts.map(account => (
                                                    <div 
                                                        key={account.id}
                                                        onClick={() => selectAccount(account)}
                                                        className="px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer flex items-center justify-between border-b border-slate-100 dark:border-slate-700 last:border-0 transition-colors"
                                                    >
                                                        <div>
                                                            <div className="text-sm font-medium text-slate-900 dark:text-white">{account.name}</div>
                                                            <div className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[200px]">{account.address || 'No address'}</div>
                                                        </div>
                                                        <IconChevronRight className="w-3 h-3 text-slate-400" />
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Type</label>
                                    <select 
                                        value={formData.type} 
                                        onChange={(e) => setFormData({...formData, type: e.target.value as VisitType})}
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    >
                                        {VISIT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Location</label>
                                <div className="flex gap-2">
                                    <input 
                                        type="text" 
                                        value={formData.location} 
                                        onChange={(e) => setFormData({...formData, location: e.target.value})} 
                                        placeholder="Address or Place Name"
                                        className="flex-1 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    />
                                    <button 
                                        type="button" 
                                        onClick={handleVerifyLocation}
                                        disabled={isLookingUpMap || !formData.location}
                                        className="px-3 py-2 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 disabled:opacity-50"
                                        title="Find exact location on Google Maps"
                                    >
                                        {isLookingUpMap ? <span className="animate-spin text-lg">⟳</span> : <IconSearch className="w-4 h-4" />}
                                    </button>
                                </div>
                                {formData.mapLink && (
                                    <a 
                                        href={formData.mapLink} 
                                        target="_blank" 
                                        rel="noopener noreferrer" 
                                        className="text-xs text-indigo-600 dark:text-indigo-400 mt-1 block hover:underline"
                                    >
                                        Location Verified (Open Map)
                                    </a>
                                )}
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Date <span className="text-red-500">*</span></label>
                                    <input 
                                        type="date" 
                                        value={formData.date} 
                                        onChange={(e) => setFormData({...formData, date: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                        required 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Status</label>
                                    <select 
                                        value={formData.status} 
                                        onChange={(e) => setFormData({...formData, status: e.target.value as VisitStatus})}
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    >
                                        {VISIT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Start Time</label>
                                    <input 
                                        type="time" 
                                        value={formData.startTime} 
                                        onChange={(e) => setFormData({...formData, startTime: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">End Time</label>
                                    <input 
                                        type="time" 
                                        value={formData.endTime} 
                                        onChange={(e) => setFormData({...formData, endTime: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Notes</label>
                                <textarea 
                                    rows={3}
                                    value={formData.notes || ''} 
                                    onChange={(e) => setFormData({...formData, notes: e.target.value})} 
                                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white"
                                    placeholder="Additional instructions..."
                                />
                            </div>

                            <div className="pt-4 flex justify-end gap-3 border-t border-slate-100 dark:border-slate-800">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 dark:text-slate-300 dark:hover:text-white transition-colors">Cancel</button>
                                <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors shadow-lg shadow-primary-500/20">
                                    {selectedVisit ? 'Save Changes' : 'Schedule Visit'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Visits;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Visit, VisitStatus, VisitType, Account } from '../types';
import { 
    IconMapPin, IconCalendar, IconClock, IconPlus, IconSearch, 
    IconFilter, IconCheckCircle, IconX, IconUser, IconBuilding,
    IconArrowUp, IconArrowDown, IconEdit, IconTrash, IconChevronRight,
    IconSparkles, IconGlobe
} from './Icons';
import { findPlace } from '../services/geminiService';

interface VisitsProps {
    visits: Visit[];
    accounts?: Account[];
    onAddVisit: (visit: Visit) => void;
    onUpdateVisit: (visit: Visit) => void;
    onDeleteVisit: (id: string) => void;
}

const VISIT_TYPES: VisitType[] = ['Sales', 'Site Inspection', 'Service', 'Delivery', 'Demo'];
const VISIT_STATUSES: VisitStatus[] = ['Scheduled', 'In Progress', 'Completed', 'Cancelled'];
const DATE_FILTERS = ['All Time', 'This Week', 'This Month', 'This Quarter', 'This Year'];

const Visits: React.FC<VisitsProps> = ({ visits, accounts = [], onAddVisit, onUpdateVisit, onDeleteVisit }) => {
    const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('All');
    const [dateFilter, setDateFilter] = useState<string>('All Time');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedVisit, setSelectedVisit] = useState<Visit | null>(null);
    const [formData, setFormData] = useState<Partial<Visit>>({
        date: new Date().toISOString().split('T')[0],
        startTime: '09:00',
        endTime: '10:00',
        status: 'Scheduled',
        type: 'Sales',
        assignedTo: 'Alex Chen',
        location: '',
        mapLink: ''
    });

    // Account Autocomplete State
    const [showAccountSuggestions, setShowAccountSuggestions] = useState(false);
    const [filteredAccounts, setFilteredAccounts] = useState<Account[]>([]);
    const accountWrapperRef = useRef<HTMLDivElement>(null);

    // Loading state for map lookup
    const [isLookingUpMap, setIsLookingUpMap] = useState(false);

    // Click outside to close suggestions
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (accountWrapperRef.current && !accountWrapperRef.current.contains(event.target as Node)) {
                setShowAccountSuggestions(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [accountWrapperRef]);

    // Metrics
    const today = new Date().toISOString().split('T')[0];
    const todayVisits = visits.filter(v => v.date === today);
    const completedCount = todayVisits.filter(v => v.status === 'Completed').length;
    const pendingCount = todayVisits.filter(v => v.status === 'Scheduled' || v.status === 'In Progress').length;

    const filteredVisits = useMemo(() => {
        return visits.filter(visit => {
            const matchesSearch = 
                visit.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                visit.relatedTo.toLowerCase().includes(searchQuery.toLowerCase()) ||
                visit.location.toLowerCase().includes(searchQuery.toLowerCase());

            const matchesStatus = statusFilter === 'All' || visit.status === statusFilter;

            let matchesDate = true;
            if (dateFilter !== 'All Time') {
                const visitDate = new Date(visit.date);
                const now = new Date();

                // Reset time part for accurate date comparison
                now.setHours(0,0,0,0); 
                // Note: visitDate usually comes from YYYY-MM-DD string so it defaults to UTC midnight or local depending on parsing. 
                // Assuming simple date comparison based on the string value is safest for 'This Year/Month' but logic below uses Date objects.
                // Ensuring consistency:
                const visitDateMidnight = new Date(visitDate.getFullYear(), visitDate.getMonth(), visitDate.getDate());

                if (dateFilter === 'This Week') {
                    const startOfWeek = new Date(now);
                    startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday as start
                    startOfWeek.setHours(0, 0, 0, 0);
                    matchesDate = visitDateMidnight >= startOfWeek;
                } else if (dateFilter === 'This Month') {
                    matchesDate = visitDate.getMonth() === now.getMonth() && visitDate.getFullYear() === now.getFullYear();
                } else if (dateFilter === 'This Quarter') {
                    const currentQuarter = Math.floor(now.getMonth() / 3);
                    const visitQuarter = Math.floor(visitDate.getMonth() / 3);
                    matchesDate = currentQuarter === visitQuarter && visitDate.getFullYear() === now.getFullYear();
                } else if (dateFilter === 'This Year') {
                    matchesDate = visitDate.getFullYear() === now.getFullYear();
                }
            }

            return matchesSearch && matchesStatus && matchesDate;
        });
    }, [visits, searchQuery, statusFilter, dateFilter]);

    const handleOpenModal = (visit?: Visit) => {
        if (visit) {
            setSelectedVisit(visit);
            setFormData(visit);
        } else {
            setSelectedVisit(null);
            setFormData({
                date: new Date().toISOString().split('T')[0],
                startTime: '09:00',
                endTime: '10:00',
                status: 'Scheduled',
                type: 'Sales',
                assignedTo: 'Alex Chen',
                title: '',
                relatedTo: '',
                location: '',
                mapLink: ''
            });
        }
        setFilteredAccounts([]);
        setIsModalOpen(true);
    };

    const handleRelatedToChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setFormData({ ...formData, relatedTo: value });

        if (value && accounts.length > 0) {
            const matches = accounts.filter(a => a.name.toLowerCase().includes(value.toLowerCase()));
            setFilteredAccounts(matches);
            setShowAccountSuggestions(matches.length > 0);
        } else {
            setShowAccountSuggestions(false);
        }
    };

    const selectAccount = (account: Account) => {
        setFormData(prev => ({
            ...prev,
            relatedTo: account.name,
            location: account.address || prev.location,
            mapLink: account.address ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(account.address)}` : prev.mapLink
        }));
        setShowAccountSuggestions(false);
    };

    const handleVerifyLocation = async () => {
        if (!formData.location) {
            alert("Please enter a location name or address first.");
            return;
        }
        setIsLookingUpMap(true);
        const result = await findPlace(formData.location);
        if (result) {
            setFormData(prev => ({ 
                ...prev, 
                location: result.address, 
                mapLink: result.mapLink 
            }));
        }
        setIsLookingUpMap(false);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.title || !formData.relatedTo || !formData.date) {
            alert('Please fill in all required fields.');
            return;
        }

        const visitData = {
            id: selectedVisit ? selectedVisit.id : `V-${Date.now()}`,
            ...formData
        } as Visit;

        if (selectedVisit) {
            onUpdateVisit(visitData);
        } else {
            onAddVisit(visitData);
        }
        setIsModalOpen(false);
    };

    const handleCheckIn = (visit: Visit, e: React.MouseEvent) => {
        e.stopPropagation();
        onUpdateVisit({ ...visit, status: 'In Progress' });
    };

    const handleComplete = (visit: Visit, e: React.MouseEvent) => {
        e.stopPropagation();
        onUpdateVisit({ ...visit, status: 'Completed', outcome: 'Visit completed successfully.' });
    };

    const getStatusColor = (status: VisitStatus) => {
        switch (status) {
            case 'Scheduled': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
            case 'In Progress': return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400';
            case 'Completed': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
            case 'Cancelled': return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
            default: return 'bg-slate-100 text-slate-600';
        }
    };

    return (
        <div className="space-y-6 h-full flex flex-col animate-fade-in">
            {/* Header */}
            <div className="flex justify-between items-center flex-shrink-0">
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Field Visits</h1>
                <button 
                    onClick={() => handleOpenModal()}
                    className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
                >
                    <IconPlus className="w-4 h-4 mr-2" /> Schedule Visit
                </button>
            </div>

            {/* Stats Cards */}
