/**
 * Finds account location and suggests nearby competitors using Google Maps Grounding.
 */
export const findAccountLocationAndNearby = async (companyName: string, website: string, industry: string): Promise<{ address: string, competitors: string }> => {
  try {
    const prompt = `Locate the headquarters of ${companyName} (${website}) using Google Maps. 
    1. Provide the full street address.
    2. Using Google Maps, find 3-4 nearby companies that are in the "${industry}" sector/industry segment.

    Format the output exactly as follows:
    Address: [Full Address]

    Nearby Opportunities:
    - [Company Name]: [Distance/Brief details]
    - [Company Name]: [Distance/Brief details]
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    const text = response.text || "";

    // Simple parsing to extract address and list
    const addressMatch = text.match(/Address:\s*(.*?)(\n|$)/i);
    const address = addressMatch ? addressMatch[1].trim() : "";

    // Extract everything after "Nearby Opportunities:"
    const competitorsMatch = text.match(/Nearby Opportunities:([\s\S]*)/i);
    const competitors = competitorsMatch ? competitorsMatch[1].trim() : "";

    return { 
      address: address || "Location not found.", 
      competitors: competitors || "No nearby data found." 
    };

  } catch (error) {
    console.error("Gemini Maps Location Error:", error);
    return { address: "", competitors: "Unable to fetch location data." };
  }
};

/**
 * Finds specific location address and map link using Google Maps Grounding.
 */
export const findPlace = async (query: string): Promise<{ address: string, mapLink: string }> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Find the precise address for "${query}". Return just the address.`,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    let mapLink = '';
    // Check grounding chunks for Maps URI
    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        const chunk = response.candidates[0].groundingMetadata.groundingChunks.find(c => c.maps?.uri);
        if (chunk && chunk.maps) {
            mapLink = chunk.maps.uri;
        }
    }

    // If no specific maps link found in chunks, generate a search link
    if (!mapLink) {
         mapLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
    }

    return { 
        address: response.text?.trim() || query, 
        mapLink 
    };
  } catch (error) {
    console.error("Find Place Error:", error);
    return { address: query, mapLink: `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}` };
  }
};

