export type LeadStatus = 'New' | 'Contacted' | 'Qualified' | 'Proposal Sent' | 'Negotiation' | 'Closed Won' | 'Closed Lost';

export interface Activity {
  id: string;
  type: 'created' | 'stage_change' | 'value_change' | 'probability_change' | 'email_sent' | 'meeting_scheduled' | 'follow_up' | 'update' | 'call' | 'note' | 'task';
  description: string;
  timestamp: string;
}

export interface Lead {
  id: string;
  name: string;
  firstName?: string;
  lastName?: string;
  company: string;
  email: string;
  phone: string;
  mobile?: string;
  website?: string;
  leadSource?: string;
  status: LeadStatus;
  industry: string;
  noOfEmployees?: number;
  annualRevenue?: number;
  rating?: string;
  score: number;
  scoreBreakdown: { fit: number; engagement: number; budget: number };
  value?: number;
  notes?: string;
  title?: string;
  city?: string;
  fax?: string;
  owner?: string;
  lastContact?: string;
  activities?: Activity[];
}

export interface Deal {
