/**
 * Generates a comprehensive project plan including description and milestones.
 */
export const generateProjectPlan = async (project: Partial<Project>): Promise<{ description: string, nextMilestone: string, riskLevel: 'Low' | 'Medium' | 'High' }> => {
  try {
    const prompt = `You are a Senior Project Manager. Create a high-level project plan for the following project.

    **Project Details:**
    - Name: ${project.name}
    - Client: ${project.client || 'Internal'}
    - Dates: ${project.startDate} to ${project.endDate}
    - Budget: $${project.budget}

    **Requirements:**
    1. **Description**: A concise 2-sentence summary of what this project likely entails based on the name.
    2. **Next Milestone**: The most immediate and critical next step/milestone.
    3. **Risk Level**: Assess the risk (Low, Medium, High) based on typical complexities of such projects.

    Return JSON:
    {
      "description": "string",
      "nextMilestone": "string",
      "riskLevel": "Low" | "Medium" | "High"
    }
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            nextMilestone: { type: Type.STRING },
            riskLevel: { type: Type.STRING, enum: ['Low', 'Medium', 'High'] }
          },
          required: ['description', 'nextMilestone', 'riskLevel']
        }
      }
    });

    const text = response.text?.trim();
    if (!text) throw new Error("Empty response");
    const jsonStr = text.startsWith("```json") ? text.replace(/```json\n|```/g, "") : text;
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Gemini Project Plan Error:", error);
    return {
      description: "Could not generate plan.",
      nextMilestone: "Define Scope",
      riskLevel: "Medium"
    };
  }
};

/**
 * Identifies potential risks for a project.
 */
export const assessProjectRisks = async (project: Project): Promise<string[]> => {
  try {
    const prompt = `Identify 3 key risks for this project: "${project.name}" (Description: ${project.description}).
    Return a simple JSON array of strings.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const text = response.text?.trim();
    if (!text) return [];
    const jsonStr = text.startsWith("```json") ? text.replace(/```json\n|```/g, "") : text;
    return JSON.parse(jsonStr);
  } catch (error) {
    console.error("Gemini Risk Assessment Error:", error);
    return ["Unable to assess risks at this time."];
  }
};

