              <p className="text-sm font-bold text-white truncate">Alex Chen</p>
              <p className="text-xs text-slate-500 truncate group-hover:text-primary-400 transition-colors">{userRole?.name || 'User'}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

