export type VisitStatus = 'Scheduled' | 'In Progress' | 'Completed' | 'Cancelled';
export type VisitType = 'Sales' | 'Site Inspection' | 'Service' | 'Delivery' | 'Demo';

export interface Visit {
  id: string;
  title: string;
  relatedTo: string; // Account or Contact Name
  date: string;
  startTime: string;
  endTime: string;
  location: string;
  mapLink?: string; // Google Maps URL
  type: VisitType;
  status: VisitStatus;
  notes?: string;
  outcome?: string;
  assignedTo: string;
}

export type ProjectStatus = 'Planning' | 'In Progress' | 'On Hold' | 'Completed';
export type ProjectRisk = 'Low' | 'Medium' | 'High';

export interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  budget: number;
  spent: number;
  progress: number; // 0-100
  owner: string;
  description?: string;
  riskLevel?: ProjectRisk;
  riskFactors?: string[];
  nextMilestone?: string;
  client?: string;
}

export type TicketStatus = 'Open' | 'In Progress' | 'Waiting on Customer' | 'Resolved' | 'Closed';
export type TicketPriority = 'Low' | 'Medium' | 'High' | 'Urgent';
export type TicketType = 'Problem' | 'Question' | 'Feature Request' | 'Billing';

export interface Ticket {
  id: string;
  subject: string;
  description: string;
  status: TicketStatus;
  priority: TicketPriority;
  type: TicketType;
  customerName: string; // Contact or Account Name
  accountId?: string; // Link to Account
  assignedTo: string;
  createdAt: string;
  sentimentScore?: number; // 0-100
  sentimentMood?: string; // e.g. "Frustrated", "Neutral", "Happy"
  aiDraftResponse?: string;
}

// RBAC Types
export type Permission = 
  | 'view_dashboard'
  | 'manage_users'
  | 'manage_settings'
  | 'view_leads'
  | 'edit_leads'
  | 'delete_records'
  | 'export_data'
  | 'view_revenue'
  | 'manage_pipeline'
  | 'use_ai_features';

export interface RoleDefinition {
  id: string;
  name: string;
  description: string;
  permissions: Permission[];
  isSystem?: boolean; // Cannot be deleted
}

export interface User {
  id: string;
  name: string;
  email: string;
  roleId: string;
  avatar?: string;
  lastLogin?: string;
  status: 'Active' | 'Inactive';
  tempPassword?: string; // For admin generated passwords
}

