        <div className={`w-10 h-5 rounded-full relative transition-colors duration-200 ease-in-out flex items-center px-0.5 ${checked ? 'bg-primary-500' : 'bg-slate-300 dark:bg-slate-600'}`}>
            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transform transition-transform duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
