);

// Mock API Key Type
interface ApiKey {
    id: string;
    name: string;
    prefix: string;
    created: string;
    lastUsed: string;
    status: 'active' | 'revoked';
}

const Settings: React.FC<SettingsProps> = ({ 
  isDark, 
  toggleTheme, 
  primaryColor, 
  setPrimaryColor,
  pipelineGoal,
  setPipelineGoal,
  fontFamily,
  setFontFamily,
  density,
  setDensity,
  weekStart,
  setWeekStart,
  dateFormat,
  setDateFormat,
  timeZone,
  setTimeZone,
  timeFormat,
  setTimeFormat,
  workingDays,
  setWorkingDays,
  fiscalYearStart,
  setFiscalYearStart,
  defaultPaymentTerm,
  setDefaultPaymentTerm,
  defaultTaxRate,
  setDefaultTaxRate,
  taxEnabled,
  setTaxEnabled,
  defaultCurrency,
  setDefaultCurrency,
  multiCurrency,
  setMultiCurrency,
  roles,
  setRoles,
  users,
  setUsers,
  currentUser,
  setCurrentUser
}) => {
  const [activeTab, setActiveTab] = useState('theme');
  const [companyName, setCompanyName] = useState('TalentSense AI');
  const [goalInput, setGoalInput] = useState(pipelineGoal.toString());
  const [isSaved, setIsSaved] = useState(false);

  // AI State
  const [aiScoring, setAiScoring] = useState(true);
  const [autoDraft, setAutoDraft] = useState(false);
  const [predictivePipeline, setPredictivePipeline] = useState(true);
  const [creativityLevel, setCreativityLevel] = useState(0.7);

  // Notification State
  const [emailAlerts, setEmailAlerts] = useState(true);
  const [dealWonAlert, setDealWonAlert] = useState(true);
  const [newLeadAlert, setNewLeadAlert] = useState(true);
  const [taskReminders, setTaskReminders] = useState(false);

  // Security State
  const [twoFactor, setTwoFactor] = useState(true);
  const [sessionTimeout, setSessionTimeout] = useState('30');

  // API Key State (Internal Gemini)
  const [isApiKeySet, setIsApiKeySet] = useState(false);

  // API Key State (External Integrations)
  const [apiKeys, setApiKeys] = useState<ApiKey[]>([
      { id: '1', name: 'Zapier Integration', prefix: 'nova_live_8a...', created: 'Oct 24, 2023', lastUsed: '2 hours ago', status: 'active' },
      { id: '2', name: 'Website Form Webhook', prefix: 'nova_live_9b...', created: 'Nov 15, 2023', lastUsed: '1 day ago', status: 'active' },
  ]);
  const [showNewKeyModal, setShowNewKeyModal] = useState(false);
  const [newKeyName, setNewKeyName] = useState('');
  const [createdKeySecret, setCreatedKeySecret] = useState<string | null>(null);

  // RBAC Local States
  const [editingRole, setEditingRole] = useState<RoleDefinition | null>(roles[0] || null); // Select first role by default
  const [isCreateRoleModalOpen, setIsCreateRoleModalOpen] = useState(false);
  const [newRoleName, setNewRoleName] = useState('');
  const [newRoleDescription, setNewRoleDescription] = useState('');

  // Password Generation State
  const [passwordModalOpen, setPasswordModalOpen] = useState(false);
  const [selectedUserForPassword, setSelectedUserForPassword] = useState<User | null>(null);
  const [generatedPassword, setGeneratedPassword] = useState('');

  useEffect(() => {
    // Ensure we have a selected role for editing if roles exist
    if (!editingRole && roles.length > 0) {
        setEditingRole(roles[0]);
    }
  }, [roles]);

  useEffect(() => {
    const checkApiKey = async () => {
        if ((window as any).aistudio?.hasSelectedApiKey) {
            const hasKey = await (window as any).aistudio.hasSelectedApiKey();
            setIsApiKeySet(hasKey);
        }
    };
    checkApiKey();
  }, []);

  const handleConfigureApiKey = async () => {
      if ((window as any).aistudio?.openSelectKey) {
          await (window as any).aistudio.openSelectKey();
          setIsApiKeySet(true);
      } else {
          alert("API Key selection is only available in the AI Studio environment.");
      }
  };

  const handleSave = () => {
    setPipelineGoal(Number(goalInput));
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const toggleWorkingDay = (day: string) => {
    if (workingDays.includes(day)) {
      setWorkingDays(workingDays.filter(d => d !== day));
    } else {
      setWorkingDays([...workingDays, day]);
    }
  };

  // API Management Functions
  const generateNewKey = () => {
      if(!newKeyName.trim()) {
          alert("Please enter a name for the API key.");
          return;
      }

      // Mock key generation
      const randomPart = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
      const secret = `nova_live_${randomPart}`;

      const newKey: ApiKey = {
          id: Date.now().toString(),
          name: newKeyName,
          prefix: `nova_live_${randomPart.substring(0, 4)}...`,
          created: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
          lastUsed: 'Never',
          status: 'active'
      };

      setApiKeys([newKey, ...apiKeys]);
      setCreatedKeySecret(secret);
      setNewKeyName('');
  };

  const revokeKey = (id: string) => {
      if(window.confirm("Are you sure you want to revoke this key? Any applications using it will lose access immediately.")) {
          setApiKeys(prev => prev.map(k => k.id === id ? { ...k, status: 'revoked' } : k));
      }
  };

  const deleteKey = (id: string) => {
      if(window.confirm("Delete this key record permanently?")) {
          setApiKeys(prev => prev.filter(k => k.id !== id));
      }
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Copied to clipboard!");
  };

  // RBAC Functions
  const handleUpdateUserRole = (userId: string, roleId: string) => {
      setUsers(users.map(u => u.id === userId ? { ...u, roleId } : u));
      if (currentUser.id === userId) {
          setCurrentUser({ ...currentUser, roleId });
      }
  };

  const handleTogglePermission = (roleId: string, permission: Permission) => {
      setRoles(roles.map(r => {
          if (r.id !== roleId) return r;
          const hasPermission = r.permissions.includes(permission);
          return {
              ...r,
              permissions: hasPermission 
                  ? r.permissions.filter(p => p !== permission)
                  : [...r.permissions, permission]
          };
      }));
      // Manually find the updated role to keep local editing state in sync for UI responsiveness
      // Note: React state batching handles this, but explicitly setting it ensures immediate detail view update
      // We don't setEditingRole here because we want it to pull from the main 'roles' prop via render logic
  };

  const handleCreateRole = () => {
      if (!newRoleName.trim()) {
          alert('Role name is required');
          return;
      }
      const newRole: RoleDefinition = {
          id: newRoleName.toLowerCase().replace(/\s+/g, '_'),
          name: newRoleName,
          description: newRoleDescription,
          isSystem: false,
          permissions: ['view_dashboard'] // Default min permission
      };
      setRoles([...roles, newRole]);
      setIsCreateRoleModalOpen(false);
      setNewRoleName('');
      setNewRoleDescription('');
      setEditingRole(newRole); // Switch to editing the new role
  };

  const handleDeleteRole = (roleId: string) => {
      if (window.confirm('Are you sure you want to delete this role? Users assigned to this role will lose access.')) {
          setRoles(roles.filter(r => r.id !== roleId));
          if (editingRole?.id === roleId) setEditingRole(roles.find(r => r.id !== roleId) || null);
      }
  };

  // Password Generation Logic
  const generateSecurePassword = () => {
      const length = 12;
      const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";
      let retVal = "";
      for (let i = 0, n = charset.length; i < length; ++i) {
          retVal += charset.charAt(Math.floor(Math.random() * n));
      }
      return retVal;
  };

  const handleGeneratePassword = (user: User) => {
      const newPassword = generateSecurePassword();
      setGeneratedPassword(newPassword);
      setSelectedUserForPassword(user);

      // Update user state with temp password
      setUsers(users.map(u => u.id === user.id ? { ...u, tempPassword: newPassword } : u));

      setPasswordModalOpen(true);
  };

  const themes = [
    { name: 'Corporate Indigo', value: 'indigo', color: 'bg-indigo-600' },
    { name: 'Midnight Charcoal', value: 'slate', color: 'bg-slate-900' },
    { name: 'Emerald Forest', value: 'emerald', color: 'bg-emerald-500' },
    { name: 'Royal Amethyst', value: 'purple', color: 'bg-purple-500' },
    { name: 'Sunset Horizon', value: 'orange', color: 'bg-orange-500' },
    { name: 'Slate Professional', value: 'slate', color: 'bg-slate-600' },
    { name: 'Ruby Crimson', value: 'rose', color: 'bg-rose-600' },
    { name: 'Oceanic Teal', value: 'cyan', color: 'bg-cyan-600' },
  ];

  const fonts = [
      { name: 'Plus Jakarta', value: 'Plus Jakarta Sans', description: 'MODERN GEOMETRIC' },
      { name: 'Inter UI', value: 'Inter UI', description: 'NEUTRAL/PROFESSIONAL' },
      { name: 'Montserrat', value: 'Montserrat', description: 'CLASSIC GEOMETRIC' },
      { name: 'Outfit', value: 'Outfit', description: 'SOFT & PREMIUM' },
      { name: 'Lexend', value: 'Lexend', description: 'HIGH READABILITY' },
      { name: 'Playfair', value: 'Playfair', description: 'ELEGANT SERIF' },
  ];

  const PERMISSION_GROUPS = {
      'System Configuration': ['view_dashboard', 'manage_users', 'manage_settings', 'delete_records', 'export_data'],
      'Sales Operations': ['view_leads', 'edit_leads', 'manage_pipeline', 'view_revenue'],
