                    <div className="bg-slate-50 dark:bg-slate-900/50 rounded-lg p-4 border border-slate-200 dark:border-slate-700 mb-4">
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-lg ${isApiKeySet ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-slate-200 text-slate-500 dark:bg-slate-800 dark:text-slate-400'}`}>
                                <IconZap className="w-5 h-5" />
                            </div>
                            <div className="flex-1">
                                <p className="text-sm font-medium text-slate-900 dark:text-white">Google Gemini API</p>
                                <p className="text-xs text-slate-500 dark:text-slate-400">{isApiKeySet ? 'Your application is authenticated and ready to generate content.' : 'Authentication required for AI features.'}</p>
                            </div>
                            <button 
                                onClick={handleConfigureApiKey}
                                className="px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
                            >
                                {isApiKeySet ? 'Change Key' : 'Connect'}
                            </button>
                        </div>
                    </div>

                    <div className="text-xs text-slate-500 dark:text-slate-400">
                        <p>A paid Google Cloud Project is required for advanced features like Video Generation (Veo).</p>
                        <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:text-primary-500 hover:underline mt-1 inline-block">
                            View Billing Documentation &rarr;
                        </a>
                    </div>
                </div>

                {/* 3. External API Access Management */}
                <div className="p-6 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex justify-between items-center mb-6">
                        <div>
                            <h4 className="font-bold text-slate-900 dark:text-white">External API Access</h4>
                            <p className="text-sm text-slate-500 mt-1">Manage API keys for external applications (Zapier, Webhooks, Custom Integrations).</p>
                        </div>
                        <button 
                            onClick={() => setShowNewKeyModal(true)}
                            className="flex items-center px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-sm font-medium rounded-lg hover:opacity-90 transition-opacity"
                        >
                            <IconPlus className="w-4 h-4 mr-2" /> Generate New Key
                        </button>
                    </div>

                    {apiKeys.length > 0 ? (
                        <div className="overflow-x-auto border border-slate-200 dark:border-slate-700 rounded-lg">
                            <table className="w-full text-left text-sm">
                                <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400 font-medium">
                                    <tr>
                                        <th className="px-4 py-3">Name</th>
                                        <th className="px-4 py-3">Key Prefix</th>
                                        <th className="px-4 py-3">Created</th>
                                        <th className="px-4 py-3">Last Used</th>
                                        <th className="px-4 py-3">Status</th>
                                        <th className="px-4 py-3 text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                    {apiKeys.map(key => (
                                        <tr key={key.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30">
                                            <td className="px-4 py-3 font-medium text-slate-900 dark:text-white">{key.name}</td>
                                            <td className="px-4 py-3 font-mono text-xs text-slate-500">{key.prefix}</td>
                                            <td className="px-4 py-3 text-slate-500">{key.created}</td>
                                            <td className="px-4 py-3 text-slate-500">{key.lastUsed}</td>
                                            <td className="px-4 py-3">
                                                <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                                                    key.status === 'active' 
                                                    ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400' 
                                                    : 'bg-red-100 text-red-700 dark:bg-red-500/20 dark:text-red-400'
                                                }`}>
                                                    {key.status === 'active' ? 'Active' : 'Revoked'}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <div className="flex justify-end gap-2">
                                                    {key.status === 'active' && (
                                                        <button 
                                                            onClick={() => revokeKey(key.id)}
                                                            className="text-slate-400 hover:text-amber-500 transition-colors" 
                                                            title="Revoke Key"
                                                        >
                                                            <IconShield className="w-4 h-4" />
                                                        </button>
                                                    )}
                                                    <button 
                                                        onClick={() => deleteKey(key.id)}
                                                        className="text-slate-400 hover:text-red-500 transition-colors" 
                                                        title="Delete Key"
                                                    >
                                                        <IconTrash className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <div className="text-center py-8 bg-slate-50 dark:bg-slate-900/50 rounded-lg border border-dashed border-slate-200 dark:border-slate-700">
                            <IconShield className="w-8 h-8 text-slate-300 mx-auto mb-2" />
                            <p className="text-sm text-slate-500">No active API keys found.</p>
                        </div>
                    )}
                </div>

                {/* Modal for creating new key */}
                {showNewKeyModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                        <div className="w-full max-w-md bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl p-6 animate-scale-in">
                            {!createdKeySecret ? (
                                <>
                                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Create New API Key</h3>
                                    <div className="mb-4">
                                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Key Name</label>
                                        <input 
                                            type="text" 
                                            value={newKeyName}
                                            onChange={(e) => setNewKeyName(e.target.value)}
                                            placeholder="e.g. Production Webhook"
                                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                                        />
                                    </div>
                                    <div className="flex gap-3 justify-end">
                                        <button 
                                            onClick={() => { setShowNewKeyModal(false); setNewKeyName(''); }}
                                            className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 dark:text-slate-300 dark:hover:text-white"
                                        >
                                            Cancel
                                        </button>
                                        <button 
                                            onClick={generateNewKey}
                                            className="px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white text-sm font-medium rounded-lg"
                                        >
                                            Generate Key
                                        </button>
                                    </div>
                                </>
                            ) : (
                                <>
                                    <div className="flex items-center gap-2 mb-4 text-emerald-600 dark:text-emerald-400">
                                        <IconCheckCircle className="w-6 h-6" />
                                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Key Generated!</h3>
                                    </div>
                                    <p className="text-sm text-slate-600 dark:text-slate-400 mb-4">
                                        Please copy your API key now. For security reasons, <strong className="text-slate-900 dark:text-white">it will not be shown again.</strong>
                                    </p>
                                    <div className="relative mb-6">
                                        <input 
                                            type="text" 
                                            readOnly 
                                            value={createdKeySecret} 
                                            className="w-full pl-3 pr-10 py-3 font-mono text-sm bg-slate-100 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-lg text-slate-800 dark:text-slate-200"
                                        />
                                        <button 
                                            onClick={() => copyToClipboard(createdKeySecret)}
                                            className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-md transition-colors text-slate-500"
                                            title="Copy to clipboard"
                                        >
                                            <IconCopy className="w-4 h-4" />
                                        </button>
                                    </div>
                                    <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-100 dark:border-amber-800/30 p-3 rounded-lg mb-6 flex gap-3">
                                        <IconInfo className="w-5 h-5 text-amber-600 dark:text-amber-400 flex-shrink-0" />
                                        <p className="text-xs text-amber-800 dark:text-amber-200">
                                            Store this key securely. If you lose it, you will need to generate a new one.
                                        </p>
                                    </div>
                                    <button 
                                        onClick={() => { setShowNewKeyModal(false); setCreatedKeySecret(null); }}
                                        className="w-full px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white text-sm font-medium rounded-lg"
                                    >
                                        I've Copied It
                                    </button>
                                </>
                            )}
                        </div>
                    </div>
                )}
            </div>
        );

      default:
        return <div className="text-slate-500">Select a category</div>;
    }
  };

  const navItemClass = (id: string) => `
    w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 
    ${activeTab === id 
        ? 'bg-primary-50 text-primary-700 dark:bg-primary-900/20 dark:text-primary-400 shadow-sm' 
        : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
  `;

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-[#0f172a] overflow-hidden">
        {/* Header */}
        <div className="px-8 py-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center sticky top-0 z-10">
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight">Command Center</h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Configure core logic, branding, and regulatory compliance.</p>
            </div>
            <button 
                onClick={handleSave}
                className={`flex items-center gap-2 px-6 py-2.5 font-bold text-sm rounded-lg shadow-lg transition-all active:translate-y-0 hover:-translate-y-0.5 ${isSaved ? 'bg-emerald-500 text-white shadow-emerald-500/30' : 'bg-primary-600 hover:bg-primary-500 text-white shadow-primary-500/30'}`}
            >
                {isSaved ? <IconCheckCircle className="w-4 h-4" /> : <IconSave className="w-4 h-4" />}
                {isSaved ? 'SETTINGS SAVED' : 'UPDATE GLOBAL SETTINGS'}
            </button>
        </div>

        <div className="flex flex-1 overflow-hidden p-8 max-w-7xl mx-auto w-full gap-8">
            {/* Sidebar Navigation */}
            <div className="w-64 flex-shrink-0">
                <nav className="space-y-1">
                    <button onClick={() => setActiveTab('company')} className={navItemClass('company')}>
                        <IconBuilding className="w-5 h-5 mr-3 opacity-70" />
                        Company Profile
                    </button>
                    <button onClick={() => setActiveTab('team')} className={navItemClass('team')}>
                        <IconUsers className="w-5 h-5 mr-3 opacity-70" />
                        Team & Roles
                    </button>
                    <button onClick={() => setActiveTab('theme')} className={navItemClass('theme')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Theme & Brand
                    </button>
                    <button onClick={() => setActiveTab('regional')} className={navItemClass('regional')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Regional & Date
                    </button>
                    <button onClick={() => setActiveTab('finance')} className={navItemClass('finance')}>
                        <IconWallet className="w-5 h-5 mr-3 opacity-70" />
                        Financial Config
                    </button>
                    <button onClick={() => setActiveTab('ai')} className={navItemClass('ai')}>
                        <IconSparkles className="w-5 h-5 mr-3 opacity-70" />
                        AI & Automation
                    </button>
                    <button onClick={() => setActiveTab('notifications')} className={navItemClass('notifications')}>
                        <IconBell className="w-5 h-5 mr-3 opacity-70" />
                        Alerts & Email
                    </button>
                    <button onClick={() => setActiveTab('security')} className={navItemClass('security')}>
                        <IconShield className="w-5 h-5 mr-3 opacity-70" />
                        Security & Access
                    </button>
                </nav>
            </div>

            {/* Content Area */}
            <div className="flex-1 bg-transparent overflow-y-auto custom-scrollbar">
                {renderContent()}
            </div>
        </div>
    </div>
  );
};

