const Dashboard: React.FC<DashboardProps> = ({ leads, deals, isDark = true }) => {
  // --- Metrics Calculation ---
  const newLeadsCount = leads.filter(l => {
      const date = new Date(l.createdTime || '');
      const sevenDaysAgo = new Date();
      sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
      return date > sevenDaysAgo;
  }).length;

  const totalRevenue = deals.filter(d => d.stage === 'Closed Won').reduce((acc, curr) => acc + curr.value, 0);
  const activeDealsCount = deals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length;
  const wonDealsCount = deals.filter(d => d.stage === 'Closed Won').length;

  // --- Chart Data Preparation ---

  // 1. Lead Source Distribution (Pie)
  const leadSourceData = leads.reduce((acc, lead) => {
      const source = lead.leadSource || 'Other';
      acc[source] = (acc[source] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  const pieData = Object.keys(leadSourceData).map(key => ({ name: key, value: leadSourceData[key] }));

  // 2. Deal Stage Funnel (Bar)
  const stageDataRaw = deals.reduce((acc, deal) => {
      acc[deal.stage] = (acc[deal.stage] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  // Dynamic sort based on volume for generic stages
  const barData = Object.keys(stageDataRaw).map(stage => ({
      name: stage.length > 12 ? stage.substring(0, 10) + '...' : stage,
      fullName: stage,
      count: stageDataRaw[stage]
  })).sort((a,b) => b.count - a.count);

  // 3. Revenue Trend + Forecasting (Area + Line)
  // Logic: Real data for past months, Projected for future based on open deals * probability
  const generateTrendData = () => {
      const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug'];
      const currentMonthIndex = new Date().getMonth(); // 0-11
      // Mock data for past
      const baseValues = [120000, 150000, 110000, 180000, 200000, 160000, 0, 0];

      // Calculate forecast for current and future months
      const forecastValues = [...baseValues];

      // Add simple logic: Open deals closing in Month X contribute Value * Probability
      deals.forEach(deal => {
          if (!['Closed Won', 'Closed Lost'].includes(deal.stage)) {
              const closeDate = new Date(deal.closeDate);
              const monthIdx = closeDate.getMonth();
              // Simplified: map year/month to index in our static array. 
              // Assuming 'Jan' is index 0 of current year.
              if (monthIdx >= 0 && monthIdx < months.length) {
                  const weightedValue = deal.value * (deal.probability / 100);
                  forecastValues[monthIdx] += weightedValue;
              }
          }
      });

      return months.map((month, idx) => ({
          name: month,
          actual: idx <= 5 ? baseValues[idx] : null, // Show actuals only for past
          forecast: forecastValues[idx] // Show forecast for all (historical matches actual, future is projected)
      }));
  };
  const trendData = generateTrendData();

  // 4. Top Opportunities (Table/List)
  const topDeals = [...deals]
    .filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage))
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);

  // 5. Recent Activity
  const allActivities = [
      ...leads.flatMap(lead => (lead.activities || []).map(act => ({ ...act, context: lead.name }))),
      ...deals.flatMap(deal => deal.activities.map(act => ({ ...act, context: deal.title })))
  ].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 6);

  return (
    <div className="space-y-6 animate-slide-up pb-8">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-2 md:pr-20">
        <div>
            <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm mb-1 font-medium">
                <IconLayoutDashboard className="w-4 h-4" /> / Dashboard
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Business Overview</h1>
        </div>

        {/* Date Filter - Safe position to avoid overlap with top-right Notification bell */}
        <div className="flex items-center bg-white dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
            {['7D', '30D', '3M', 'YTD'].map((period) => (
                <button 
                    key={period}
                    className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${period === '30D' ? 'bg-primary-50 text-primary-600 dark:bg-primary-900/30 dark:text-primary-400' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
                >
                    {period}
                </button>
            ))}
        </div>
      </div>

      {/* Row 1: KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        <BIStatCard 
            title="New Leads" 
            value={newLeadsCount} 
            subtext="Target: 15" 
            trend="8%"
            icon={IconUsers} 
            colorClass="bg-gradient-to-br from-blue-500 to-blue-600" 
        />
        <BIStatCard 
            title="Active Pipeline" 
            value={activeDealsCount} 
            subtext="Open Deals" 
            icon={IconKanban} 
            colorClass="bg-gradient-to-br from-emerald-400 to-emerald-600" 
        />
        <BIStatCard 
            title="Won Deals" 
            value={wonDealsCount} 
            subtext="This Quarter" 
            trend="15%"
            icon={IconCheckCircle} 
            colorClass="bg-gradient-to-br from-rose-400 to-rose-600" 
        />
        <BIStatCard 
            title="Total Revenue" 
            value={`$${(totalRevenue / 1000).toFixed(1)}k`} 
            subtext="vs last month" 
            trend="12%"
            icon={IconWallet} 
            colorClass="bg-gradient-to-br from-indigo-500 to-purple-600" 
        />
      </div>

      {/* Row 2: Main Charts */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
          {/* Revenue Trend - Takes 2 cols */}
          <ChartWidget title="Revenue Forecast (Actual vs Projected)" className="xl:col-span-2">
             <ResponsiveContainer width="100%" height="100%">
               <AreaChart data={trendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                 <defs>
                   <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                     <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                     <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                   </linearGradient>
                   <linearGradient id="colorForecast" x1="0" y1="0" x2="0" y2="1">
                     <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                     <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                   </linearGradient>
                 </defs>
                 <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.5} />
                 <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} dy={10} />
                 <YAxis axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} tickFormatter={(val) => `$${val/1000}k`} dx={-10} />
                 <Tooltip 
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', backgroundColor: isDark ? '#1e293b' : '#fff' }}
                    itemStyle={{ color: isDark ? '#fff' : '#1e293b' }}
                 />
                 <Legend verticalAlign="top" height={36} iconType="circle" />

                 {/* Forecast Line */}
                 <Area type="monotone" name="Forecast (Weighted)" dataKey="forecast" stroke="#10b981" strokeDasharray="5 5" strokeWidth={2} fillOpacity={1} fill="url(#colorForecast)" />

                 {/* Actuals Line */}
                 <Area type="monotone" name="Actual Revenue" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" />
               </AreaChart>
             </ResponsiveContainer>
          </ChartWidget>

          {/* Lead Source Distribution - Takes 1 col */}
          <ChartWidget title="Lead Source Distribution">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                    <Pie
                        data={pieData}
                        cx="50%"
                        cy="50%"
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                    >
                        {pieData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                        ))}
                    </Pie>
                    <Tooltip 
                        contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: isDark ? '#1e293b' : '#fff' }}
                        itemStyle={{ color: isDark ? '#fff' : '#1e293b' }}
                    />
                    <Legend 
                        layout="horizontal" 
                        verticalAlign="bottom" 
                        align="center"
                        iconType="circle"
                        wrapperStyle={{ paddingTop: '20px', fontSize: '12px' }}
                    />
                </PieChart>
             </ResponsiveContainer>
          </ChartWidget>
      </div>

      {/* Row 3: Secondary Charts & Lists */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">

          {/* Deal Stage Funnel */}
          <ChartWidget title="Opportunities by Stage">
             <ResponsiveContainer width="100%" height={250}>
                <BarChart data={barData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.3} />
                    <XAxis type="number" hide />
                    <YAxis dataKey="name" type="category" width={80} tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 11 }} axisLine={false} tickLine={false} />
                    <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px', backgroundColor: isDark ? '#1e293b' : '#fff' }} />
                    <Bar dataKey="count" fill="#10b981" radius={[0, 4, 4, 0]} barSize={20} />
                </BarChart>
             </ResponsiveContainer>
          </ChartWidget>

          {/* Top Opportunities List - Enhanced */}
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Top Opportunities</h3>
                  <IconTrendingUp className="w-5 h-5 text-emerald-500" />
              </div>
              <div className="space-y-3">
                  {topDeals.length > 0 ? topDeals.map((deal, idx) => (
                      <div key={deal.id} className="group flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700/50 hover:bg-white dark:hover:bg-slate-800 hover:shadow-md transition-all">
                          <div className="flex items-center gap-3">
                              <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold ${idx === 0 ? 'bg-amber-100 text-amber-600' : 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-400'}`}>
