  const wonDealsCount = deals.filter(d => d.stage === 'Closed Won').length;

  // --- Chart Data Preparation ---

  // 1. Lead Source Distribution (Pie)
  const leadSourceData = leads.reduce((acc, lead) => {
      const source = lead.leadSource || 'Other';
      acc[source] = (acc[source] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  const pieData = Object.keys(leadSourceData).map(key => ({ name: key, value: leadSourceData[key] }));

  // 2. Deal Stage Funnel (Bar)
  const stageDataRaw = deals.reduce((acc, deal) => {
      acc[deal.stage] = (acc[deal.stage] || 0) + 1;
