const Dashboard: React.FC<DashboardProps> = ({ leads, deals, isDark = true }) => {
  const [timeRange, setTimeRange] = useState<'7D' | '30D' | '3M' | 'YTD'>('30D');

  // --- Metrics Calculation ---

  // Helper to determine start date based on filter
  const startDate = useMemo(() => {
      const now = new Date();
      const d = new Date(now);
      switch (timeRange) {
          case '7D': d.setDate(now.getDate() - 7); break;
          case '30D': d.setDate(now.getDate() - 30); break;
          case '3M': d.setMonth(now.getMonth() - 3); break;
          case 'YTD': d.setMonth(0, 1); break; // Jan 1st of current year
      }
      return d;
  }, [timeRange]);

  const isAfterStart = (dateStr?: string) => {
      if (!dateStr) return false;
      return new Date(dateStr) >= startDate;
  };

  const getLeadDate = (lead: Lead) => {
      // Find 'created' activity or fallback to lastContact or just assume new if no date
      const createdAct = lead.activities?.find(a => a.type === 'created');
      if (createdAct) return new Date(createdAct.timestamp);
      // If we don't have a created date, for the sake of the mock dashboard showing data, 
      // we might rely on the fact that existing mocks are somewhat recent or fallback to a date.
      // In a real app, `createdTime` would be on the Lead object.
      return lead.lastContact ? new Date(lead.lastContact) : new Date(0); 
  };

  const newLeadsCount = leads.filter(l => getLeadDate(l) >= startDate).length;

  const wonDealsFiltered = deals.filter(d => d.stage === 'Closed Won' && isAfterStart(d.closeDate));
  const wonDealsCount = wonDealsFiltered.length;
  const totalRevenue = wonDealsFiltered.reduce((acc, curr) => acc + curr.value, 0);

  // Pipeline is usually a snapshot of "Now", so time filter applies less, but we can filter by 'updated recently' if we wanted.
  // For standard dashboards, Active Pipeline usually shows everything currently open.
  const activeDealsCount = deals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length;

  // --- Chart Data Preparation ---

  // 1. Lead Source Distribution (Pie) - Filtered by time range
  const leadSourceData = leads
    .filter(l => getLeadDate(l) >= startDate)
    .reduce((acc, lead) => {
        const source = lead.leadSource || 'Other';
        acc[source] = (acc[source] || 0) + 1;
        return acc;
    }, {} as Record<string, number>);

  const pieData = Object.keys(leadSourceData).length > 0 
    ? Object.keys(leadSourceData).map(key => ({ name: key, value: leadSourceData[key] }))
    : [{ name: 'No Data', value: 1 }]; // Placeholder if 0 to prevent crash

  // 2. Deal Stage Funnel (Bar) - Snapshot (All Active)
  const stageDataRaw = deals.reduce((acc, deal) => {
      acc[deal.stage] = (acc[deal.stage] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  const barData = Object.keys(stageDataRaw).map(stage => ({
      name: stage.length > 12 ? stage.substring(0, 10) + '...' : stage,
      fullName: stage,
      count: stageDataRaw[stage]
  })).sort((a,b) => b.count - a.count);

  // 3. Revenue Trend + Forecasting (Area + Line)
  // Dynamic generation based on timeRange
  const trendData = useMemo(() => {
      const data = [];
      const now = new Date();

      if (timeRange === '7D') {
          for (let i = 6; i >= 0; i--) {
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { weekday: 'short' });
              // Mocking "actual" data logic for demo purposes
              // In real app, aggregate deals closed on this day
              data.push({ 
                  name: label, 
                  actual: Math.floor(Math.random() * 15000), 
                  forecast: Math.floor(Math.random() * 10000) + 5000 
              });
          }
      } else if (timeRange === '30D') {
          for (let i = 29; i >= 0; i-=3) { // Step every 3 days to keep chart clean
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
              data.push({ 
                  name: label, 
                  actual: Math.floor(Math.random() * 40000), 
                  forecast: Math.floor(Math.random() * 30000) + 20000 
              });
          }
      } else {
          // 3M or YTD - Monthly view
          const monthsBack = timeRange === '3M' ? 2 : now.getMonth(); // 2 means current + prev 2
          for (let i = monthsBack; i >= 0; i--) {
              const d = new Date(now);
              d.setMonth(d.getMonth() - i);
              const label = d.toLocaleDateString('en-US', { month: 'short' });
              data.push({ 
                  name: label, 
                  actual: Math.floor(Math.random() * 150000), 
                  forecast: Math.floor(Math.random() * 180000) 
              });
          }
      }
      return data;
  }, [timeRange]);

  // 4. Top Opportunities (Table/List)
  const topDeals = [...deals]
    .filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage))
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);

  // 5. Recent Activity
  const allActivities = [
      ...leads.flatMap(lead => (lead.activities || []).map(act => ({ ...act, context: lead.name }))),
      ...deals.flatMap(deal => deal.activities.map(act => ({ ...act, context: deal.title })))
  ].filter(a => new Date(a.timestamp) >= startDate)
   .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
   .slice(0, 6);

  return (
    <div className="space-y-6 animate-slide-up pb-8">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-2 md:pr-20">
        <div>
            <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm mb-1 font-medium">
                <IconLayoutDashboard className="w-4 h-4" /> / Dashboard
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Business Overview</h1>
        </div>

        {/* Date Filter - Safe position to avoid overlap with top-right Notification bell */}
        <div className="flex items-center bg-white dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
            {(['7D', '30D', '3M', 'YTD'] as const).map((period) => (
                <button 
                    key={period}
                    onClick={() => setTimeRange(period)}
                    className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${
                        timeRange === period 
                        ? 'bg-primary-50 text-primary-600 dark:bg-primary-900/30 dark:text-primary-400 shadow-sm ring-1 ring-primary-500/20' 
                        : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700'
                    }`}
                >
                    {period}
                </button>
            ))}
        </div>
      </div>

      {/* Row 1: KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        <BIStatCard 
            title="New Leads" 
            value={newLeadsCount} 
            subtext={`Since ${startDate.toLocaleDateString()}`}
            trend="8%"
            icon={IconUsers} 
            colorClass="bg-gradient-to-br from-blue-500 to-blue-600" 
        />
        <BIStatCard 
            title="Active Pipeline" 
            value={activeDealsCount} 
            subtext="Total Open Deals" 
