} from './Icons';
import { RoleDefinition, Permission } from '../types';

interface SidebarProps {
  currentView: string;
  setView: (view: string) => void;
  isOpen: boolean;
  isDark: boolean;
  toggleTheme: () => void;
  userRole?: RoleDefinition;
  onLogout: () => void;
}

