      {/* Brand Header */}
      <div className={`flex items-center h-24 ${isCollapsed ? 'justify-center px-0' : 'px-8'} bg-[#0b1120] sticky top-0 z-10 transition-all duration-300 flex-shrink-0`}>
        <div className="relative group flex items-center justify-center">
            <div className="relative flex-shrink-0 flex items-center justify-center w-10 h-10 bg-gradient-to-br from-primary-600 to-indigo-600 rounded-xl shadow-lg shadow-primary-900/40">
                <IconSparkles className="w-5 h-5 text-white" />
            </div>
