export function App() {
  const [currentView, setCurrentView] = useState('dashboard');
  const [previousView, setPreviousView] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isDark, setIsDark] = useState(false);

  // Theme Settings
  const [primaryColor, setPrimaryColor] = useState('indigo');
  const [fontFamily, setFontFamily] = useState('Plus Jakarta Sans');
  const [density, setDensity] = useState('Medium');
  const [weekStart, setWeekStart] = useState('Sunday');
  const [dateFormat, setDateFormat] = useState('DD/MM/YYYY');
  const [timeZone, setTimeZone] = useState('UTC');
  const [timeFormat, setTimeFormat] = useState<'12h' | '24h'>('12h');
  const [workingDays, setWorkingDays] = useState<string[]>(['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
  const [fiscalYearStart, setFiscalYearStart] = useState('January');

  // Finance Settings
  const [defaultPaymentTerm, setDefaultPaymentTerm] = useState('Net 30');
  const [defaultTaxRate, setDefaultTaxRate] = useState(0);
  const [taxEnabled, setTaxEnabled] = useState(false);
  const [defaultCurrency, setDefaultCurrency] = useState('USD');
  const [multiCurrency, setMultiCurrency] = useState(false);

  // RBAC & Auth State
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [roles, setRoles] = useState<RoleDefinition[]>(DEFAULT_ROLES);
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]);

  // State for data
  const [leads, setLeads] = useState<Lead[]>(MOCK_LEADS);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);
  const [meetings, setMeetings] = useState<Meeting[]>(MOCK_MEETINGS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [accounts, setAccounts] = useState<Account[]>(MOCK_ACCOUNTS);
  const [calls, setCalls] = useState<Call[]>(MOCK_CALLS);
  const [campaigns, setCampaigns] = useState<Campaign[]>(MOCK_CAMPAIGNS);
  const [documents, setDocuments] = useState<Document[]>(MOCK_DOCUMENTS);
  const [visits, setVisits] = useState<Visit[]>(MOCK_VISITS);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);
  const [tickets, setTickets] = useState<Ticket[]>(MOCK_TICKETS);
  const [editingDocument, setEditingDocument] = useState<Document | null>(null);

  const [pipelineGoal, setPipelineGoal] = useState<number>(() => {
    const saved = localStorage.getItem('nova_pipeline_goal');
    return saved ? Number(saved) : 5000000;
  });

  // Calculate current user role for RBAC
  const userRole = roles.find(r => r.id === currentUser.roleId) || DEFAULT_ROLES[2];

  // Auth Initialization
  useEffect(() => {
    const initAuth = async () => {
      // Check if current token is valid
      if (authService.isAuthenticated()) {
        const user = authService.getCurrentUser();
        if (user) {
          setCurrentUser(user);
          setIsAuthenticated(true);
        }
      } else {
        // Try refresh token logic if implemented fully, or just logout
        const refreshedToken = await authService.refreshSession();
        if (refreshedToken) {
           const user = authService.getCurrentUser();
           if (user) {
             setCurrentUser(user);
             setIsAuthenticated(true);
           }
        }
      }
      setIsLoadingAuth(false);
    };
    initAuth();
  }, []);

  const handleLogin = async (email: string, password?: string): Promise<boolean> => {
    const response = await authService.login(email, password);
    if (response) {
      setCurrentUser(response.user);
      setIsAuthenticated(true);
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    authService.logout();
    setIsAuthenticated(false);
  };

  const handleSetPipelineGoal = (goal: number) => {
    setPipelineGoal(goal);
    localStorage.setItem('nova_pipeline_goal', goal.toString());
  };

  const handleNavigateToTasks = () => {
    setCurrentView('tasks');
  };

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  useEffect(() => {
    const root = document.documentElement;
    const themeColors = THEMES[primaryColor] || THEMES.indigo;

    Object.keys(themeColors).forEach((key) => {
      root.style.setProperty(`--color-primary-${key}`, themeColors[Number(key)]);
    });

    const fontMap: Record<string, string> = {
      'Plus Jakarta Sans': "'Plus Jakarta Sans', sans-serif",
      'Inter UI': "'Inter', sans-serif",
      'Montserrat': "'Montserrat', sans-serif",
      'Outfit': "'Outfit', sans-serif",
      'Lexend': "'Lexend', sans-serif",
      'Playfair': "'Playfair Display', serif",
    };
    root.style.setProperty('--font-family', fontMap[fontFamily] || "'Inter', sans-serif");

    const sizeMap: Record<string, string> = {
      'Small': '14px',
      'Medium': '16px',
      'Large': '17px',
      'XL': '18px'
    };
    root.style.setProperty('--base-font-size', sizeMap[density] || '16px');
    root.style.fontSize = sizeMap[density] || '16px';

  }, [primaryColor, fontFamily, density]);

  const toggleTheme = () => setIsDark(!isDark);

  // Data Handlers
  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50,
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: currentUser.name,
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    } as Contact;
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddAccount = (newAccount: Account) => {
    setAccounts(prevAccounts => [...prevAccounts, newAccount]);
  };

  const handleUpdateAccount = (updatedAccount: Account) => {
    setAccounts(prevAccounts => prevAccounts.map(a => 
      a.id === updatedAccount.id ? updatedAccount : a
    ));
  };

  const handleDeleteAccount = (accountId: string) => {
    setAccounts(prevAccounts => prevAccounts.filter(a => a.id !== accountId));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddMeeting = (newMeeting: Meeting) => {
    setMeetings(prev => [...prev, newMeeting]);
  };

  const handleUpdateMeeting = (updatedMeeting: Meeting) => {
    setMeetings(prev => prev.map(m => m.id === updatedMeeting.id ? updatedMeeting : m));
  };

  const handleDeleteMeeting = (meetingId: string) => {
    setMeetings(prev => prev.filter(m => m.id !== meetingId));
  };

  const handleAddDeal = (newDeal: Deal) => {
    const activities = newDeal.activities && newDeal.activities.length > 0 
      ? newDeal.activities 
      : [{
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }];

    const dealWithActivity = {
      ...newDeal,
      activities
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({ id: Date.now().toString() + 's', type: 'stage_change', description: `Stage updated to ${updatedDeal.stage}`, timestamp });
      }
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({ id: Date.now().toString() + 'v', type: 'value_change', description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`, timestamp });
      }
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({ id: Date.now().toString() + 'p', type: 'probability_change', description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`, timestamp });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);
      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({ id: Date.now().toString() + 'u', type: 'update', description: `Deal details updated`, timestamp });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const handleAddTask = (newTask: Task) => {
    setTasks(prev => [newTask, ...prev]);
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const handleAddCampaign = (newCampaign: Campaign) => {
    setCampaigns(prev => [...prev, newCampaign]);
  };

  const handleUpdateCampaign = (updatedCampaign: Campaign) => {
    setCampaigns(prev => prev.map(c => c.id === updatedCampaign.id ? updatedCampaign : c));
  };

  const handleDeleteCampaign = (campaignId: string) => {
    setCampaigns(prev => prev.filter(c => c.id !== campaignId));
  };

  const handleAddDocument = (newDoc: Document) => {
    setDocuments(prev => [newDoc, ...prev]);
  };

  const handleDeleteDocument = (docId: string) => {
    setDocuments(prev => prev.filter(d => d.id !== docId));
  };

  const handleUpdateDocument = (updatedDoc: Document) => {
    setDocuments(prev => prev.map(d => d.id === updatedDoc.id ? updatedDoc : d));
  };

  const handleAddVisit = (newVisit: Visit) => {
    setVisits(prev => [newVisit, ...prev]);
  };

  const handleUpdateVisit = (updatedVisit: Visit) => {
    setVisits(prev => prev.map(v => v.id === updatedVisit.id ? updatedVisit : v));
  };

  const handleDeleteVisit = (visitId: string) => {
    setVisits(prev => prev.filter(v => v.id !== visitId));
  };

  const handleAddProject = (newProject: Project) => {
    setProjects(prev => [...prev, newProject]);
  };

  const handleUpdateProject = (updatedProject: Project) => {
    setProjects(prev => prev.map(p => p.id === updatedProject.id ? updatedProject : p));
  };

  const handleDeleteProject = (projectId: string) => {
    setProjects(prev => prev.filter(p => p.id !== projectId));
  };

  const handleAddTicket = (newTicket: Ticket) => {
    setTickets(prev => [...prev, newTicket]);
  };

  const handleUpdateTicket = (updatedTicket: Ticket) => {
    setTickets(prev => prev.map(t => t.id === updatedTicket.id ? updatedTicket : t));
  };

  const handleDeleteTicket = (ticketId: string) => {
    setTickets(prev => prev.filter(t => t.id !== ticketId));
  };

  // Handler to open the document editor
  const handleEditDocument = (doc: Document) => {
      setEditingDocument(doc);
      setPreviousView(currentView);
      setCurrentView('document-editor');
  };

  const handleCloseEditor = () => {
      setEditingDocument(null);
      setCurrentView(previousView); // Return to where we came from
  };

  const renderContent = () => {
    // Permission Access Control Check
    const requiredPerm = VIEW_PERMISSIONS[currentView];
    if (requiredPerm && !userRole.permissions.includes(requiredPerm)) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-center p-8 animate-fade-in">
                <div className="p-4 bg-slate-100 dark:bg-slate-800 rounded-full mb-4">
                    <IconLock className="w-12 h-12 text-slate-400" />
                </div>
                <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">Access Denied</h2>
                <p className="text-slate-500 dark:text-slate-400 max-w-md mb-6">
                    You do not have permission to view this module. Please contact your administrator if you believe this is an error.
                </p>
                <button 
                    onClick={() => setCurrentView('dashboard')}
                    className="px-6 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg font-medium transition-colors"
                >
                    Return to Dashboard
                </button>
            </div>
        );
    }

    switch (currentView) {
      case 'dashboard':
        return <Dashboard 
            leads={leads} 
            deals={deals} 
            tasks={tasks} 
            meetings={meetings} 
            isDark={isDark} 
            pipelineGoal={pipelineGoal}
            userRole={userRole} 
        />;
      case 'leads':
        return <Leads 
            leads={leads}
            accounts={accounts} 
            contacts={contacts}
            onAddLead={handleAddLead} 
            onUpdateLead={handleUpdateLead} 
            onDeleteLeads={handleDeleteLeads} 
            onAddDeal={handleAddDeal} 
            onViewOpportunities={() => setCurrentView('pipeline')}
            onAddDocument={handleAddDocument}
            documents={documents}
            onUpdateDocument={handleUpdateDocument}
            onDeleteDocument={handleDeleteDocument}
            onEditDocument={handleEditDocument} 
            calls={calls}
            onAddCall={handleAddCall}
            userRole={userRole}
        />;
      case 'pipeline':
        return <Pipeline 
            deals={deals}
            accounts={accounts}
            contacts={contacts}
            onAddDeal={handleAddDeal} 
            onUpdateDeal={handleUpdateDeal} 
            pipelineGoal={pipelineGoal} 
            onSetGoal={handleSetPipelineGoal} 
        />;
      case 'tasks':
        return <Tasks tasks={tasks} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />;
      case 'meetings':
        return <Meetings 
          meetings={meetings} 
          contacts={contacts}
          accounts={accounts}
          onAddMeeting={handleAddMeeting} 
          onUpdateMeeting={handleUpdateMeeting} 
          onDeleteMeeting={handleDeleteMeeting}
        />;
      case 'contacts':
        return <Contacts 
          contacts={contacts} 
          accounts={accounts}
          onAddContact={handleAddContact} 
          onUpdateContact={handleUpdateContact} 
        />;
      case 'accounts':
        return <Accounts 
          accounts={accounts} 
          contacts={contacts} 
          deals={deals}
          leads={leads}
          meetings={meetings}
          calls={calls}
          onAddAccount={handleAddAccount} 
          onUpdateAccount={handleUpdateAccount} 
          onDeleteAccount={handleDeleteAccount}
          onAddContact={handleAddContact}
          onAddCall={handleAddCall}
          onAddDocument={handleAddDocument}
          onEditDocument={handleEditDocument}
        />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} accounts={accounts} onAddCall={handleAddCall} />;
      case 'campaigns': 
        return <Campaigns 
          campaigns={campaigns} 
          onAddCampaign={handleAddCampaign} 
          onUpdateCampaign={handleUpdateCampaign} 
          onDeleteCampaign={handleDeleteCampaign} 
        />;
      case 'documents':
        return <Documents 
          documents={documents}
          onAddDocument={handleAddDocument}
          onUpdateDocument={handleUpdateDocument}
          onDeleteDocument={handleDeleteDocument}
          onEditDocument={handleEditDocument}
        />;
      case 'templates':
        return <Templates />;
      case 'document-editor':
        return editingDocument ? (
            <DocumentEditor 
                document={editingDocument}
                onSave={(updatedDoc) => {
                    handleUpdateDocument(updatedDoc);
                    handleCloseEditor();
                }}
                onClose={handleCloseEditor}
            />
        ) : <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} userRole={userRole} />;
      case 'settings':
        return <Settings 
          isDark={isDark} 
          toggleTheme={toggleTheme} 
          primaryColor={primaryColor} 
          setPrimaryColor={setPrimaryColor} 
          pipelineGoal={pipelineGoal}
          setPipelineGoal={handleSetPipelineGoal}
          fontFamily={fontFamily}
          setFontFamily={setFontFamily}
          density={density}
          setDensity={setDensity}
          weekStart={weekStart}
          setWeekStart={setWeekStart}
          dateFormat={dateFormat}
          setDateFormat={setDateFormat}
          timeZone={timeZone}
          setTimeZone={setTimeZone}
          timeFormat={timeFormat}
          setTimeFormat={setTimeFormat}
          workingDays={workingDays}
          setWorkingDays={setWorkingDays}
          fiscalYearStart={fiscalYearStart}
          setFiscalYearStart={setFiscalYearStart}
          // Finance
          defaultPaymentTerm={defaultPaymentTerm}
          setDefaultPaymentTerm={setDefaultPaymentTerm}
          defaultTaxRate={defaultTaxRate}
          setDefaultTaxRate={setDefaultTaxRate}
          taxEnabled={taxEnabled}
          setTaxEnabled={setTaxEnabled}
          defaultCurrency={defaultCurrency}
          setDefaultCurrency={setDefaultCurrency}
          multiCurrency={multiCurrency}
          setMultiCurrency={setMultiCurrency}
          // RBAC
          roles={roles}
          setRoles={setRoles}
          users={users}
          setUsers={setUsers}
          currentUser={currentUser}
          setCurrentUser={setCurrentUser}
        />;
      case 'visits': 
        return <Visits 
          visits={visits}
          accounts={accounts}
          onAddVisit={handleAddVisit}
          onUpdateVisit={handleUpdateVisit}
          onDeleteVisit={handleDeleteVisit}
        />;
      case 'projects': 
        return <Projects
          projects={projects}
          onAddProject={handleAddProject}
          onUpdateProject={handleUpdateProject}
          onDeleteProject={handleDeleteProject}
        />;
      case 'support':
        return <Support 
          tickets={tickets}
          accounts={accounts}
          onAddTicket={handleAddTicket}
          onUpdateTicket={handleUpdateTicket}
          onDeleteTicket={handleDeleteTicket}
        />;
      default: return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} userRole={userRole} />;
    }
  };

  if (isLoadingAuth) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-900 text-white">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-white"></div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Auth onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-primary-500/30 transition-colors duration-300">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Hide Sidebar when editing document to use full screen */}
      {currentView !== 'document-editor' && (
          <Sidebar 
            currentView={currentView} 
            setView={(view) => { setCurrentView(view); setSidebarOpen(false); }} 
            isOpen={sidebarOpen}
            isDark={isDark}
            toggleTheme={toggleTheme}
            userRole={userRole} // Pass RBAC role
            onLogout={handleLogout}
          />
      )}

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <div className="absolute inset-0 z-0 pointer-events-none bg-grid-pattern dark:bg-grid-pattern-dark bg-grid opacity-[0.03] dark:opacity-[0.05]"></div>

        {currentView !== 'document-editor' && (
            <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300 z-10">
            <div className="flex items-center">
                <button onClick={() => setSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
                <IconMenu className="w-6 h-6" />
                </button>
                <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
            </div>
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </header>
        )}

        {currentView !== 'settings' && currentView !== 'document-editor' && (
            <div className="hidden md:block absolute top-6 right-8 z-20">
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </div>
        )}

        <main className={`flex-1 overflow-x-hidden overflow-y-auto bg-transparent relative z-0 ${currentView === 'document-editor' ? '' : 'p-4 md:p-8 pt-4 md:pt-8 custom-scrollbar'}`}>
          {renderContent()}
        </main>

        {currentView !== 'document-editor' && <AIChat leads={leads} deals={deals} />}
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Lead, Deal, Task, Meeting, Activity, RoleDefinition } from '../types';
import { 
    IconUsers, 
    IconKanban, 
    IconHistory, 
    IconSparkles, 
    IconCheckCircle, 
    IconActivity, 
    IconTrendingUp, 
    IconWallet, 
    IconLayoutDashboard,
    IconArrowUp,
    IconLock
} from './Icons';
import { 
    AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, PieChart, Pie, Cell, Legend
} from 'recharts';

interface DashboardProps {
  leads: Lead[];
  deals: Deal[];
  tasks: Task[];
  meetings: Meeting[];
  isDark?: boolean;
  pipelineGoal?: number;
  userRole?: RoleDefinition;
}

const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

const BIStatCard = ({ title, value, subtext, icon: Icon, colorClass, trend }: { title: string, value: string | number, subtext?: string, icon: any, colorClass: string, trend?: string }) => (
    <div className={`p-6 rounded-2xl shadow-sm text-white relative overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:shadow-lg ${colorClass}`}>
        {/* Background Circles for decoration */}
        <div className="absolute -right-6 -top-6 w-24 h-24 rounded-full bg-white/10 blur-xl"></div>
        <div className="absolute -left-6 -bottom-6 w-20 h-20 rounded-full bg-black/5 blur-lg"></div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h3 className="text-xs font-bold uppercase tracking-wider opacity-90 mb-1">{title}</h3>
                <p className="text-3xl font-bold tracking-tight">{value}</p>
                {subtext && (
                    <div className="flex items-center gap-2 mt-2">
                        {trend && <span className="bg-white/20 px-1.5 py-0.5 rounded text-[10px] font-bold flex items-center"><IconArrowUp className="w-2.5 h-2.5 mr-0.5" />{trend}</span>}
                        <p className="text-xs opacity-80 font-medium">{subtext}</p>
                    </div>
                )}
            </div>
            <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm shadow-inner">
                <Icon className="w-6 h-6 text-white" />
            </div>
        </div>
    </div>
);

const ChartWidget = ({ title, children, className = "" }: { title: string, children?: React.ReactNode, className?: string }) => (
    <div className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col ${className}`}>
        <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">{title}</h3>
            <button className="text-slate-400 hover:text-primary-500 transition-colors">
                <IconSparkles className="w-4 h-4" />
            </button>
        </div>
        <div className="flex-1 w-full min-h-[250px]">
            {children}
        </div>
    </div>
);

const ActivityItem: React.FC<{ activity: Activity & { context: string }, isLast: boolean }> = ({ activity, isLast }) => {
    return (
        <div className="flex group relative pl-2">
            {!isLast && <div className="absolute left-[19px] top-8 bottom-0 w-px bg-slate-100 dark:bg-slate-800 group-hover:bg-indigo-100 dark:group-hover:bg-indigo-900/30 transition-colors"></div>}

            <div className="flex-shrink-0 mr-4 pt-1">
                <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center shadow-sm z-10 relative bg-white dark:bg-slate-900 ${
                    activity.type === 'stage_change' ? 'border-blue-200 text-blue-500' :
                    activity.type === 'created' ? 'border-emerald-200 text-emerald-500' :
                    'border-slate-200 text-slate-400'
                }`}>
                    <div className={`w-2 h-2 rounded-full ${
                         activity.type === 'stage_change' ? 'bg-blue-500' :
                         activity.type === 'created' ? 'bg-emerald-500' :
                         'bg-slate-400'
                    }`}></div>
                </div>
            </div>
            <div className="pb-6 pt-1.5 w-full">
                <div className="flex justify-between items-start">
                    <p className="text-sm font-medium text-slate-700 dark:text-slate-200 mb-0.5">
                        <span className="font-bold">{activity.context}</span>: {activity.description}
                    </p>
                </div>
                <span className="text-xs text-slate-400 dark:text-slate-500 flex items-center gap-1">
                    <IconHistory className="w-3 h-3" />
                    {new Date(activity.timestamp).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                </span>
            </div>
        </div>
    );
};

const Dashboard: React.FC<DashboardProps> = ({ leads, deals, isDark = true, userRole }) => {
  const [timeRange, setTimeRange] = useState<'7D' | '30D' | '3M' | 'YTD'>('30D');

  const canViewRevenue = userRole ? userRole.permissions.includes('view_revenue') : true;

  // --- Metrics Calculation ---

  // Helper to determine start date based on filter
  const startDate = useMemo(() => {
      const now = new Date();
      const d = new Date(now);
      switch (timeRange) {
          case '7D': d.setDate(now.getDate() - 7); break;
          case '30D': d.setDate(now.getDate() - 30); break;
          case '3M': d.setMonth(now.getMonth() - 3); break;
          case 'YTD': d.setMonth(0, 1); break; // Jan 1st of current year
      }
      return d;
  }, [timeRange]);

  const isAfterStart = (dateStr?: string) => {
      if (!dateStr) return false;
      return new Date(dateStr) >= startDate;
  };

  const getLeadDate = (lead: Lead) => {
      // Find 'created' activity or fallback to lastContact or just assume new if no date
      const createdAct = lead.activities?.find(a => a.type === 'created');
      if (createdAct) return new Date(createdAct.timestamp);
      // If we don't have a created date, for the sake of the mock dashboard showing data, 
      // we might rely on the fact that existing mocks are somewhat recent or fallback to a date.
      // In a real app, `createdTime` would be on the Lead object.
      return lead.lastContact ? new Date(lead.lastContact) : new Date(0); 
  };

  const newLeadsCount = leads.filter(l => getLeadDate(l) >= startDate).length;

  const wonDealsFiltered = deals.filter(d => d.stage === 'Closed Won' && isAfterStart(d.closeDate));
  const wonDealsCount = wonDealsFiltered.length;
  const totalRevenue = wonDealsFiltered.reduce((acc, curr) => acc + curr.value, 0);

  // Pipeline is usually a snapshot of "Now", so time filter applies less, but we can filter by 'updated recently' if we wanted.
  // For standard dashboards, Active Pipeline usually shows everything currently open.
  const activeDealsCount = deals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length;

  // --- Chart Data Preparation ---

  // 1. Lead Source Distribution (Pie) - Filtered by time range
  const leadSourceData = leads
    .filter(l => getLeadDate(l) >= startDate)
    .reduce((acc, lead) => {
        const source = lead.leadSource || 'Other';
        acc[source] = (acc[source] || 0) + 1;
        return acc;
    }, {} as Record<string, number>);

  const pieData = Object.keys(leadSourceData).length > 0 
    ? Object.keys(leadSourceData).map(key => ({ name: key, value: leadSourceData[key] }))
    : [{ name: 'No Data', value: 1 }]; // Placeholder if 0 to prevent crash

  // 2. Deal Stage Funnel (Bar) - Snapshot (All Active)
  const stageDataRaw = deals.reduce((acc, deal) => {
      acc[deal.stage] = (acc[deal.stage] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  const barData = Object.keys(stageDataRaw).map(stage => ({
      name: stage.length > 12 ? stage.substring(0, 10) + '...' : stage,
      fullName: stage,
      count: stageDataRaw[stage]
  })).sort((a,b) => b.count - a.count);

  // 3. Revenue Trend + Forecasting (Area + Line)
  // Dynamic generation based on timeRange
  const trendData = useMemo(() => {
      const data = [];
      const now = new Date();

      if (timeRange === '7D') {
          for (let i = 6; i >= 0; i--) {
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { weekday: 'short' });
              // Mocking "actual" data logic for demo purposes
              // In real app, aggregate deals closed on this day
              data.push({ 
                  name: label, 
                  actual: Math.floor(Math.random() * 15000), 
                  forecast: Math.floor(Math.random() * 10000) + 5000 
              });
          }
      } else if (timeRange === '30D') {
          for (let i = 29; i >= 0; i-=3) { // Step every 3 days to keep chart clean
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
              data.push({ 
                  name: label, 
                  actual: Math.floor(Math.random() * 40000), 
                  forecast: Math.floor(Math.random() * 30000) + 20000 
              });
          }
      } else {
          // 3M or YTD - Monthly view
          const monthsBack = timeRange === '3M' ? 2 : now.getMonth(); // 2 means current + prev 2
          for (let i = monthsBack; i >= 0; i--) {
              const d = new Date(now);
              d.setMonth(d.getMonth() - i);
              const label = d.toLocaleDateString('en-US', { month: 'short' });
              data.push({ 
                  name: label, 
                  actual: Math.floor(Math.random() * 150000), 
                  forecast: Math.floor(Math.random() * 180000) 
              });
          }
      }
      return data;
  }, [timeRange]);

  // 4. Top Opportunities (Table/List)
  const topDeals = [...deals]
    .filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage))
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);

  // 5. Recent Activity
  const allActivities = [
      ...leads.flatMap(lead => (lead.activities || []).map(act => ({ ...act, context: lead.name }))),
      ...deals.flatMap(deal => deal.activities.map(act => ({ ...act, context: deal.title })))
  ].filter(a => new Date(a.timestamp) >= startDate)
   .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
   .slice(0, 6);

  return (
    <div className="space-y-6 animate-slide-up pb-8">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-2 md:pr-20">
        <div>
            <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm mb-1 font-medium">
                <IconLayoutDashboard className="w-4 h-4" /> / Dashboard
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Business Overview</h1>
        </div>

        {/* Date Filter - Safe position to avoid overlap with top-right Notification bell */}
        <div className="flex items-center bg-white dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
            {(['7D', '30D', '3M', 'YTD'] as const).map((period) => (
                <button 
                    key={period}
                    onClick={() => setTimeRange(period)}
                    className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${
                        timeRange === period 
                        ? 'bg-primary-50 text-primary-600 dark:bg-primary-900/30 dark:text-primary-400 shadow-sm ring-1 ring-primary-500/20' 
                        : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700'
                    }`}
                >
                    {period}
                </button>
            ))}
        </div>
      </div>

      {/* Row 1: KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        <BIStatCard 
            title="New Leads" 
            value={newLeadsCount} 
            subtext={`Since ${startDate.toLocaleDateString()}`}
            trend="8%"
            icon={IconUsers} 
            colorClass="bg-gradient-to-br from-blue-500 to-blue-600" 
        />
        <BIStatCard 
            title="Active Pipeline" 
            value={activeDealsCount} 
            subtext="Total Open Deals" 
            icon={IconKanban} 
            colorClass="bg-gradient-to-br from-emerald-400 to-emerald-600" 
        />

        {/* Financial Cards - Conditional Rendering based on Permission */}
        {canViewRevenue ? (
            <>
                <BIStatCard 
                    title="Won Deals" 
                    value={wonDealsCount} 
                    subtext="In Selected Period" 
                    trend="15%"
                    icon={IconCheckCircle} 
                    colorClass="bg-gradient-to-br from-rose-400 to-rose-600" 
                />
                <BIStatCard 
                    title="Revenue" 
                    value={`$${(totalRevenue / 1000).toFixed(1)}k`} 
                    subtext="Closed Won" 
                    trend="12%"
                    icon={IconWallet} 
                    colorClass="bg-gradient-to-br from-indigo-500 to-purple-600" 
                />
            </>
        ) : (
            <>
                <div className="p-6 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex flex-col items-center justify-center text-center opacity-70">
                    <IconLock className="w-8 h-8 text-slate-400 mb-2" />
                    <p className="text-sm font-medium text-slate-500">Won Deals Hidden</p>
                </div>
                <div className="p-6 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex flex-col items-center justify-center text-center opacity-70">
                    <IconLock className="w-8 h-8 text-slate-400 mb-2" />
                    <p className="text-sm font-medium text-slate-500">Revenue Hidden</p>
                </div>
            </>
        )}
      </div>

      {/* Row 2: Main Charts */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
          {/* Revenue Trend - Takes 2 cols */}
          <ChartWidget title={`Revenue Forecast (${timeRange})`} className="xl:col-span-2">
             {canViewRevenue ? (
                 <ResponsiveContainer width="100%" height="100%">
                   <AreaChart data={trendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                     <defs>
                       <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                         <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                         <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                       </linearGradient>
                       <linearGradient id="colorForecast" x1="0" y1="0" x2="0" y2="1">
                         <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                         <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                       </linearGradient>
                     </defs>
                     <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.5} />
                     <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} dy={10} />
                     <YAxis axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} tickFormatter={(val) => `$${val/1000}k`} dx={-10} />
                     <Tooltip 
                        contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', backgroundColor: isDark ? '#1e293b' : '#fff' }}
                        itemStyle={{ color: isDark ? '#fff' : '#1e293b' }}
                     />
                     <Legend verticalAlign="top" height={36} iconType="circle" />

                     {/* Forecast Line */}
                     <Area type="monotone" name="Forecast (Weighted)" dataKey="forecast" stroke="#10b981" strokeDasharray="5 5" strokeWidth={2} fillOpacity={1} fill="url(#colorForecast)" />

                     {/* Actuals Line */}
                     <Area type="monotone" name="Actual Revenue" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" />
                   </AreaChart>
                 </ResponsiveContainer>
             ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-400">
                     <IconLock className="w-12 h-12 mb-4 opacity-20" />
                     <p>Revenue data is restricted for your role.</p>
                 </div>
             )}
          </ChartWidget>

          {/* Lead Source Distribution - Takes 1 col */}
          <ChartWidget title="Lead Source">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                    <Pie
                        data={pieData}
                        cx="50%"
                        cy="50%"
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                    >
                        {pieData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                        ))}
                    </Pie>
                    <Tooltip 
                        contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: isDark ? '#1e293b' : '#fff' }}
                        itemStyle={{ color: isDark ? '#fff' : '#1e293b' }}
                    />
                    <Legend 
                        layout="horizontal" 
                        verticalAlign="bottom" 
                        align="center"
                        iconType="circle"
                        wrapperStyle={{ paddingTop: '20px', fontSize: '12px' }}
                    />
                </PieChart>
             </ResponsiveContainer>
          </ChartWidget>
      </div>

      {/* Row 3: Secondary Charts & Lists */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">

          {/* Deal Stage Funnel */}
          <ChartWidget title="Opportunities by Stage">
             <ResponsiveContainer width="100%" height={250}>
                <BarChart data={barData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.3} />
                    <XAxis type="number" hide />
                    <YAxis dataKey="name" type="category" width={80} tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 11 }} axisLine={false} tickLine={false} />
                    <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px', backgroundColor: isDark ? '#1e293b' : '#fff' }} />
                    <Bar dataKey="count" fill="#10b981" radius={[0, 4, 4, 0]} barSize={20} />
                </BarChart>
             </ResponsiveContainer>
          </ChartWidget>

          {/* Top Opportunities List - Enhanced */}
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Top Opportunities</h3>
                  <IconTrendingUp className="w-5 h-5 text-emerald-500" />
              </div>
              <div className="space-y-3">
                  {topDeals.length > 0 ? topDeals.map((deal, idx) => (
                      <div key={deal.id} className="group flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700/50 hover:bg-white dark:hover:bg-slate-800 hover:shadow-md transition-all">
                          <div className="flex items-center gap-3">
                              <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold ${idx === 0 ? 'bg-amber-100 text-amber-600' : 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-400'}`}>
                                  {idx + 1}
                              </div>
                              <div>
                                  <p className="font-semibold text-sm text-slate-900 dark:text-white truncate max-w-[120px]" title={deal.title}>{deal.title}</p>
                                  <p className="text-xs text-slate-500">{deal.company}</p>
                              </div>
                          </div>
                          {canViewRevenue ? (
                              <div className="text-right">
                                  <p className="font-bold text-slate-900 dark:text-white text-sm">${deal.value.toLocaleString()}</p>
                                  <div className="flex items-center justify-end gap-1 mt-1">
                                    <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                                        <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${deal.probability}%` }}></div>
                                    </div>
                                    <span className="text-[10px] text-slate-500">{deal.probability}%</span>
                                  </div>
                              </div>
                          ) : (
                              <div className="text-right">
                                  <IconLock className="w-4 h-4 text-slate-400" />
                              </div>
                          )}
                      </div>
                  )) : (
                      <div className="text-center text-slate-500 text-sm py-8">No open opportunities found.</div>
                  )}
              </div>
          </div>

          {/* Recent Activity */}
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col">
              <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Activity Feed</h3>
                  <IconActivity className="w-5 h-5 text-blue-500" />
              </div>
              <div className="overflow-y-auto flex-1 custom-scrollbar -mr-2 pr-2">
                  {allActivities.length > 0 ? allActivities.map((act, index) => (
                      <ActivityItem 
                          key={act.id} 
                          activity={act} 
                          isLast={index === allActivities.length - 1}
                      />
                  )) : (
                      <div className="flex flex-col items-center justify-center h-40 text-slate-500">
                          <IconSparkles className="w-8 h-8 mb-2 opacity-20" />
                          <p className="text-sm">No recent activity.</p>
                      </div>
                  )}
              </div>
          </div>

      </div>
    </div>
  );
};

