                                        type="text" 
                                        value={newRoleName}
                                        onChange={e => setNewRoleName(e.target.value)}
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500"
                                        placeholder="e.g. Marketing Manager"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Description</label>
                                    <textarea 
                                        value={newRoleDescription}
                                        onChange={e => setNewRoleDescription(e.target.value)}
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500 resize-none h-24"
                                        placeholder="Describe the access level for this role..."
                                    />
                                </div>
                                <div className="pt-4 flex gap-3">
                                    <button 
                                        onClick={() => setIsCreateRoleModalOpen(false)}
                                        className="flex-1 px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg font-medium transition-colors"
                                    >
                                        Cancel
                                    </button>
                                    <button 
                                        onClick={handleCreateRole}
                                        disabled={!newRoleName.trim()}
                                        className="flex-1 px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary-500/20"
                                    >
                                        Create Role
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {passwordModalOpen && selectedUserForPassword && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                        <div className="w-full max-w-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl p-6 animate-scale-in text-center">
                            <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
                                <IconKey className="w-8 h-8 text-emerald-600 dark:text-emerald-400" />
                            </div>
                            <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">Password Reset</h3>
                            <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">
                                Temporary password generated for <strong>{selectedUserForPassword.name}</strong>
                            </p>

                            <div className="bg-slate-100 dark:bg-slate-800 p-3 rounded-lg border border-slate-200 dark:border-slate-700 mb-6 flex items-center justify-between">
                                <code className="font-mono text-lg font-bold text-slate-800 dark:text-slate-200 tracking-wide">{generatedPassword}</code>
                                <button onClick={() => copyToClipboard(generatedPassword)} className="text-primary-600 hover:text-primary-700 dark:text-primary-400 p-1">
                                    <IconCopy className="w-5 h-5" />
                                </button>
                            </div>

                            <button 
                                onClick={() => setPasswordModalOpen(false)}
                                className="w-full px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-lg font-bold hover:opacity-90 transition-opacity"
                            >
                                Done
                            </button>
                        </div>
                    </div>
                )}
            </div>
        );

      // Other cases (company, theme, etc.) remain the same...
      default:
        return <div className="text-slate-500">Select a category</div>;
    }
  };

  const navItemClass = (id: string) => `
    w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 
    ${activeTab === id 
        ? 'bg-primary-50 text-primary-700 dark:bg-primary-900/20 dark:text-primary-400 shadow-sm' 
        : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
  `;

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-[#0f172a] overflow-hidden">
        <div className="px-8 py-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center sticky top-0 z-10">
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight">Command Center</h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Configure core logic, branding, and regulatory compliance.</p>
            </div>
            <button 
                onClick={handleSave}
                className={`flex items-center gap-2 px-6 py-2.5 font-bold text-sm rounded-lg shadow-lg transition-all active:translate-y-0 hover:-translate-y-0.5 ${isSaved ? 'bg-emerald-500 text-white shadow-emerald-500/30' : 'bg-primary-600 hover:bg-primary-500 text-white shadow-primary-500/30'}`}
            >
                {isSaved ? <IconCheckCircle className="w-4 h-4" /> : <IconSave className="w-4 h-4" />}
                {isSaved ? 'SETTINGS SAVED' : 'UPDATE GLOBAL SETTINGS'}
            </button>
        </div>

        <div className="flex flex-1 overflow-hidden p-8 max-w-7xl mx-auto w-full gap-8">
            <div className="w-64 flex-shrink-0">
                <nav className="space-y-1">
                    <button onClick={() => setActiveTab('team')} className={navItemClass('team')}>
                        <IconUsers className="w-5 h-5 mr-3 opacity-70" />
                        Team & Roles
                    </button>
                    <button onClick={() => setActiveTab('company')} className={navItemClass('company')}>
                        <IconBuilding className="w-5 h-5 mr-3 opacity-70" />
                        Company Profile
                    </button>
                    <button onClick={() => setActiveTab('theme')} className={navItemClass('theme')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Theme & Brand
                    </button>
                    <button onClick={() => setActiveTab('regional')} className={navItemClass('regional')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Regional & Date
                    </button>
                    <button onClick={() => setActiveTab('finance')} className={navItemClass('finance')}>
                        <IconWallet className="w-5 h-5 mr-3 opacity-70" />
                        Financial Config
                    </button>
                    <button onClick={() => setActiveTab('ai')} className={navItemClass('ai')}>
                        <IconSparkles className="w-5 h-5 mr-3 opacity-70" />
                        AI & Automation
                    </button>
                    <button onClick={() => setActiveTab('notifications')} className={navItemClass('notifications')}>
                        <IconBell className="w-5 h-5 mr-3 opacity-70" />
                        Alerts & Email
                    </button>
                    <button onClick={() => setActiveTab('security')} className={navItemClass('security')}>
                        <IconShield className="w-5 h-5 mr-3 opacity-70" />
                        Security & Access
                    </button>
                </nav>
            </div>

            <div className="flex-1 bg-transparent overflow-y-auto custom-scrollbar">
                {renderContent()}
            </div>
        </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { 
  IconUser, 
  IconBuilding, 
  IconGlobe, 
  IconSparkles, 
  IconBell, 
  IconShield, 
  IconSave,
  IconCheckCircle,
  IconPlus,
  IconTrash,
  IconWallet,
  IconLock,
  IconUsers,
  IconKey,
  IconCopy,
  IconX
} from './Icons';
import { RoleDefinition, User, Permission } from '../types';

interface SettingsProps {
  isDark: boolean;
  toggleTheme: () => void;
  primaryColor: string;
  setPrimaryColor: (color: string) => void;
  pipelineGoal: number;
  setPipelineGoal: (goal: number) => void;
  // Theme Props
  fontFamily: string;
  setFontFamily: (font: string) => void;
  density: string;
  setDensity: (density: string) => void;
  // Regional Props
  weekStart: string;
  setWeekStart: (day: string) => void;
  dateFormat: string;
  setDateFormat: (format: string) => void;
  timeZone: string;
  setTimeZone: (tz: string) => void;
  timeFormat: '12h' | '24h';
  setTimeFormat: (format: '12h' | '24h') => void;
  workingDays: string[];
  setWorkingDays: (days: string[]) => void;
  fiscalYearStart: string;
  setFiscalYearStart: (month: string) => void;
  // Finance Props
  defaultPaymentTerm: string;
  setDefaultPaymentTerm: (term: string) => void;
  defaultTaxRate: number;
  setDefaultTaxRate: (rate: number) => void;
  taxEnabled: boolean;
  setTaxEnabled: (enabled: boolean) => void;
  defaultCurrency: string;
  setDefaultCurrency: (currency: string) => void;
  multiCurrency: boolean;
  setMultiCurrency: (enabled: boolean) => void;
  // RBAC Props
  roles: RoleDefinition[];
  setRoles: (roles: RoleDefinition[]) => void;
  users: User[];
  setUsers: (users: User[]) => void;
  currentUser: User;
  setCurrentUser: (user: User) => void;
}

// Permission Toggle Card for Role Editor
const PermissionToggleCard: React.FC<{ label: string, checked: boolean, onChange: () => void, disabled?: boolean }> = ({ label, checked, onChange, disabled }) => (
    <div 
        onClick={() => !disabled && onChange()}
        className={`flex items-center justify-between p-4 rounded-xl border transition-all duration-200 cursor-pointer group ${
            checked 
            ? 'bg-primary-50 border-primary-200 dark:bg-primary-900/20 dark:border-primary-800/50 shadow-sm' 
            : 'bg-white border-slate-200 dark:bg-slate-800 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'
        } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
    >
        <span className={`text-sm font-medium ${checked ? 'text-primary-700 dark:text-primary-300' : 'text-slate-600 dark:text-slate-400'}`}>
            {label}
        </span>
        <div className={`w-11 h-6 rounded-full relative transition-colors duration-200 ease-in-out flex items-center px-0.5 ${checked ? 'bg-primary-500' : 'bg-slate-300 dark:bg-slate-600'}`}>
            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transform transition-transform duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
        </div>
    </div>
);

const Settings: React.FC<SettingsProps> = ({ 
  isDark, 
  toggleTheme, 
  primaryColor, 
  setPrimaryColor,
  pipelineGoal,
  setPipelineGoal,
  fontFamily,
  setFontFamily,
  density,
  setDensity,
  weekStart,
  setWeekStart,
  dateFormat,
  setDateFormat,
  timeZone,
  setTimeZone,
  timeFormat,
  setTimeFormat,
  workingDays,
  setWorkingDays,
  fiscalYearStart,
  setFiscalYearStart,
  defaultPaymentTerm,
  setDefaultPaymentTerm,
  defaultTaxRate,
  setDefaultTaxRate,
  taxEnabled,
  setTaxEnabled,
  defaultCurrency,
  setDefaultCurrency,
  multiCurrency,
  setMultiCurrency,
  roles,
  setRoles,
  users,
  setUsers,
  currentUser,
  setCurrentUser
}) => {
  const [activeTab, setActiveTab] = useState('team');
  const [goalInput, setGoalInput] = useState(pipelineGoal.toString());
  const [isSaved, setIsSaved] = useState(false);

  // RBAC Local States
  const [editingRole, setEditingRole] = useState<RoleDefinition | null>(null);
  const [isCreateRoleModalOpen, setIsCreateRoleModalOpen] = useState(false);
  const [newRoleName, setNewRoleName] = useState('');
  const [newRoleDescription, setNewRoleDescription] = useState('');

  // Invite Member State
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const [inviteName, setInviteName] = useState('');
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState('');

  // Password Generation State
  const [passwordModalOpen, setPasswordModalOpen] = useState(false);
  const [selectedUserForPassword, setSelectedUserForPassword] = useState<User | null>(null);
  const [generatedPassword, setGeneratedPassword] = useState('');

  // Select default role for editing when roles load
  useEffect(() => {
    if (!editingRole && roles.length > 0) {
        setEditingRole(roles[0]);
    }
  }, [roles]);

  // Set default invite role whenever modal opens or roles change
  useEffect(() => {
      if (roles.length > 0 && isInviteModalOpen) {
          // If no role selected yet, default to first role
          if (!inviteRole) {
              setInviteRole(roles[0].id);
          }
      }
  }, [roles, isInviteModalOpen]);

  const handleSave = () => {
    setPipelineGoal(Number(goalInput));
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Copied to clipboard!");
  };

  // RBAC Functions
  const handleUpdateUserRole = (userId: string, roleId: string) => {
      setUsers(users.map(u => u.id === userId ? { ...u, roleId } : u));
      if (currentUser.id === userId) {
          setCurrentUser({ ...currentUser, roleId });
      }
  };

  const handleTogglePermission = (roleId: string, permission: Permission) => {
      setRoles(roles.map(r => {
          if (r.id !== roleId) return r;
          const hasPermission = r.permissions.includes(permission);
          return {
              ...r,
              permissions: hasPermission 
                  ? r.permissions.filter(p => p !== permission)
                  : [...r.permissions, permission]
          };
      }));
  };

  const handleCreateRole = () => {
      if (!newRoleName.trim()) {
          alert('Role name is required');
          return;
      }

      // Robust ID generation
      const roleId = newRoleName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

      const newRole: RoleDefinition = {
          id: roleId,
          name: newRoleName.trim(),
          description: newRoleDescription || 'Custom Role',
          isSystem: false,
          permissions: ['view_dashboard'] // Default min permission
      };

      const updatedRoles = [...roles, newRole];
      setRoles(updatedRoles);

      setIsCreateRoleModalOpen(false);
      setNewRoleName('');
      setNewRoleDescription('');
      setEditingRole(newRole); // Switch to editing the new role immediately
  };

  const handleInviteMember = (e: React.FormEvent) => {
      e.preventDefault();
      if (!inviteEmail || !inviteName) {
          alert('Name and Email are required');
          return;
      }

      // Use selected inviteRole or fallback safely
      const selectedRoleId = inviteRole || (roles.length > 0 ? roles[0].id : 'sales_rep');

      const newUser: User = {
          id: `u-${Date.now()}`,
          name: inviteName,
          email: inviteEmail,
          roleId: selectedRoleId,
          status: 'Active',
          lastLogin: 'Never',
          avatar: `https://i.pravatar.cc/150?u=${Date.now()}` // Random avatar
      };

      // Prepend to users array so it appears at the top
      setUsers([newUser, ...users]);

      setIsInviteModalOpen(false);
      setInviteName('');
      setInviteEmail('');
      setInviteRole(''); // Clear selection so it resets next time

      // Show success feedback
      alert(`User ${inviteName} added successfully!`);
  };

  const handleDeleteRole = (roleId: string) => {
      if (window.confirm('Are you sure you want to delete this role? Users assigned to this role will lose access.')) {
          setRoles(roles.filter(r => r.id !== roleId));
          if (editingRole?.id === roleId) setEditingRole(roles.find(r => r.id !== roleId) || null);
      }
  };

  // Password Generation Logic
  const generateSecurePassword = () => {
      const length = 12;
      const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";
      let retVal = "";
      for (let i = 0, n = charset.length; i < length; ++i) {
          retVal += charset.charAt(Math.floor(Math.random() * n));
      }
      return retVal;
  };

  const handleGeneratePassword = (user: User) => {
      const newPassword = generateSecurePassword();
      setGeneratedPassword(newPassword);
      setSelectedUserForPassword(user);

      // Update user state with temp password
      setUsers(users.map(u => u.id === user.id ? { ...u, tempPassword: newPassword } : u));

      setPasswordModalOpen(true);
  };

  const PERMISSION_GROUPS = {
      'System Administration': ['manage_users', 'manage_settings'],
      'Sales Operations': ['view_leads', 'edit_leads', 'manage_pipeline', 'view_revenue'],
      'Data Governance': ['delete_records', 'export_data'],
      'Intelligence': ['use_ai_features', 'view_dashboard']
  };

  const PERMISSION_LABELS: Record<Permission, string> = {
      'view_dashboard': 'Access Analytics Dashboard',
      'manage_users': 'Manage Users & Roles',
      'manage_settings': 'Configure System Settings',
      'view_leads': 'View Leads & Contacts',
      'edit_leads': 'Create/Edit Leads & Contacts',
      'delete_records': 'Delete Records',
      'export_data': 'Export Data',
      'view_revenue': 'View Revenue Data',
      'manage_pipeline': 'Manage Sales Pipeline',
      'use_ai_features': 'Access AI Features'
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'team':
        return (
            <div className="space-y-10 animate-fade-in pb-10">
                <div className="flex justify-between items-end border-b border-slate-200 dark:border-slate-800 pb-4">
                    <div>
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white uppercase tracking-tight">Team & Access Control</h3>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Manage users, roles, and granular permissions.</p>
                    </div>
                    <button 
                      onClick={() => setIsInviteModalOpen(true)}
                      className="flex items-center gap-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-4 py-2 rounded-lg text-sm font-bold shadow-md hover:opacity-90 transition-all"
                    >
                        <IconPlus className="w-4 h-4" /> Invite Member
                    </button>
                </div>

                {/* 1. Users Section */}
                <section>
                    <h4 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <IconUsers className="w-4 h-4" /> Active Users ({users.length})
                    </h4>
                    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden">
                        <table className="w-full text-left text-sm">
                            <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
                                <tr>
                                    <th className="px-6 py-3 font-medium">User</th>
                                    <th className="px-6 py-3 font-medium">Role</th>
                                    <th className="px-6 py-3 font-medium">Status</th>
                                    <th className="px-6 py-3 font-medium text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {users.map(user => (
                                    <tr key={user.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                                        <td className="px-6 py-3">
                                            <div className="flex items-center">
                                                <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center mr-3 overflow-hidden">
                                                    {user.avatar ? (
                                                        <img src={user.avatar} alt={user.name} className="w-full h-full object-cover" />
                                                    ) : (
                                                        <span className="font-bold text-slate-500 dark:text-slate-400">{user.name.charAt(0)}</span>
                                                    )}
                                                </div>
                                                <div>
                                                    <div className="font-medium text-slate-900 dark:text-white">{user.name}</div>
                                                    <div className="text-xs text-slate-500">{user.email}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-3">
                                            <select 
                                                value={user.roleId}
                                                onChange={(e) => handleUpdateUserRole(user.id, e.target.value)}
                                                className="bg-transparent text-sm border-b border-dashed border-slate-300 dark:border-slate-600 focus:outline-none hover:border-primary-500 cursor-pointer text-slate-700 dark:text-slate-300 py-1"
                                            >
                                                {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                                            </select>
                                        </td>
                                        <td className="px-6 py-3">
                                            <span className={`px-2 py-0.5 rounded-full text-xs font-bold ${user.status === 'Active' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-slate-100 text-slate-600'}`}>
                                                {user.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-3 text-right">
                                            <button 
                                                onClick={() => handleGeneratePassword(user)}
                                                className="text-primary-600 hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300 text-xs font-medium"
                                            >
                                                Reset Password
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </section>

                {/* 2. Roles & Permissions Section */}
                <section>
                    <div className="flex items-center justify-between mb-4">
                        <h4 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest flex items-center gap-2">
                            <IconLock className="w-4 h-4" /> Role Configuration
                        </h4>
                        <button 
                            onClick={() => setIsCreateRoleModalOpen(true)}
                            className="text-xs font-bold text-primary-600 dark:text-primary-400 hover:underline flex items-center gap-1"
                        >
                            <IconPlus className="w-3 h-3" /> Create Custom Role
                        </button>
                    </div>

                    <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden flex flex-col md:flex-row h-[600px]">
                        {/* Sidebar: Role List */}
                        <div className="w-full md:w-1/3 border-r border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex flex-col">
                            <div className="overflow-y-auto flex-1 p-3 space-y-2 custom-scrollbar">
