const Dashboard: React.FC<DashboardProps> = ({ leads, deals, isDark = true, userRole }) => {
  const [timeRange, setTimeRange] = useState<'7D' | '30D' | '3M' | 'YTD'>('30D');
  const [isCustomizeOpen, setIsCustomizeOpen] = useState(false);

  const [statsConfig, setStatsConfig] = useState<StatsConfig[]>(DEFAULT_STATS);
  const [widgetsConfig, setWidgetsConfig] = useState<WidgetConfig[]>(DEFAULT_WIDGETS);

  // Drag and Drop States for Customization
  const [draggedStatId, setDraggedStatId] = useState<string | null>(null);
  const [draggedWidgetId, setDraggedWidgetId] = useState<string | null>(null);

  const canViewRevenue = userRole ? userRole.permissions.includes('view_revenue') : true;

  // --- Metrics Calculation ---
  const startDate = useMemo(() => {
      const now = new Date();
      const d = new Date(now);
      switch (timeRange) {
          case '7D': d.setDate(now.getDate() - 7); break;
          case '30D': d.setDate(now.getDate() - 30); break;
          case '3M': d.setMonth(now.getMonth() - 3); break;
          case 'YTD': d.setMonth(0, 1); break;
      }
      return d;
  }, [timeRange]);

  const isAfterStart = (dateStr?: string) => {
      if (!dateStr) return false;
      return new Date(dateStr) >= startDate;
  };

  const getLeadDate = (lead: Lead) => {
      const createdAct = lead.activities?.find(a => a.type === 'created');
      if (createdAct) return new Date(createdAct.timestamp);
      return lead.lastContact ? new Date(lead.lastContact) : new Date(0); 
  };

  const newLeadsCount = leads.filter(l => getLeadDate(l) >= startDate).length;
  const wonDealsFiltered = deals.filter(d => d.stage === 'Closed Won' && isAfterStart(d.closeDate));
  const wonDealsCount = wonDealsFiltered.length;
  const totalRevenue = wonDealsFiltered.reduce((acc, curr) => acc + curr.value, 0);
  const activeDealsCount = deals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length;

  // --- Chart Data Preparation ---
  const leadSourceData = leads
    .filter(l => getLeadDate(l) >= startDate)
    .reduce((acc, lead) => {
        const source = lead.leadSource || 'Other';
        acc[source] = (acc[source] || 0) + 1;
        return acc;
    }, {} as Record<string, number>);

  const pieData = Object.keys(leadSourceData).length > 0 
    ? Object.keys(leadSourceData).map(key => ({ name: key, value: leadSourceData[key] }))
    : [{ name: 'No Data', value: 1 }];

  const stageDataRaw = deals.reduce((acc, deal) => {
      acc[deal.stage] = (acc[deal.stage] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  const barData = Object.keys(stageDataRaw).map(stage => ({
      name: stage.length > 12 ? stage.substring(0, 10) + '...' : stage,
      fullName: stage,
      count: stageDataRaw[stage]
  })).sort((a,b) => b.count - a.count);

  const trendData = useMemo(() => {
      const data = [];
      const now = new Date();
      if (timeRange === '7D') {
          for (let i = 6; i >= 0; i--) {
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { weekday: 'short' });
              data.push({ name: label, actual: Math.floor(Math.random() * 15000), forecast: Math.floor(Math.random() * 10000) + 5000 });
          }
      } else if (timeRange === '30D') {
          for (let i = 29; i >= 0; i-=3) {
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
              data.push({ name: label, actual: Math.floor(Math.random() * 40000), forecast: Math.floor(Math.random() * 30000) + 20000 });
          }
      } else {
          const monthsBack = timeRange === '3M' ? 2 : now.getMonth();
          for (let i = monthsBack; i >= 0; i--) {
              const d = new Date(now);
              d.setMonth(d.getMonth() - i);
              const label = d.toLocaleDateString('en-US', { month: 'short' });
              data.push({ name: label, actual: Math.floor(Math.random() * 150000), forecast: Math.floor(Math.random() * 180000) });
          }
      }
      return data;
  }, [timeRange]);

  const topDeals = [...deals]
    .filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage))
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);

  const allActivities = [
      ...leads.flatMap(lead => (lead.activities || []).map(act => ({ ...act, context: lead.name }))),
      ...deals.flatMap(deal => deal.activities.map(act => ({ ...act, context: deal.title })))
  ].filter(a => new Date(a.timestamp) >= startDate)
   .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
   .slice(0, 6);

  // --- Layout Helper Functions ---
  const toggleStatVisibility = (id: string) => {
      setStatsConfig(prev => prev.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s));
  };

  const toggleWidgetVisibility = (id: string) => {
      setWidgetsConfig(prev => prev.map(w => w.id === id ? { ...w, isVisible: !w.isVisible } : w));
  };

  const onStatDragStart = (e: React.DragEvent, id: string) => {
      e.dataTransfer.setData('statId', id);
      setDraggedStatId(id);
  };

  const onStatDrop = (e: React.DragEvent, targetId: string) => {
      const draggedId = e.dataTransfer.getData('statId');
      if (draggedId === targetId) return;
      const draggedIndex = statsConfig.findIndex(s => s.id === draggedId);
      const targetIndex = statsConfig.findIndex(s => s.id === targetId);
      const newStats = [...statsConfig];
      const [removed] = newStats.splice(draggedIndex, 1);
      newStats.splice(targetIndex, 0, removed);
      setStatsConfig(newStats.map((s, idx) => ({ ...s, order: idx })));
      setDraggedStatId(null);
  };

  const onWidgetDragStart = (e: React.DragEvent, id: string) => {
      e.dataTransfer.setData('widgetId', id);
      setDraggedWidgetId(id);
  };

  const onWidgetDrop = (e: React.DragEvent, targetId: string) => {
      const draggedId = e.dataTransfer.getData('widgetId');
      if (draggedId === targetId) return;
      const draggedIndex = widgetsConfig.findIndex(w => w.id === draggedId);
      const targetIndex = widgetsConfig.findIndex(w => w.id === targetId);
      const newWidgets = [...widgetsConfig];
      const [removed] = newWidgets.splice(draggedIndex, 1);
      newWidgets.splice(targetIndex, 0, removed);
      setWidgetsConfig(newWidgets.map((w, idx) => ({ ...w, order: idx })));
      setDraggedWidgetId(null);
  };

  // --- Rendering Specific Widgets ---
  const renderStatWidget = (stat: StatsConfig) => {
      if (stat.requiredPerm && !canViewRevenue) {
          return (
            <div key={stat.id} className="p-6 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex flex-col items-center justify-center text-center opacity-70">
                <IconLock className="w-8 h-8 text-slate-400 mb-2" />
                <p className="text-sm font-medium text-slate-500">{stat.label} Hidden</p>
            </div>
          );
      }

      let value: string | number = 0;
      let subtext = '';
      let trend = '';

      if (stat.id === 'new_leads') {
          value = newLeadsCount;
          subtext = `Since ${startDate.toLocaleDateString()}`;
          trend = '8%';
      } else if (stat.id === 'active_pipeline') {
          value = activeDealsCount;
          subtext = "Total Open Deals";
      } else if (stat.id === 'won_deals') {
          value = wonDealsCount;
          subtext = "In Selected Period";
          trend = '15%';
      } else if (stat.id === 'revenue') {
          value = `$${(totalRevenue / 1000).toFixed(1)}k`;
          subtext = "Closed Won";
          trend = '12%';
      }

      return (
          <BIStatCard 
            key={stat.id}
            title={stat.label} 
            value={value} 
            subtext={subtext}
            trend={trend}
            icon={stat.icon} 
            colorClass={stat.colorClass} 
          />
      );
  };

  const renderMainWidget = (widget: WidgetConfig) => {
      const colSpanClass = widget.colSpan === 2 ? 'xl:col-span-2' : 'xl:col-span-1';

      if (widget.requiredPerm && !canViewRevenue) {
          return (
              <ChartWidget key={widget.id} title={widget.label} className={`${colSpanClass}`}>
                 <div className="flex flex-col items-center justify-center h-full text-slate-400">
                     <IconLock className="w-12 h-12 mb-4 opacity-20" />
                     <p>Data restricted for your role.</p>
                 </div>
              </ChartWidget>
          );
      }

      switch(widget.id) {
          case 'revenue_forecast':
              return (
                  <ChartWidget key={widget.id} title={`Revenue Forecast (${timeRange})`} className={colSpanClass}>
                     <ResponsiveContainer width="100%" height="100%">
                       <AreaChart data={trendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                         <defs>
                           <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                             <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                             <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                           </linearGradient>
                           <linearGradient id="colorForecast" x1="0" y1="0" x2="0" y2="1">
                             <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                             <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                           </linearGradient>
                         </defs>
                         <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.5} />
                         <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} dy={10} />
                         <YAxis axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} tickFormatter={(val) => `$${val/1000}k`} dx={-10} />
                         <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', backgroundColor: isDark ? '#1e293b' : '#fff' }} itemStyle={{ color: isDark ? '#fff' : '#1e293b' }} />
                         <Legend verticalAlign="top" height={36} iconType="circle" />
                         <Area type="monotone" name="Forecast" dataKey="forecast" stroke="#10b981" strokeDasharray="5 5" strokeWidth={2} fillOpacity={1} fill="url(#colorForecast)" />
                         <Area type="monotone" name="Revenue" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" />
                       </AreaChart>
                     </ResponsiveContainer>
                  </ChartWidget>
              );
          case 'lead_source':
              return (
                  <ChartWidget key={widget.id} title="Lead Source" className={colSpanClass}>
                     <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                            <Pie data={pieData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                {pieData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />)}
                            </Pie>
                            <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: isDark ? '#1e293b' : '#fff' }} itemStyle={{ color: isDark ? '#fff' : '#1e293b' }} />
                            <Legend layout="horizontal" verticalAlign="bottom" align="center" iconType="circle" wrapperStyle={{ paddingTop: '20px', fontSize: '12px' }} />
                        </PieChart>
                     </ResponsiveContainer>
                  </ChartWidget>
              );
          case 'deal_funnel':
              return (
                  <ChartWidget key={widget.id} title="Opportunities by Stage" className={colSpanClass}>
                     <ResponsiveContainer width="100%" height={250}>
                        <BarChart data={barData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.3} />
                            <XAxis type="number" hide />
                            <YAxis dataKey="name" type="category" width={80} tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 11 }} axisLine={false} tickLine={false} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px', backgroundColor: isDark ? '#1e293b' : '#fff' }} />
                            <Bar dataKey="count" fill="#10b981" radius={[0, 4, 4, 0]} barSize={20} />
                        </BarChart>
                     </ResponsiveContainer>
                  </ChartWidget>
              );
          case 'top_opportunities':
              return (
                  <div key={widget.id} className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow ${colSpanClass}`}>
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Top Opportunities</h3>
                      </div>
                      <div className="space-y-3">
                          {topDeals.length > 0 ? topDeals.map((deal, idx) => (
                              <div key={deal.id} className="group flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700/50 hover:bg-white dark:hover:bg-slate-800 hover:shadow-md transition-all">
                                  <div className="flex items-center gap-3">
                                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold ${idx === 0 ? 'bg-amber-100 text-amber-600' : 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-400'}`}>{idx + 1}</div>
                                      <div><p className="font-semibold text-sm text-slate-900 dark:text-white truncate max-w-[120px]" title={deal.title}>{deal.title}</p><p className="text-xs text-slate-500">{deal.company}</p></div>
                                  </div>
                                  {canViewRevenue ? (
                                      <div className="text-right">
                                          <p className="font-bold text-slate-900 dark:text-white text-sm">${deal.value.toLocaleString()}</p>
                                          <div className="flex items-center justify-end gap-1 mt-1">
                                            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden"><div className="h-full bg-emerald-500 rounded-full" style={{ width: `${deal.probability}%` }}></div></div>
                                            <span className="text-[10px] text-slate-500">{deal.probability}%</span>
                                          </div>
                                      </div>
                                  ) : (<div className="text-right"><IconLock className="w-4 h-4 text-slate-400" /></div>)}
                              </div>
                          )) : <div className="text-center text-slate-500 text-sm py-8">No open opportunities found.</div>}
                      </div>
                  </div>
              );
          case 'activity_feed':
              return (
                  <div key={widget.id} className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col ${colSpanClass}`}>
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Activity Feed</h3>
                          <IconActivity className="w-5 h-5 text-blue-500" />
                      </div>
                      <div className="overflow-y-auto flex-1 custom-scrollbar -mr-2 pr-2">
                          {allActivities.length > 0 ? allActivities.map((act, index) => (
                              <ActivityItem key={act.id} activity={act} isLast={index === allActivities.length - 1} />
                          )) : <div className="flex flex-col items-center justify-center h-40 text-slate-500"><IconSparkles className="w-8 h-8 mb-2 opacity-20" /><p className="text-sm">No recent activity.</p></div>}
                      </div>
                  </div>
              );
          default: return null;
      }
  };

  return (
    <div className="space-y-6 animate-slide-up pb-8 relative">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-2 md:pr-20">
        <div>
            <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm mb-1 font-medium">
                <IconLayoutDashboard className="w-4 h-4" /> / Dashboard
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Business Overview</h1>
        </div>

        <div className="flex items-center gap-3">
            <button 
                onClick={() => setIsCustomizeOpen(true)}
                className="flex items-center px-4 py-2 text-sm font-medium bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 transition-colors shadow-sm"
            >
                <IconSettings className="w-4 h-4 mr-2" /> Customize
            </button>

            {/* Date Filter */}
            <div className="flex items-center bg-white dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                {(['7D', '30D', '3M', 'YTD'] as const).map((period) => (
                    <button 
                        key={period}
                        onClick={() => setTimeRange(period)}
                        className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${
                            timeRange === period 
                            ? 'bg-primary-50 text-primary-600 dark:bg-primary-900/30 dark:text-primary-400 shadow-sm ring-1 ring-primary-500/20' 
                            : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                    >
                        {period}
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* Row 1: KPI Cards (Dynamic) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        {statsConfig.filter(s => s.isVisible).map(stat => renderStatWidget(stat))}
      </div>

      {/* Main Grid (Dynamic) */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
          {widgetsConfig.filter(w => w.isVisible).map(widget => renderMainWidget(widget))}
      </div>

      {/* Customization Modal */}
      {isCustomizeOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
              <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl overflow-hidden animate-scale-in flex flex-col max-h-[85vh]">
                  <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                      <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                          <IconSettings className="w-5 h-5 mr-3 text-primary-500" />
                          Customize Dashboard
                      </h2>
                      <button onClick={() => setIsCustomizeOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                      {/* Section 1: Key Metrics */}
                      <div className="mb-8">
                          <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-4">Key Metrics (Top Row)</h3>
                          <div className="space-y-3">
                              {statsConfig.map(stat => (
                                  <div 
                                    key={stat.id}
                                    draggable
                                    onDragStart={(e) => onStatDragStart(e, stat.id)}
                                    onDragOver={(e) => e.preventDefault()}
                                    onDrop={(e) => onStatDrop(e, stat.id)}
                                    className={`flex items-center justify-between p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl ${draggedStatId === stat.id ? 'opacity-50 border-dashed border-primary-500' : 'hover:border-primary-300 dark:hover:border-primary-700'}`}
                                  >
                                      <div className="flex items-center gap-3">
                                          <IconGripVertical className="w-4 h-4 text-slate-400 cursor-move hover:text-primary-500" />
                                          <span className="font-medium text-slate-700 dark:text-slate-200 text-sm">{stat.label}</span>
                                      </div>
                                      <button 
                                        onClick={() => toggleStatVisibility(stat.id)}
                                        className={`p-2 rounded-lg transition-colors ${stat.isVisible ? 'text-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-400 bg-slate-100 dark:bg-slate-800'}`}
                                      >
                                          {stat.isVisible ? <IconEye className="w-4 h-4" /> : <IconEyeOff className="w-4 h-4" />}
                                      </button>
                                  </div>
                              ))}
                          </div>
                      </div>

                      {/* Section 2: Analytics & Lists */}
                      <div>
                          <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-4">Analytics & Lists (Main Grid)</h3>
                          <div className="space-y-3">
                              {widgetsConfig.map(widget => (
                                  <div 
                                    key={widget.id}
                                    draggable
                                    onDragStart={(e) => onWidgetDragStart(e, widget.id)}
                                    onDragOver={(e) => e.preventDefault()}
                                    onDrop={(e) => onWidgetDrop(e, widget.id)}
                                    className={`flex items-center justify-between p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl ${draggedWidgetId === widget.id ? 'opacity-50 border-dashed border-primary-500' : 'hover:border-primary-300 dark:hover:border-primary-700'}`}
                                  >
                                      <div className="flex items-center gap-3">
                                          <IconGripVertical className="w-4 h-4 text-slate-400 cursor-move hover:text-primary-500" />
                                          <span className="font-medium text-slate-700 dark:text-slate-200 text-sm">{widget.label}</span>
                                          <span className="text-[10px] bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded text-slate-500 uppercase font-bold">
                                              {widget.colSpan === 2 ? 'Wide' : 'Standard'}
                                          </span>
                                      </div>
                                      <button 
                                        onClick={() => toggleWidgetVisibility(widget.id)}
                                        className={`p-2 rounded-lg transition-colors ${widget.isVisible ? 'text-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-400 bg-slate-100 dark:bg-slate-800'}`}
                                      >
                                          {widget.isVisible ? <IconEye className="w-4 h-4" /> : <IconEyeOff className="w-4 h-4" />}
                                      </button>
                                  </div>
                              ))}
                          </div>
                      </div>
                  </div>

                  <div className="p-4 border-t border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex justify-end">
                      <button 
                        onClick={() => setIsCustomizeOpen(false)}
                        className="px-6 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-xl font-bold text-sm shadow-md transition-all"
                      >
                          Done
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef } from 'react';
import { Lead, Deal, Task, Meeting, Activity, RoleDefinition } from '../types';
import { 
    IconUsers, 
    IconKanban, 
    IconHistory, 
    IconSparkles, 
    IconCheckCircle, 
    IconActivity, 
    IconWallet, 
    IconLayoutDashboard,
    IconArrowUp,
    IconLock,
    IconSettings,
    IconGripVertical,
    IconEye,
    IconEyeOff,
    IconX
} from './Icons';
import { 
    AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, PieChart, Pie, Cell, Legend
} from 'recharts';

interface DashboardProps {
  leads: Lead[];
  deals: Deal[];
  tasks: Task[];
  meetings: Meeting[];
  isDark?: boolean;
  pipelineGoal?: number;
  userRole?: RoleDefinition;
}

const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

// ----- Config Interfaces -----
interface WidgetConfig {
    id: string;
    label: string;
    isVisible: boolean;
    order: number;
    colSpan: number; // 1 (default), 2 (half-width), 3 (full-width)
    requiredPerm?: string;
}

interface StatsConfig {
    id: string;
    label: string;
    isVisible: boolean;
    order: number;
    icon: any;
    colorClass: string;
    requiredPerm?: string;
}

// ----- Default Configurations -----
const DEFAULT_STATS: StatsConfig[] = [
    { id: 'new_leads', label: 'New Leads', isVisible: true, order: 0, icon: IconUsers, colorClass: 'bg-gradient-to-br from-blue-500 to-blue-600' },
    { id: 'active_pipeline', label: 'Active Pipeline', isVisible: true, order: 1, icon: IconKanban, colorClass: 'bg-gradient-to-br from-emerald-400 to-emerald-600' },
    { id: 'won_deals', label: 'Won Deals', isVisible: true, order: 2, icon: IconCheckCircle, colorClass: 'bg-gradient-to-br from-rose-400 to-rose-600', requiredPerm: 'view_revenue' },
    { id: 'revenue', label: 'Revenue', isVisible: true, order: 3, icon: IconWallet, colorClass: 'bg-gradient-to-br from-indigo-500 to-purple-600', requiredPerm: 'view_revenue' }
];

const DEFAULT_WIDGETS: WidgetConfig[] = [
    { id: 'revenue_forecast', label: 'Revenue Forecast', isVisible: true, order: 0, colSpan: 2, requiredPerm: 'view_revenue' },
    { id: 'lead_source', label: 'Lead Source', isVisible: true, order: 1, colSpan: 1 },
    { id: 'deal_funnel', label: 'Opportunities by Stage', isVisible: true, order: 2, colSpan: 1 },
    { id: 'top_opportunities', label: 'Top Opportunities', isVisible: true, order: 3, colSpan: 1 },
    { id: 'activity_feed', label: 'Activity Feed', isVisible: true, order: 4, colSpan: 1 },
];

interface BIStatCardProps {
    title: string;
    value: string | number;
    subtext?: string;
    icon: any;
    colorClass: string;
    trend?: string;
}

const BIStatCard: React.FC<BIStatCardProps> = ({ title, value, subtext, icon: Icon, colorClass, trend }) => (
    <div className={`p-6 rounded-2xl shadow-sm text-white relative overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:shadow-lg ${colorClass}`}>
        {/* Background Circles for decoration */}
        <div className="absolute -right-6 -top-6 w-24 h-24 rounded-full bg-white/10 blur-xl"></div>
        <div className="absolute -left-6 -bottom-6 w-20 h-20 rounded-full bg-black/5 blur-lg"></div>

        <div className="relative z-10 flex justify-between items-start">
            <div>
                <h3 className="text-xs font-bold uppercase tracking-wider opacity-90 mb-1">{title}</h3>
                <p className="text-3xl font-bold tracking-tight">{value}</p>
                {subtext && (
                    <div className="flex items-center gap-2 mt-2">
                        {trend && <span className="bg-white/20 px-1.5 py-0.5 rounded text-[10px] font-bold flex items-center"><IconArrowUp className="w-2.5 h-2.5 mr-0.5" />{trend}</span>}
                        <p className="text-xs opacity-80 font-medium">{subtext}</p>
                    </div>
                )}
            </div>
            <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm shadow-inner">
                <Icon className="w-6 h-6 text-white" />
            </div>
        </div>
    </div>
);

interface ChartWidgetProps {
    title: string;
    children?: React.ReactNode;
    className?: string;
}

const ChartWidget: React.FC<ChartWidgetProps> = ({ title, children, className = "" }) => (
    <div className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col h-full ${className}`}>
        <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">{title}</h3>
            <button className="text-slate-400 hover:text-primary-500 transition-colors">
                <IconSparkles className="w-4 h-4" />
            </button>
        </div>
        <div className="flex-1 w-full min-h-[250px]">
            {children}
        </div>
    </div>
);

const ActivityItem: React.FC<{ activity: Activity & { context: string }, isLast: boolean }> = ({ activity, isLast }) => {
    return (
        <div className="flex group relative pl-2">
            {!isLast && <div className="absolute left-[19px] top-8 bottom-0 w-px bg-slate-100 dark:bg-slate-800 group-hover:bg-indigo-100 dark:group-hover:bg-indigo-900/30 transition-colors"></div>}

            <div className="flex-shrink-0 mr-4 pt-1">
                <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center shadow-sm z-10 relative bg-white dark:bg-slate-900 ${
                    activity.type === 'stage_change' ? 'border-blue-200 text-blue-500' :
                    activity.type === 'created' ? 'border-emerald-200 text-emerald-500' :
                    'border-slate-200 text-slate-400'
                }`}>
                    <div className={`w-2 h-2 rounded-full ${
                         activity.type === 'stage_change' ? 'bg-blue-500' :
                         activity.type === 'created' ? 'bg-emerald-500' :
                         'bg-slate-400'
                    }`}></div>
                </div>
            </div>
            <div className="pb-6 pt-1.5 w-full">
                <div className="flex justify-between items-start">
                    <p className="text-sm font-medium text-slate-700 dark:text-slate-200 mb-0.5">
                        <span className="font-bold">{activity.context}</span>: {activity.description}
                    </p>
                </div>
                <span className="text-xs text-slate-400 dark:text-slate-500 flex items-center gap-1">
                    <IconHistory className="w-3 h-3" />
                    {new Date(activity.timestamp).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                </span>
            </div>
        </div>
    );
};

const Dashboard: React.FC<DashboardProps> = ({ leads, deals, isDark = true, userRole }) => {
  const [timeRange, setTimeRange] = useState<'7D' | '30D' | '3M' | 'YTD'>('30D');
  const [isCustomizeOpen, setIsCustomizeOpen] = useState(false);

  const [statsConfig, setStatsConfig] = useState<StatsConfig[]>(DEFAULT_STATS);
  const [widgetsConfig, setWidgetsConfig] = useState<WidgetConfig[]>(DEFAULT_WIDGETS);

  // Drag and Drop States for Customization
  const [draggedStatId, setDraggedStatId] = useState<string | null>(null);
  const [draggedWidgetId, setDraggedWidgetId] = useState<string | null>(null);

  const canViewRevenue = userRole ? userRole.permissions.includes('view_revenue') : true;

  // --- Metrics Calculation ---
  const startDate = useMemo(() => {
      const now = new Date();
      const d = new Date(now);
      switch (timeRange) {
          case '7D': d.setDate(now.getDate() - 7); break;
          case '30D': d.setDate(now.getDate() - 30); break;
          case '3M': d.setMonth(now.getMonth() - 3); break;
          case 'YTD': d.setMonth(0, 1); break;
      }
      return d;
  }, [timeRange]);

  const isAfterStart = (dateStr?: string) => {
      if (!dateStr) return false;
      return new Date(dateStr) >= startDate;
  };

  const getLeadDate = (lead: Lead) => {
      const createdAct = lead.activities?.find(a => a.type === 'created');
      if (createdAct) return new Date(createdAct.timestamp);
      return lead.lastContact ? new Date(lead.lastContact) : new Date(0); 
  };

  const newLeadsCount = leads.filter(l => getLeadDate(l) >= startDate).length;
  const wonDealsFiltered = deals.filter(d => d.stage === 'Closed Won' && isAfterStart(d.closeDate));
  const wonDealsCount = wonDealsFiltered.length;
  const totalRevenue = wonDealsFiltered.reduce((acc, curr) => acc + curr.value, 0);
  const activeDealsCount = deals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length;

  // --- Chart Data Preparation ---
  const leadSourceData = leads
    .filter(l => getLeadDate(l) >= startDate)
    .reduce((acc, lead) => {
        const source = lead.leadSource || 'Other';
        acc[source] = (acc[source] || 0) + 1;
        return acc;
    }, {} as Record<string, number>);

  const pieData = Object.keys(leadSourceData).length > 0 
    ? Object.keys(leadSourceData).map(key => ({ name: key, value: leadSourceData[key] }))
    : [{ name: 'No Data', value: 1 }];

  const stageDataRaw = deals.reduce((acc, deal) => {
      acc[deal.stage] = (acc[deal.stage] || 0) + 1;
      return acc;
  }, {} as Record<string, number>);

  const barData = Object.keys(stageDataRaw).map(stage => ({
      name: stage.length > 12 ? stage.substring(0, 10) + '...' : stage,
      fullName: stage,
      count: stageDataRaw[stage]
  })).sort((a,b) => b.count - a.count);

  const trendData = useMemo(() => {
      const data = [];
      const now = new Date();
      if (timeRange === '7D') {
          for (let i = 6; i >= 0; i--) {
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { weekday: 'short' });
              data.push({ name: label, actual: Math.floor(Math.random() * 15000), forecast: Math.floor(Math.random() * 10000) + 5000 });
          }
      } else if (timeRange === '30D') {
          for (let i = 29; i >= 0; i-=3) {
              const d = new Date(now);
              d.setDate(d.getDate() - i);
              const label = d.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
              data.push({ name: label, actual: Math.floor(Math.random() * 40000), forecast: Math.floor(Math.random() * 30000) + 20000 });
          }
      } else {
          const monthsBack = timeRange === '3M' ? 2 : now.getMonth();
          for (let i = monthsBack; i >= 0; i--) {
              const d = new Date(now);
              d.setMonth(d.getMonth() - i);
              const label = d.toLocaleDateString('en-US', { month: 'short' });
              data.push({ name: label, actual: Math.floor(Math.random() * 150000), forecast: Math.floor(Math.random() * 180000) });
          }
      }
      return data;
  }, [timeRange]);

  const topDeals = [...deals]
    .filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage))
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);

  const allActivities = [
      ...leads.flatMap(lead => (lead.activities || []).map(act => ({ ...act, context: lead.name }))),
      ...deals.flatMap(deal => deal.activities.map(act => ({ ...act, context: deal.title })))
  ].filter(a => new Date(a.timestamp) >= startDate)
   .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
   .slice(0, 6);

  // --- Layout Helper Functions ---
  const toggleStatVisibility = (id: string) => {
      setStatsConfig(prev => prev.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s));
  };

  const toggleWidgetVisibility = (id: string) => {
      setWidgetsConfig(prev => prev.map(w => w.id === id ? { ...w, isVisible: !w.isVisible } : w));
  };

  const onStatDragStart = (e: React.DragEvent, id: string) => {
      e.dataTransfer.setData('statId', id);
      setDraggedStatId(id);
  };

  const onStatDrop = (e: React.DragEvent, targetId: string) => {
      const draggedId = e.dataTransfer.getData('statId');
      if (draggedId === targetId) return;
      const draggedIndex = statsConfig.findIndex(s => s.id === draggedId);
      const targetIndex = statsConfig.findIndex(s => s.id === targetId);
      const newStats = [...statsConfig];
      const [removed] = newStats.splice(draggedIndex, 1);
      newStats.splice(targetIndex, 0, removed);
      setStatsConfig(newStats.map((s, idx) => ({ ...s, order: idx })));
      setDraggedStatId(null);
  };

  const onWidgetDragStart = (e: React.DragEvent, id: string) => {
      e.dataTransfer.setData('widgetId', id);
      setDraggedWidgetId(id);
  };

  const onWidgetDrop = (e: React.DragEvent, targetId: string) => {
      const draggedId = e.dataTransfer.getData('widgetId');
      if (draggedId === targetId) return;
      const draggedIndex = widgetsConfig.findIndex(w => w.id === draggedId);
      const targetIndex = widgetsConfig.findIndex(w => w.id === targetId);
      const newWidgets = [...widgetsConfig];
      const [removed] = newWidgets.splice(draggedIndex, 1);
      newWidgets.splice(targetIndex, 0, removed);
      setWidgetsConfig(newWidgets.map((w, idx) => ({ ...w, order: idx })));
      setDraggedWidgetId(null);
  };

  // --- Rendering Specific Widgets ---
  const renderStatWidget = (stat: StatsConfig) => {
      if (stat.requiredPerm && !canViewRevenue) {
          return (
            <div key={stat.id} className="p-6 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex flex-col items-center justify-center text-center opacity-70">
                <IconLock className="w-8 h-8 text-slate-400 mb-2" />
                <p className="text-sm font-medium text-slate-500">{stat.label} Hidden</p>
            </div>
          );
      }

      let value: string | number = 0;
      let subtext = '';
      let trend = '';

      if (stat.id === 'new_leads') {
          value = newLeadsCount;
          subtext = `Since ${startDate.toLocaleDateString()}`;
          trend = '8%';
      } else if (stat.id === 'active_pipeline') {
          value = activeDealsCount;
          subtext = "Total Open Deals";
      } else if (stat.id === 'won_deals') {
          value = wonDealsCount;
          subtext = "In Selected Period";
          trend = '15%';
      } else if (stat.id === 'revenue') {
          value = `$${(totalRevenue / 1000).toFixed(1)}k`;
          subtext = "Closed Won";
          trend = '12%';
      }

      return (
          <BIStatCard 
            key={stat.id}
            title={stat.label} 
            value={value} 
            subtext={subtext}
            trend={trend}
            icon={stat.icon} 
            colorClass={stat.colorClass} 
          />
      );
  };

  const renderMainWidget = (widget: WidgetConfig) => {
      const colSpanClass = widget.colSpan === 2 ? 'xl:col-span-2' : 'xl:col-span-1';

      if (widget.requiredPerm && !canViewRevenue) {
          return (
              <ChartWidget key={widget.id} title={widget.label} className={`${colSpanClass}`}>
                 <div className="flex flex-col items-center justify-center h-full text-slate-400">
                     <IconLock className="w-12 h-12 mb-4 opacity-20" />
                     <p>Data restricted for your role.</p>
                 </div>
              </ChartWidget>
          );
      }

      switch(widget.id) {
          case 'revenue_forecast':
              return (
                  <ChartWidget key={widget.id} title={`Revenue Forecast (${timeRange})`} className={colSpanClass}>
                     <ResponsiveContainer width="100%" height="100%">
                       <AreaChart data={trendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                         <defs>
                           <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                             <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                             <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                           </linearGradient>
                           <linearGradient id="colorForecast" x1="0" y1="0" x2="0" y2="1">
                             <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                             <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                           </linearGradient>
                         </defs>
                         <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.5} />
                         <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} dy={10} />
                         <YAxis axisLine={false} tickLine={false} tick={{ fill: isDark ? '#94a3b8' : '#64748b' }} tickFormatter={(val) => `$${val/1000}k`} dx={-10} />
                         <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', backgroundColor: isDark ? '#1e293b' : '#fff' }} itemStyle={{ color: isDark ? '#fff' : '#1e293b' }} />
                         <Legend verticalAlign="top" height={36} iconType="circle" />
                         <Area type="monotone" name="Forecast" dataKey="forecast" stroke="#10b981" strokeDasharray="5 5" strokeWidth={2} fillOpacity={1} fill="url(#colorForecast)" />
                         <Area type="monotone" name="Revenue" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" />
                       </AreaChart>
                     </ResponsiveContainer>
                  </ChartWidget>
              );
          case 'lead_source':
              return (
                  <ChartWidget key={widget.id} title="Lead Source" className={colSpanClass}>
                     <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                            <Pie data={pieData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                {pieData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />)}
                            </Pie>
                            <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: isDark ? '#1e293b' : '#fff' }} itemStyle={{ color: isDark ? '#fff' : '#1e293b' }} />
                            <Legend layout="horizontal" verticalAlign="bottom" align="center" iconType="circle" wrapperStyle={{ paddingTop: '20px', fontSize: '12px' }} />
                        </PieChart>
                     </ResponsiveContainer>
                  </ChartWidget>
              );
          case 'deal_funnel':
              return (
                  <ChartWidget key={widget.id} title="Opportunities by Stage" className={colSpanClass}>
                     <ResponsiveContainer width="100%" height={250}>
                        <BarChart data={barData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.3} />
                            <XAxis type="number" hide />
                            <YAxis dataKey="name" type="category" width={80} tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 11 }} axisLine={false} tickLine={false} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px', backgroundColor: isDark ? '#1e293b' : '#fff' }} />
                            <Bar dataKey="count" fill="#10b981" radius={[0, 4, 4, 0]} barSize={20} />
                        </BarChart>
                     </ResponsiveContainer>
                  </ChartWidget>
              );
          case 'top_opportunities':
              return (
                  <div key={widget.id} className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow ${colSpanClass}`}>
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Top Opportunities</h3>
                      </div>
                      <div className="space-y-3">
                          {topDeals.length > 0 ? topDeals.map((deal, idx) => (
                              <div key={deal.id} className="group flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700/50 hover:bg-white dark:hover:bg-slate-800 hover:shadow-md transition-all">
                                  <div className="flex items-center gap-3">
                                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold ${idx === 0 ? 'bg-amber-100 text-amber-600' : 'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-400'}`}>{idx + 1}</div>
                                      <div><p className="font-semibold text-sm text-slate-900 dark:text-white truncate max-w-[120px]" title={deal.title}>{deal.title}</p><p className="text-xs text-slate-500">{deal.company}</p></div>
                                  </div>
                                  {canViewRevenue ? (
                                      <div className="text-right">
                                          <p className="font-bold text-slate-900 dark:text-white text-sm">${deal.value.toLocaleString()}</p>
                                          <div className="flex items-center justify-end gap-1 mt-1">
                                            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden"><div className="h-full bg-emerald-500 rounded-full" style={{ width: `${deal.probability}%` }}></div></div>
                                            <span className="text-[10px] text-slate-500">{deal.probability}%</span>
                                          </div>
                                      </div>
                                  ) : (<div className="text-right"><IconLock className="w-4 h-4 text-slate-400" /></div>)}
                              </div>
                          )) : <div className="text-center text-slate-500 text-sm py-8">No open opportunities found.</div>}
                      </div>
                  </div>
              );
          case 'activity_feed':
              return (
                  <div key={widget.id} className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col ${colSpanClass}`}>
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Activity Feed</h3>
                          <IconActivity className="w-5 h-5 text-blue-500" />
                      </div>
                      <div className="overflow-y-auto flex-1 custom-scrollbar -mr-2 pr-2">
                          {allActivities.length > 0 ? allActivities.map((act, index) => (
                              <ActivityItem key={act.id} activity={act} isLast={index === allActivities.length - 1} />
                          )) : <div className="flex flex-col items-center justify-center h-40 text-slate-500"><IconSparkles className="w-8 h-8 mb-2 opacity-20" /><p className="text-sm">No recent activity.</p></div>}
                      </div>
                  </div>
              );
          default: return null;
      }
  };

  return (
    <div className="space-y-6 animate-slide-up pb-8 relative">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-2 md:pr-20">
        <div>
            <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm mb-1 font-medium">
                <IconLayoutDashboard className="w-4 h-4" /> / Dashboard
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Business Overview</h1>
        </div>

        <div className="flex items-center gap-3">
            <button 
                onClick={() => setIsCustomizeOpen(true)}
                className="flex items-center px-4 py-2 text-sm font-medium bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 transition-colors shadow-sm"
            >
                <IconSettings className="w-4 h-4 mr-2" /> Customize
            </button>

            {/* Date Filter */}
            <div className="flex items-center bg-white dark:bg-slate-800 p-1 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                {(['7D', '30D', '3M', 'YTD'] as const).map((period) => (
                    <button 
                        key={period}
                        onClick={() => setTimeRange(period)}
                        className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${
                            timeRange === period 
                            ? 'bg-primary-50 text-primary-600 dark:bg-primary-900/30 dark:text-primary-400 shadow-sm ring-1 ring-primary-500/20' 
                            : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                    >
                        {period}
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* Row 1: KPI Cards (Dynamic) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        {statsConfig.filter(s => s.isVisible).map(stat => renderStatWidget(stat))}
      </div>

      {/* Main Grid (Dynamic) */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
          {widgetsConfig.filter(w => w.isVisible).map(widget => renderMainWidget(widget))}
      </div>

      {/* Customization Modal */}
      {isCustomizeOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
              <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl overflow-hidden animate-scale-in flex flex-col max-h-[85vh]">
                  <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                      <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                          <IconSettings className="w-5 h-5 mr-3 text-primary-500" />
                          Customize Dashboard
                      </h2>
                      <button onClick={() => setIsCustomizeOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                      {/* Section 1: Key Metrics */}
                      <div className="mb-8">
                          <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-4">Key Metrics (Top Row)</h3>
                          <div className="space-y-3">
                              {statsConfig.map(stat => (
                                  <div 
                                    key={stat.id}
                                    draggable
                                    onDragStart={(e) => onStatDragStart(e, stat.id)}
                                    onDragOver={(e) => e.preventDefault()}
                                    onDrop={(e) => onStatDrop(e, stat.id)}
                                    className={`flex items-center justify-between p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl ${draggedStatId === stat.id ? 'opacity-50 border-dashed border-primary-500' : 'hover:border-primary-300 dark:hover:border-primary-700'}`}
                                  >
                                      <div className="flex items-center gap-3">
                                          <IconGripVertical className="w-4 h-4 text-slate-400 cursor-move hover:text-primary-500" />
                                          <span className="font-medium text-slate-700 dark:text-slate-200 text-sm">{stat.label}</span>
                                      </div>
                                      <button 
                                        onClick={() => toggleStatVisibility(stat.id)}
                                        className={`p-2 rounded-lg transition-colors ${stat.isVisible ? 'text-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-400 bg-slate-100 dark:bg-slate-800'}`}
                                      >
                                          {stat.isVisible ? <IconEye className="w-4 h-4" /> : <IconEyeOff className="w-4 h-4" />}
                                      </button>
                                  </div>
                              ))}
                          </div>
                      </div>

                      {/* Section 2: Analytics & Lists */}
                      <div>
                          <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-4">Analytics & Lists (Main Grid)</h3>
                          <div className="space-y-3">
                              {widgetsConfig.map(widget => (
                                  <div 
                                    key={widget.id}
                                    draggable
                                    onDragStart={(e) => onWidgetDragStart(e, widget.id)}
                                    onDragOver={(e) => e.preventDefault()}
                                    onDrop={(e) => onWidgetDrop(e, widget.id)}
                                    className={`flex items-center justify-between p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl ${draggedWidgetId === widget.id ? 'opacity-50 border-dashed border-primary-500' : 'hover:border-primary-300 dark:hover:border-primary-700'}`}
                                  >
                                      <div className="flex items-center gap-3">
                                          <IconGripVertical className="w-4 h-4 text-slate-400 cursor-move hover:text-primary-500" />
                                          <span className="font-medium text-slate-700 dark:text-slate-200 text-sm">{widget.label}</span>
                                          <span className="text-[10px] bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded text-slate-500 uppercase font-bold">
                                              {widget.colSpan === 2 ? 'Wide' : 'Standard'}
                                          </span>
                                      </div>
                                      <button 
                                        onClick={() => toggleWidgetVisibility(widget.id)}
                                        className={`p-2 rounded-lg transition-colors ${widget.isVisible ? 'text-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-400 bg-slate-100 dark:bg-slate-800'}`}
                                      >
                                          {widget.isVisible ? <IconEye className="w-4 h-4" /> : <IconEyeOff className="w-4 h-4" />}
                                      </button>
                                  </div>
                              ))}
                          </div>
                      </div>
                  </div>

                  <div className="p-4 border-t border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex justify-end">
                      <button 
                        onClick={() => setIsCustomizeOpen(false)}
                        className="px-6 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-xl font-bold text-sm shadow-md transition-all"
                      >
                          Done
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

