                                                            const isChecked = currentRoleState?.permissions.includes(permKey) || false;
                                                            const isDisabled = editingRole.id === 'admin' && ['manage_users', 'manage_settings', 'view_dashboard'].includes(permKey);

                                                            return (
                                                                <PermissionToggleCard 
                                                                    key={key}
                                                                    label={PERMISSION_LABELS[permKey]}
                                                                    checked={isChecked}
                                                                    disabled={isDisabled}
                                                                    onChange={() => handleTogglePermission(editingRole.id, permKey)}
                                                                />
                                                            );
                                                        })}
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </>
                            ) : (
                                <div className="flex flex-col items-center justify-center h-full text-slate-400">
                                    <IconLock className="w-12 h-12 mb-4 opacity-20" />
                                    <p className="font-medium">Select a role to configure permissions</p>
                                </div>
                            )}
                        </div>
                    </div>
                </section>
            </div>
        );

      case 'notifications':
