      const selectedRoleId = inviteRole || (roles.length > 0 ? roles[0].id : 'sales_rep');
      const newUser: User = {
          id: `u-${Date.now()}`,
          name: inviteName,
          email: inviteEmail,
          roleId: selectedRoleId,
          status: 'Active',
          lastLogin: 'Never',
          avatar: `https://i.pravatar.cc/150?u=${Date.now()}`
      };
      setUsers([newUser, ...users]);
      setIsInviteModalOpen(false);
      setInviteName('');
