  emerald: { 50: '236 253 245', 100: '209 250 229', 200: '167 243 208', 300: '110 231 183', 400: '52 211 153', 500: '16 185 129', 600: '5 150 105', 700: '4 120 87', 800: '6 95 70', 900: '6 78 59', 950: '2 44 34' }, 
  purple: { 50: '250 245 255', 100: '243 232 255', 200: '233 213 255', 300: '216 180 254', 400: '192 132 252', 500: '168 85 247', 600: '147 51 234', 700: '126 34 206', 800: '107 33 168', 900: '88 28 135', 950: '59 7 100' }, 
  orange: { 50: '255 247 237', 100: '255 237 213', 200: '254 215 170', 300: '253 186 116', 400: '251 146 60', 500: '249 115 22', 600: '234 88 12', 700: '194 65 12', 800: '154 52 18', 900: '124 45 18', 950: '67 20 7' }, 
  rose: { 50: '255 241 242', 100: '255 228 230', 200: '254 205 211', 300: '253 164 175', 400: '251 113 133', 500: '244 63 94', 600: '225 29 72', 700: '190 18 60', 800: '159 18 57', 900: '136 19 55', 950: '76 5 25' }, 
  cyan: { 50: '236 254 255', 100: '207 250 254', 200: '165 243 252', 300: '103 232 249', 400: '34 211 238', 500: '6 182 212', 600: '8 145 178', 700: '14 116 144', 800: '21 94 117', 900: '22 78 99', 950: '8 51 68' }, 
  blue: { 50: '239 246 255', 100: '219 234 254', 200: '191 219 254', 300: '147 197 253', 400: '96 165 250', 500: '59 130 246', 600: '37 99 235', 700: '29 78 216', 800: '30 64 175', 900: '30 58 138', 950: '23 37 84' },
  gray: { 50: '249 250 251', 100: '243 244 246', 200: '229 231 235', 300: '209 213 219', 400: '156 163 175', 500: '107 114 128', 600: '75 85 99', 700: '55 65 81', 800: '31 41 55', 900: '17 24 39', 950: '3 7 18' },
};

// Initial RBAC Data
const DEFAULT_ROLES: RoleDefinition[] = [
  {
    id: 'admin',
    name: 'Administrator',
    description: 'Full system access and configuration control',
    isSystem: true,
    permissions: ['view_dashboard', 'manage_users', 'manage_settings', 'view_leads', 'edit_leads', 'delete_records', 'export_data', 'view_revenue', 'manage_pipeline', 'use_ai_features']
  },
  {
    id: 'manager',
    name: 'Sales Manager',
    description: 'Can manage teams and view revenue, but cannot change system settings',
    isSystem: true,
    permissions: ['view_dashboard', 'view_leads', 'edit_leads', 'export_data', 'view_revenue', 'manage_pipeline', 'use_ai_features']
  },
  {
    id: 'sales_rep',
    name: 'Sales Representative',
    description: 'Standard access to manage own leads and deals',
    isSystem: false,
    permissions: ['view_dashboard', 'view_leads', 'edit_leads', 'manage_pipeline', 'use_ai_features']
  },
  {
    id: 'support',
    name: 'Support Agent',
    description: 'Access to ticketing and customer view only',
    isSystem: false,
    permissions: ['view_dashboard', 'view_leads']
  }
];

const VIEW_PERMISSIONS: Record<string, Permission> = {
  dashboard: 'view_dashboard',
  leads: 'view_leads',
  contacts: 'view_leads',
  accounts: 'view_leads',
  pipeline: 'manage_pipeline',
  tasks: 'view_leads',
  meetings: 'view_leads',
  calls: 'view_leads',
  campaigns: 'manage_pipeline', // Restricted to higher roles
  documents: 'view_leads',
  templates: 'manage_settings', // Restricted to admins/managers
  visits: 'view_leads',
  projects: 'view_leads',
  support: 'view_leads',
  settings: 'manage_settings', // Restricted
  'document-editor': 'view_leads'
};

export function App() {
  const [currentView, setCurrentView] = useState('dashboard');
  const [previousView, setPreviousView] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isDark, setIsDark] = useState(false);

  // Theme Settings
  const [primaryColor, setPrimaryColor] = useState('indigo');
  const [fontFamily, setFontFamily] = useState('Outfit');
  const [density, setDensity] = useState('Medium');
  const [weekStart, setWeekStart] = useState('Sunday');
  const [dateFormat, setDateFormat] = useState('DD/MM/YYYY');
  const [timeZone, setTimeZone] = useState('UTC');
  const [timeFormat, setTimeFormat] = useState<'12h' | '24h'>('12h');
  const [workingDays, setWorkingDays] = useState<string[]>(['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
  const [fiscalYearStart, setFiscalYearStart] = useState('January');

  // Finance Settings
  const [defaultPaymentTerm, setDefaultPaymentTerm] = useState('Net 30');
  const [defaultTaxRate, setDefaultTaxRate] = useState(0);
  const [taxEnabled, setTaxEnabled] = useState(false);
  const [defaultCurrency, setDefaultCurrency] = useState('USD');
  const [multiCurrency, setMultiCurrency] = useState(false);

  // RBAC & Auth State
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [roles, setRoles] = useState<RoleDefinition[]>(DEFAULT_ROLES);
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]);

  // State for data
  const [leads, setLeads] = useState<Lead[]>(MOCK_LEADS);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);
  const [meetings, setMeetings] = useState<Meeting[]>(MOCK_MEETINGS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [accounts, setAccounts] = useState<Account[]>(MOCK_ACCOUNTS);
  const [calls, setCalls] = useState<Call[]>(MOCK_CALLS);
  const [campaigns, setCampaigns] = useState<Campaign[]>(MOCK_CAMPAIGNS);
  const [documents, setDocuments] = useState<Document[]>(MOCK_DOCUMENTS);
  const [visits, setVisits] = useState<Visit[]>(MOCK_VISITS);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);
  const [tickets, setTickets] = useState<Ticket[]>(MOCK_TICKETS);
  const [editingDocument, setEditingDocument] = useState<Document | null>(null);

  const [pipelineGoal, setPipelineGoal] = useState<number>(() => {
    const saved = localStorage.getItem('nova_pipeline_goal');
    return saved ? Number(saved) : 5000000;
  });

  // Calculate current user role for RBAC
  const userRole = roles.find(r => r.id === currentUser.roleId) || DEFAULT_ROLES[2];

  // Auth Initialization
  useEffect(() => {
    const initAuth = async () => {
      // Check if current token is valid
      if (authService.isAuthenticated()) {
        const user = authService.getCurrentUser();
        if (user) {
          setCurrentUser(user);
          setIsAuthenticated(true);
        }
      } else {
        // Try refresh token logic
        const refreshedToken = await authService.refreshSession();
        if (refreshedToken) {
           const user = authService.getCurrentUser();
           if (user) {
             setCurrentUser(user);
             setIsAuthenticated(true);
           }
        }
      }
      setIsLoadingAuth(false);
    };
    initAuth();
  }, []);

  const handleLogin = async (email: string, password?: string): Promise<boolean> => {
    const response = await authService.login(email, password);
    if (response) {
      setCurrentUser(response.user);
      setIsAuthenticated(true);
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    authService.logout();
    setIsAuthenticated(false);
  };

  const handleSetPipelineGoal = (goal: number) => {
    setPipelineGoal(goal);
    localStorage.setItem('nova_pipeline_goal', goal.toString());
  };

  const handleNavigateToTasks = () => {
    setCurrentView('tasks');
  };

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  useEffect(() => {
    const root = document.documentElement;
    const themeColors = THEMES[primaryColor] || THEMES.indigo;

    Object.keys(themeColors).forEach((key) => {
      root.style.setProperty(`--color-primary-${key}`, themeColors[Number(key)]);
    });

    const fontMap: Record<string, string> = {
      'Plus Jakarta': "'Plus Jakarta Sans', sans-serif",
      'Plus Jakarta Sans': "'Plus Jakarta Sans', sans-serif",
      'Inter UI': "'Inter', sans-serif",
      'Montserrat': "'Montserrat', sans-serif",
      'Outfit': "'Outfit', sans-serif",
      'Lexend': "'Lexend', sans-serif",
      'Playfair Display': "'Playfair Display', serif",
    };
    root.style.setProperty('--font-family', fontMap[fontFamily] || "'Outfit', sans-serif");

    const sizeMap: Record<string, string> = {
      'Small': '14px',
      'Medium': '16px',
      'Large': '17px',
      'XL': '18px'
    };
    root.style.setProperty('--base-font-size', sizeMap[density] || '16px');
    root.style.fontSize = sizeMap[density] || '16px';

  }, [primaryColor, fontFamily, density]);

  const toggleTheme = () => setIsDark(!isDark);

  // Data Handlers
  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50,
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: currentUser.name,
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    } as Contact;
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddAccount = (newAccount: Account) => {
    setAccounts(prevAccounts => [...prevAccounts, newAccount]);
  };

  const handleUpdateAccount = (updatedAccount: Account) => {
    setAccounts(prevAccounts => prevAccounts.map(a => 
      a.id === updatedAccount.id ? updatedAccount : a
    ));
  };

  const handleDeleteAccount = (accountId: string) => {
    setAccounts(prevAccounts => prevAccounts.filter(a => a.id !== accountId));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddMeeting = (newMeeting: Meeting) => {
    setMeetings(prev => [...prev, newMeeting]);
  };

  const handleUpdateMeeting = (updatedMeeting: Meeting) => {
    setMeetings(prev => prev.map(m => m.id === updatedMeeting.id ? updatedMeeting : m));
  };

  const handleDeleteMeeting = (meetingId: string) => {
    setMeetings(prev => prev.filter(m => m.id !== meetingId));
  };

  const handleAddDeal = (newDeal: Deal) => {
    const activities = newDeal.activities && newDeal.activities.length > 0 
      ? newDeal.activities 
      : [{
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }];

    const dealWithActivity = {
      ...newDeal,
      activities
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({ id: Date.now().toString() + 's', type: 'stage_change', description: `Stage updated to ${updatedDeal.stage}`, timestamp });
      }
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({ id: Date.now().toString() + 'v', type: 'value_change', description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`, timestamp });
      }
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({ id: Date.now().toString() + 'p', type: 'probability_change', description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`, timestamp });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);
      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({ id: Date.now().toString() + 'u', type: 'update', description: `Deal details updated`, timestamp });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const handleAddTask = (newTask: Task) => {
    setTasks(prev => [newTask, ...prev]);
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const handleAddCampaign = (newCampaign: Campaign) => {
    setCampaigns(prev => [...prev, newCampaign]);
  };

  const handleUpdateCampaign = (updatedCampaign: Campaign) => {
    setCampaigns(prev => prev.map(c => c.id === updatedCampaign.id ? updatedCampaign : c));
  };

  const handleDeleteCampaign = (campaignId: string) => {
    setCampaigns(prev => prev.filter(c => c.id !== campaignId));
  };

  const handleAddDocument = (newDoc: Document) => {
    setDocuments(prev => [newDoc, ...prev]);
  };

  const handleDeleteDocument = (docId: string) => {
    setDocuments(prev => prev.filter(d => d.id !== docId));
  };

  const handleUpdateDocument = (updatedDoc: Document) => {
    setDocuments(prev => prev.map(d => d.id === updatedDoc.id ? updatedDoc : d));
  };

  const handleAddVisit = (newVisit: Visit) => {
    setVisits(prev => [newVisit, ...prev]);
  };

  const handleUpdateVisit = (updatedVisit: Visit) => {
    setVisits(prev => prev.map(v => v.id === updatedVisit.id ? updatedVisit : v));
  };

  const handleDeleteVisit = (visitId: string) => {
    setVisits(prev => prev.filter(v => v.id !== visitId));
  };

  const handleAddProject = (newProject: Project) => {
    setProjects(prev => [...prev, newProject]);
  };

  const handleUpdateProject = (updatedProject: Project) => {
    setProjects(prev => prev.map(p => p.id === updatedProject.id ? updatedProject : p));
  };

  const handleDeleteProject = (projectId: string) => {
    setProjects(prev => prev.filter(p => p.id !== projectId));
  };

  const handleAddTicket = (newTicket: Ticket) => {
    setTickets(prev => [...prev, newTicket]);
  };

  const handleUpdateTicket = (updatedTicket: Ticket) => {
    setTickets(prev => prev.map(t => t.id === updatedTicket.id ? updatedTicket : t));
  };

  const handleDeleteTicket = (ticketId: string) => {
    setTickets(prev => prev.filter(t => t.id !== ticketId));
  };

  // Handler to open the document editor
  const handleEditDocument = (doc: Document) => {
      setEditingDocument(doc);
      setPreviousView(currentView);
      setCurrentView('document-editor');
  };

  const handleCloseEditor = () => {
      setEditingDocument(null);
      setCurrentView(previousView); // Return to where we came from
  };

  const renderContent = () => {
    // Permission Access Control Check
    const requiredPerm = VIEW_PERMISSIONS[currentView];
    if (requiredPerm && !userRole.permissions.includes(requiredPerm)) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-center p-8 animate-fade-in">
                <div className="p-4 bg-slate-100 dark:bg-slate-800 rounded-full mb-4">
                    <IconLock className="w-12 h-12 text-slate-400" />
                </div>
                <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">Access Denied</h2>
                <p className="text-slate-500 dark:text-slate-400 max-w-md mb-6">
                    You do not have permission to view this module. Please contact your administrator if you believe this is an error.
                </p>
                <button 
                    onClick={() => setCurrentView('dashboard')}
                    className="px-6 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg font-medium transition-colors"
                >
                    Return to Dashboard
                </button>
            </div>
        );
    }

    switch (currentView) {
      case 'dashboard':
        return <Dashboard 
            leads={leads} 
            deals={deals} 
            tasks={tasks} 
            meetings={meetings} 
            isDark={isDark} 
            pipelineGoal={pipelineGoal}
            userRole={userRole} 
        />;
      case 'leads':
        return <Leads 
            leads={leads}
            accounts={accounts} 
            contacts={contacts}
            onAddLead={handleAddLead} 
            onUpdateLead={handleUpdateLead} 
            onDeleteLeads={handleDeleteLeads} 
            onAddDeal={handleAddDeal} 
            onViewOpportunities={() => setCurrentView('pipeline')}
            onAddDocument={handleAddDocument}
            documents={documents}
            onUpdateDocument={handleUpdateDocument}
            onDeleteDocument={handleDeleteDocument}
            onEditDocument={handleEditDocument} 
            calls={calls}
            onAddCall={handleAddCall}
            userRole={userRole}
        />;
      case 'pipeline':
        return <Pipeline 
            deals={deals}
            accounts={accounts}
            contacts={contacts}
            onAddDeal={handleAddDeal} 
            onUpdateDeal={handleUpdateDeal} 
            pipelineGoal={pipelineGoal} 
            onSetGoal={handleSetPipelineGoal} 
            userRole={userRole}
        />;
      case 'tasks':
        return <Tasks tasks={tasks} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />;
      case 'meetings':
        return <Meetings 
          meetings={meetings} 
          contacts={contacts}
          accounts={accounts}
          onAddMeeting={handleAddMeeting} 
          onUpdateMeeting={handleUpdateMeeting} 
          onDeleteMeeting={handleDeleteMeeting}
        />;
      case 'contacts':
        return <Contacts 
          contacts={contacts} 
          accounts={accounts}
          onAddContact={handleAddContact} 
          onUpdateContact={handleUpdateContact} 
        />;
      case 'accounts':
        return <Accounts 
          accounts={accounts} 
          contacts={contacts} 
          deals={deals}
          leads={leads}
          meetings={meetings}
          calls={calls}
          onAddAccount={handleAddAccount} 
          onUpdateAccount={handleUpdateAccount} 
          onDeleteAccount={handleDeleteAccount}
          onAddContact={handleAddContact}
          onAddCall={handleAddCall}
          onAddDocument={handleAddDocument}
          onEditDocument={handleEditDocument}
          userRole={userRole}
        />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} accounts={accounts} onAddCall={handleAddCall} />;
      case 'campaigns': 
        return <Campaigns 
          campaigns={campaigns} 
          onAddCampaign={handleAddCampaign} 
          onUpdateCampaign={handleUpdateCampaign} 
          onDeleteCampaign={handleDeleteCampaign} 
        />;
      case 'documents':
        return <Documents 
          documents={documents}
          onAddDocument={handleAddDocument}
          onUpdateDocument={handleUpdateDocument}
          onDeleteDocument={handleDeleteDocument}
          onEditDocument={handleEditDocument}
        />;
      case 'templates':
        return <Templates />;
      case 'document-editor':
        return editingDocument ? (
            <DocumentEditor 
                document={editingDocument}
                onSave={(updatedDoc) => {
                    handleUpdateDocument(updatedDoc);
                    handleCloseEditor();
                }}
                onClose={handleCloseEditor}
            />
        ) : <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} userRole={userRole} />;
      case 'settings':
        return <Settings 
          isDark={isDark} 
          toggleTheme={toggleTheme} 
          primaryColor={primaryColor} 
          setPrimaryColor={setPrimaryColor} 
          pipelineGoal={pipelineGoal}
          setPipelineGoal={handleSetPipelineGoal}
          fontFamily={fontFamily}
          setFontFamily={setFontFamily}
          density={density}
          setDensity={setDensity}
          weekStart={weekStart}
          setWeekStart={setWeekStart}
          dateFormat={dateFormat}
          setDateFormat={setDateFormat}
          timeZone={timeZone}
          setTimeZone={setTimeZone}
          timeFormat={timeFormat}
          setTimeFormat={setTimeFormat}
          workingDays={workingDays}
          setWorkingDays={setWorkingDays}
          fiscalYearStart={fiscalYearStart}
          setFiscalYearStart={setFiscalYearStart}
          // Finance
          defaultPaymentTerm={defaultPaymentTerm}
          setDefaultPaymentTerm={setDefaultPaymentTerm}
          defaultTaxRate={defaultTaxRate}
          setDefaultTaxRate={setDefaultTaxRate}
          taxEnabled={taxEnabled}
          setTaxEnabled={setTaxEnabled}
          defaultCurrency={defaultCurrency}
          setDefaultCurrency={setDefaultCurrency}
          multiCurrency={multiCurrency}
          setMultiCurrency={setMultiCurrency}
          // RBAC
          roles={roles}
          setRoles={setRoles}
          users={users}
          setUsers={setUsers}
          currentUser={currentUser}
          setCurrentUser={setCurrentUser}
        />;
      case 'visits': 
        return <Visits 
          visits={visits}
          accounts={accounts}
          onAddVisit={handleAddVisit}
          onUpdateVisit={handleUpdateVisit}
          onDeleteVisit={handleDeleteVisit}
        />;
      case 'projects': 
        return <Projects
          projects={projects}
          tasks={tasks} // Pass tasks to Project management
          onAddProject={handleAddProject}
          onUpdateProject={handleUpdateProject}
          onDeleteProject={handleDeleteProject}
          onAddTask={handleAddTask} // Pass ability to add tasks from project view
        />;
      case 'support':
        return <Support 
          tickets={tickets}
          accounts={accounts}
          onAddTicket={handleAddTicket}
          onUpdateTicket={handleUpdateTicket}
          onDeleteTicket={handleDeleteTicket}
        />;
      default: return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} userRole={userRole} />;
    }
  };

  if (isLoadingAuth) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-900 text-white">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-white"></div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Auth onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-primary-500/30 transition-colors duration-300">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Hide Sidebar when editing document to use full screen */}
      {currentView !== 'document-editor' && (
          <Sidebar 
            currentView={currentView} 
            setView={(view) => { setCurrentView(view); setSidebarOpen(false); }} 
            isOpen={sidebarOpen}
            isDark={isDark}
            toggleTheme={toggleTheme}
            userRole={userRole} // Pass RBAC role
            onLogout={handleLogout}
          />
      )}

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <div className="absolute inset-0 z-0 pointer-events-none bg-grid-pattern dark:bg-grid-pattern-dark bg-grid opacity-[0.03] dark:opacity-[0.05]"></div>

        {currentView !== 'document-editor' && (
            <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300 z-10">
            <div className="flex items-center">
                <button onClick={() => setSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
                <IconMenu className="w-6 h-6" />
                </button>
                <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
            </div>
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </header>
        )}

        {currentView !== 'settings' && currentView !== 'document-editor' && (
            <div className="hidden md:block absolute top-6 right-8 z-20">
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </div>
        )}

        <main className={`flex-1 overflow-x-hidden overflow-y-auto bg-transparent relative z-0 ${currentView === 'document-editor' ? '' : 'p-4 md:p-8 pt-4 md:pt-8 custom-scrollbar'}`}>
          {renderContent()}
        </main>

        {currentView !== 'document-editor' && <AIChat leads={leads} deals={deals} />}
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Project, ProjectStatus, Task } from '../types';
import { 
  IconBriefcase, IconPlus, IconSearch, IconFilter, IconCalendar, 
  IconUser, IconEdit, IconTrash, IconSparkles, IconCheckCircle, 
  IconAlertTriangle, IconList, IconKanban, IconArrowUp, IconArrowDown
} from './Icons';
import { generateProjectPlan, assessProjectRisks } from '../services/geminiService';
import ProjectDetail from './ProjectDetail';

interface ProjectsProps {
  projects: Project[];
  tasks?: Task[]; // Added tasks prop
  onAddProject: (project: Project) => void;
  onUpdateProject: (project: Project) => void;
  onDeleteProject: (id: string) => void;
  onAddTask?: (task: Task) => void; // Added onAddTask prop
}

const PROJECT_STATUSES: ProjectStatus[] = ['Planning', 'In Progress', 'On Hold', 'Completed'];

const Projects: React.FC<ProjectsProps> = ({ projects, tasks = [], onAddProject, onUpdateProject, onDeleteProject, onAddTask = () => {} }) => {
  const [viewMode, setViewMode] = useState<'kanban' | 'list'>('kanban');
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isDetailView, setIsDetailView] = useState(false); // New state for detail view

  // AI Loading States
  const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
  const [isAssessingRisks, setIsAssessingRisks] = useState(false);

  // List View Sorting
  const [sortConfig, setSortConfig] = useState<{ key: keyof Project; direction: 'asc' | 'desc' } | null>(null);

  const [formData, setFormData] = useState<Partial<Project>>({
    name: '',
    status: 'Planning',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    budget: 0,
    spent: 0,
    progress: 0,
    owner: 'Alex Chen',
    client: '',
    description: '',
    riskLevel: 'Low',
    riskFactors: []
  });

  const filteredProjects = useMemo(() => {
    return projects.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.client?.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [projects, searchQuery]);

  const sortedProjects = useMemo(() => {
      let items = [...filteredProjects];
      if (sortConfig) {
          items.sort((a, b) => {
              const aVal = a[sortConfig.key] || '';
              const bVal = b[sortConfig.key] || '';
              if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
              if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
              return 0;
          });
      }
      return items;
  }, [filteredProjects, sortConfig]);

  const handleSort = (key: keyof Project) => {
      let direction: 'asc' | 'desc' = 'asc';
      if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
      setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Project) => {
      if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0">↕</span>;
      return sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />;
  };

  const handleOpenModal = (project?: Project) => {
    if (project) {
      setSelectedProject(project);
      setFormData(project);
    } else {
      setSelectedProject(null);
      setFormData({
        name: '',
        status: 'Planning',
        startDate: new Date().toISOString().split('T')[0],
        endDate: '',
        budget: 0,
        spent: 0,
        progress: 0,
        owner: 'Alex Chen',
        client: '',
        description: '',
        riskLevel: 'Low',
        riskFactors: []
      });
    }
    setIsModalOpen(true);
  };

  const handleOpenDetail = (project: Project) => {
      setSelectedProject(project);
      setIsDetailView(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const projectData = {
        id: selectedProject ? selectedProject.id : `PRJ-${Date.now()}`,
        name: formData.name || '',
        status: formData.status as ProjectStatus,
        startDate: formData.startDate || '',
        endDate: formData.endDate || '',
        budget: Number(formData.budget) || 0,
        spent: Number(formData.spent) || 0,
        progress: Number(formData.progress) || 0,
        owner: formData.owner || '',
        client: formData.client || '',
        description: formData.description || '',
        riskLevel: formData.riskLevel as any,
        nextMilestone: formData.nextMilestone,
        riskFactors: formData.riskFactors
    };

    if (selectedProject) {
        onUpdateProject(projectData);
        if (isDetailView) setSelectedProject(projectData); // Update detail view data if open
    } else {
        onAddProject(projectData);
    }
    setIsModalOpen(false);
  };

  const handleGeneratePlan = async () => {
      if (!formData.name) {
          alert("Please enter a project name first.");
          return;
      }
      setIsGeneratingPlan(true);
      const plan = await generateProjectPlan(formData);
      setFormData(prev => ({
          ...prev,
          description: plan.description,
          nextMilestone: plan.nextMilestone,
          riskLevel: plan.riskLevel,
          riskFactors: plan.riskFactors || []
      }));
      setIsGeneratingPlan(false);
  };

  const handleRiskAssessment = async (project: Project) => {
      setIsAssessingRisks(true);
      const risks = await assessProjectRisks(project);
      onUpdateProject({ ...project, riskFactors: risks });
      setIsAssessingRisks(false);
  };

  // Drag & Drop
  const handleDragStart = (e: React.DragEvent, projectId: string) => {
      e.dataTransfer.setData('projectId', projectId);
  };

  const handleDrop = (e: React.DragEvent, status: ProjectStatus) => {
      const projectId = e.dataTransfer.getData('projectId');
      const project = projects.find(p => p.id === projectId);
      if (project && project.status !== status) {
          onUpdateProject({ ...project, status });
      }
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault();
  };

  const getRiskColor = (level?: string) => {
      switch(level) {
          case 'High': return 'text-red-600 bg-red-100 dark:text-red-400 dark:bg-red-900/30';
          case 'Medium': return 'text-amber-600 bg-amber-100 dark:text-amber-400 dark:bg-amber-900/30';
          case 'Low': return 'text-emerald-600 bg-emerald-100 dark:text-emerald-400 dark:bg-emerald-900/30';
          default: return 'text-slate-500 bg-slate-100 dark:text-slate-400 dark:bg-slate-800';
      }
  };

  if (isDetailView && selectedProject) {
      return (
          <ProjectDetail 
              project={selectedProject}
              tasks={tasks}
              onBack={() => setIsDetailView(false)}
              onUpdate={onUpdateProject}
              onDelete={() => { onDeleteProject(selectedProject.id); setIsDetailView(false); }}
              onAddTask={onAddTask}
          />
      );
  }

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
        {/* Header */}
        <div className="flex justify-between items-center flex-shrink-0 md:pr-20">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Project Management</h1>
            <div className="flex gap-3">
                <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                    <button onClick={() => setViewMode('kanban')} className={`p-2 rounded-lg transition-all ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`} title="Kanban View"><IconKanban className="w-4 h-4" /></button>
                    <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`} title="List View"><IconList className="w-4 h-4" /></button>
                </div>
                <button 
                    onClick={() => handleOpenModal()}
                    className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
                >
                    <IconPlus className="w-4 h-4 mr-2" /> New Project
                </button>
            </div>
        </div>

        {/* View Content */}
        {viewMode === 'kanban' ? (
            <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4 custom-scrollbar">
                <div className="h-full flex gap-6 min-w-full">
                    {PROJECT_STATUSES.map(status => (
                        <div 
                            key={status}
                            onDragOver={handleDragOver}
                            onDrop={(e) => handleDrop(e, status)}
                            className="flex flex-col w-80 bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl flex-shrink-0"
                        >
                            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-100/50 dark:bg-slate-900/50 rounded-t-xl">
                                <h3 className="font-bold text-slate-700 dark:text-slate-200">{status}</h3>
                                <span className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 text-xs font-bold px-2 py-0.5 rounded-full">
                                    {filteredProjects.filter(p => p.status === status).length}
                                </span>
                            </div>
                            <div className="flex-1 p-3 space-y-3 overflow-y-auto custom-scrollbar">
                                {filteredProjects.filter(p => p.status === status).map(project => (
                                    <div 
                                        key={project.id}
                                        draggable
                                        onDragStart={(e) => handleDragStart(e, project.id)}
                                        onClick={() => handleOpenDetail(project)}
                                        className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md cursor-pointer group transition-all relative"
                                    >
                                        <div className="flex justify-between items-start mb-2">
                                            <div>
                                                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full mb-1 inline-block ${getRiskColor(project.riskLevel)}`}>
                                                    {project.riskLevel} Risk
                                                </span>
                                                <h4 className="font-bold text-slate-900 dark:text-white text-sm leading-tight group-hover:text-primary-600 transition-colors">{project.name}</h4>
                                                {project.client && <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{project.client}</p>}
                                            </div>
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); handleOpenModal(project); }} 
                                                className="p-1 text-slate-400 hover:text-slate-600 dark:hover:text-white opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                <IconEdit className="w-3.5 h-3.5" />
                                            </button>
                                        </div>

                                        <div className="mt-3 mb-2">
                                            <div className="flex justify-between text-xs mb-1">
                                                <span className="text-slate-500">Progress</span>
                                                <span className="font-bold text-primary-600 dark:text-primary-400">{project.progress}%</span>
                                            </div>
                                            <div className="w-full bg-slate-100 dark:bg-slate-700 rounded-full h-1.5 overflow-hidden">
                                                <div className="bg-primary-500 h-1.5 rounded-full transition-all duration-500" style={{ width: `${project.progress}%` }}></div>
                                            </div>
                                        </div>

                                        <div className="space-y-2 mt-3 pt-3 border-t border-slate-50 dark:border-slate-700/50">
                                            <div className="flex items-center text-xs text-slate-500 dark:text-slate-400">
                                                <IconCalendar className="w-3 h-3 mr-1.5" />
                                                {project.endDate ? `Due ${new Date(project.endDate).toLocaleDateString()}` : 'No due date'}
                                            </div>
                                            {project.nextMilestone && (
                                                <div className="flex items-center text-xs text-indigo-600 dark:text-indigo-400 font-medium">
                                                    <IconCheckCircle className="w-3 h-3 mr-1.5" />
                                                    {project.nextMilestone}
                                                </div>
                                            )}
                                        </div>

                                        {(!project.riskFactors || project.riskFactors.length === 0) && (
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); handleRiskAssessment(project); }}
                                                disabled={isAssessingRisks}
                                                className="mt-3 w-full py-1.5 bg-slate-50 dark:bg-slate-700/50 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 text-xs rounded-lg flex items-center justify-center transition-colors opacity-0 group-hover:opacity-100"
                                            >
                                                <IconSparkles className="w-3 h-3 mr-1.5" /> Assess Risks
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        ) : (
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
                <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                    <div className="relative max-w-md w-full">
                        <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input type="text" placeholder="Search projects..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" />
                    </div>
                </div>
                <div className="overflow-auto flex-1 custom-scrollbar">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
                            <tr>
                                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('name')}><div className="flex items-center gap-1">Project Name {getSortIcon('name')}</div></th>
                                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('client')}><div className="flex items-center gap-1">Client {getSortIcon('client')}</div></th>
                                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('status')}><div className="flex items-center gap-1">Status {getSortIcon('status')}</div></th>
                                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('progress')}><div className="flex items-center gap-1">Progress {getSortIcon('progress')}</div></th>
                                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('budget')}><div className="flex items-center gap-1">Budget {getSortIcon('budget')}</div></th>
                                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('endDate')}><div className="flex items-center gap-1">Due Date {getSortIcon('endDate')}</div></th>
                                <th className="px-6 py-4 font-medium text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                            {sortedProjects.map(project => (
                                <tr key={project.id} onClick={() => handleOpenDetail(project)} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group">
                                    <td className="px-6 py-4 font-medium text-slate-900 dark:text-white">{project.name}</td>
                                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{project.client || '-'}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold uppercase ${
                                            project.status === 'In Progress' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400' :
                                            project.status === 'Completed' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' :
                                            project.status === 'On Hold' ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400' :
                                            'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                                        }`}>
                                            {project.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="w-24 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                                                <div className="bg-primary-500 h-full rounded-full" style={{ width: `${project.progress}%` }}></div>
                                            </div>
                                            <span className="text-xs text-slate-500">{project.progress}%</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">${project.budget.toLocaleString()}</td>
                                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{project.endDate || '-'}</td>
                                    <td className="px-6 py-4 text-right">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDeleteProject(project.id); }} 
                                            className="p-2 text-slate-400 hover:text-red-600 transition-colors opacity-0 group-hover:opacity-100"
                                        >
                                            <IconTrash className="w-4 h-4" />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        )}

        {/* Modal */}
        {isModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in flex flex-col max-h-[90vh]">
                    <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                        <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                            <IconBriefcase className="w-5 h-5 mr-3 text-primary-500" />
                            {selectedProject ? 'Edit Project' : 'New Project'}
                        </h2>
                        <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconPlus className="w-6 h-6 rotate-45" /></button>
                    </div>

                    <div className="p-6 overflow-y-auto">
                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* AI Assistant Banner */}
                            <div className="bg-gradient-to-r from-indigo-50 to-purple-50 dark:from-indigo-900/20 dark:to-purple-900/20 p-4 rounded-xl border border-indigo-100 dark:border-indigo-800/30 flex items-center justify-between">
                                <div>
                                    <h3 className="text-sm font-bold text-indigo-900 dark:text-indigo-100 flex items-center">
                                        <IconSparkles className="w-4 h-4 mr-2" /> AI Project Planner
                                    </h3>
                                    <p className="text-xs text-indigo-700 dark:text-indigo-300 mt-1">
                                        Auto-generate description, milestones, and risk assessment based on name & budget.
                                    </p>
                                </div>
                                <button 
                                    type="button"
                                    onClick={handleGeneratePlan}
                                    disabled={isGeneratingPlan || !formData.name}
                                    className="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold rounded-lg shadow-sm transition-all disabled:opacity-50"
                                >
                                    {isGeneratingPlan ? 'Generating...' : 'Auto-Fill Details'}
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Project Name</label>
                                    <input 
                                        type="text" 
                                        value={formData.name} 
                                        onChange={(e) => setFormData({...formData, name: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500"
                                        required 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Client</label>
                                    <input 
                                        type="text" 
                                        value={formData.client} 
                                        onChange={(e) => setFormData({...formData, client: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500"
                                        placeholder="Optional"
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Start Date</label>
                                    <input 
                                        type="date" 
                                        value={formData.startDate} 
                                        onChange={(e) => setFormData({...formData, startDate: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">End Date</label>
                                    <input 
                                        type="date" 
                                        value={formData.endDate} 
                                        onChange={(e) => setFormData({...formData, endDate: e.target.value})} 
                                        className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500"
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-3 gap-6">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Budget ($)</label>
                                    <input 
                                        type="number" 
                                        value={formData.budget} 
