                        <div className="pt-2 flex justify-end gap-3">
                            <button type="button" onClick={() => setIsCreateRoleModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg">Cancel</button>
                            <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-primary-600 hover:bg-primary-500 rounded-lg shadow-md">Create Role</button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* Password Reset Modal */}
        {passwordModalOpen && selectedUserForPassword && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="w-full max-w-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
                            <IconKey className="w-8 h-8 text-emerald-600 dark:text-emerald-400" />
                        </div>
                        <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Password Reset</h2>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">
                            Temporary password generated for <strong>{selectedUserForPassword.name}</strong>.
                        </p>

                        <div className="bg-slate-100 dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex items-center justify-between mb-6">
                            <code className="text-lg font-mono font-bold text-slate-800 dark:text-slate-200 tracking-wide">{generatedPassword}</code>
                            <button 
                                onClick={() => copyToClipboard(generatedPassword)}
                                className="p-2 text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"
