                                              cy="50%"
                                              innerRadius={60}
                                              outerRadius={80}
                                              paddingAngle={5}
                                              dataKey="value"
                                          >
                                              {/* Positive, Neutral, Negative colors */}
                                              <Cell fill="#10b981" />
                                              <Cell fill="#f59e0b" />
                                              <Cell fill="#ef4444" />
                                          </Pie>
                                          <Tooltip />
                                          <Legend verticalAlign="bottom" height={36}/>
                                      </PieChart>
                                  </ResponsiveContainer>
