                            </div>

                            {/* AI Content Generator Section */}
                            <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-slate-800 dark:to-slate-800/50 p-4 rounded-xl border border-purple-100 dark:border-slate-700">
                                <div className="flex items-center justify-between mb-3">
                                    <h3 className="text-sm font-bold text-purple-800 dark:text-purple-300 flex items-center">
                                        <IconSparkles className="w-4 h-4 mr-2" /> AI Content Assistant
                                    </h3>
                                    <button 
                                        type="button" 
                                        onClick={handleGenerateContent}
                                        disabled={isGenerating || !formData.name}
                                        className="text-xs bg-purple-600 hover:bg-purple-700 text-white px-3 py-1.5 rounded-lg transition-colors font-medium disabled:opacity-50 flex items-center gap-1"
                                    >
                                        {isGenerating ? <span className="animate-spin">⟳</span> : <IconSparkles className="w-3 h-3" />}
                                        {formData.type === 'Email' ? 'Draft Email' : 'Generate Strategy'}
                                    </button>
                                </div>
                                <input 
                                    type="text" 
                                    value={aiContext}
                                    onChange={(e) => setAiContext(e.target.value)}
                                    placeholder="Brief goal (e.g. 'Targeting CTOs for new AI tool launch')"
                                    className="w-full px-3 py-2 bg-white dark:bg-slate-900 border border-purple-200 dark:border-slate-600 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-purple-500 placeholder-slate-400"
                                />
                                <p className="text-[10px] text-slate-500 dark:text-slate-400 mt-2">
                                    Uses campaign details & budget to generate professional content.
                                </p>
                            </div>

                            {/* Predictive Segmentation Section */}
                            <div className="bg-gradient-to-br from-indigo-50 to-blue-50 dark:from-indigo-900/20 dark:to-blue-900/10 p-5 rounded-xl border border-indigo-100 dark:border-indigo-800/30">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold text-indigo-800 dark:text-indigo-300 flex items-center">
                                        <IconTarget className="w-4 h-4 mr-2" /> Predictive Segmentation
                                    </h3>
                                    <button 
                                        type="button" 
                                        onClick={handlePredictSegments}
                                        disabled={isSegmenting || !formData.name}
                                        className="text-xs bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-1.5 rounded-lg transition-colors font-medium disabled:opacity-50 flex items-center gap-1 shadow-sm"
                                    >
                                        {isSegmenting ? <span className="animate-spin">⟳</span> : <IconTarget className="w-3 h-3" />}
                                        Generate Segments
                                    </button>
                                </div>

                                {generatedSegments.length > 0 ? (
                                    <div className="grid grid-cols-1 gap-3">
                                        {generatedSegments.map((segment, idx) => (
                                            <div 
                                                key={idx} 
                                                onClick={() => selectSegment(segment)}
                                                className="bg-white dark:bg-slate-800 p-3 rounded-lg border border-indigo-100 dark:border-slate-700 hover:border-indigo-400 dark:hover:border-indigo-500 cursor-pointer transition-all shadow-sm group"
                                            >
                                                <div className="flex justify-between items-start mb-1">
                                                    <h4 className="font-bold text-sm text-slate-900 dark:text-white group-hover:text-indigo-600 dark:group-hover:text-indigo-400">{segment.name}</h4>
                                                    <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-0.5 rounded-full">
                                                        {segment.conversionProbability} Conv.
                                                    </span>
                                                </div>
                                                <p className="text-xs text-slate-600 dark:text-slate-300 mb-1"><strong>Who:</strong> {segment.demographics}</p>
                                                <p className="text-xs text-slate-500 dark:text-slate-400"><strong>Behavior:</strong> {segment.behavior}</p>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <p className="text-xs text-indigo-600/70 dark:text-indigo-300/70 italic text-center py-2">
                                        Use AI to identify high-value audiences based on behavior & demographics.
                                    </p>
                                )}
                            </div>

                            {/* A/B Testing Section */}
                            <div className="bg-gradient-to-br from-orange-50 to-amber-50 dark:from-orange-900/20 dark:to-amber-900/10 p-5 rounded-xl border border-orange-100 dark:border-orange-800/30">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold text-orange-800 dark:text-orange-300 flex items-center">
                                        <IconFlask className="w-4 h-4 mr-2" /> A/B Optimization
                                    </h3>
                                    <button 
                                        type="button" 
                                        onClick={handleGenerateABTests}
                                        disabled={isGeneratingAB || !formData.name}
                                        className="text-xs bg-orange-600 hover:bg-orange-700 text-white px-3 py-1.5 rounded-lg transition-colors font-medium disabled:opacity-50 flex items-center gap-1 shadow-sm"
                                    >
                                        {isGeneratingAB ? <span className="animate-spin">⟳</span> : <IconFlask className="w-3 h-3" />}
                                        Generate Experiments
                                    </button>
                                </div>

                                {abTestSuggestions.length > 0 ? (
                                    <div className="space-y-4">
                                        {abTestSuggestions.map((test, idx) => (
                                            <div key={idx} className="bg-white dark:bg-slate-800 p-4 rounded-lg border border-orange-100 dark:border-slate-700 shadow-sm">
                                                <div className="flex justify-between items-center mb-3">
                                                    <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Experiment: {test.element}</span>
                                                    <span className="text-xs font-bold text-orange-600 bg-orange-100 dark:bg-orange-900/30 px-2 py-0.5 rounded">Split: {test.split}</span>
                                                </div>
                                                <div className="grid grid-cols-2 gap-4 mb-3">
                                                    <div className="p-3 bg-slate-50 dark:bg-slate-900 rounded border border-slate-200 dark:border-slate-700">
                                                        <span className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Variation A (Control)</span>
                                                        <p className="text-sm text-slate-800 dark:text-slate-200 font-medium">{test.variationA}</p>
                                                    </div>
                                                    <div className="p-3 bg-indigo-50 dark:bg-indigo-900/20 rounded border border-indigo-100 dark:border-indigo-800/30">
                                                        <span className="block text-[10px] font-bold text-indigo-400 uppercase mb-1">Variation B (Challenger)</span>
                                                        <p className="text-sm text-indigo-900 dark:text-indigo-100 font-medium">{test.variationB}</p>
                                                    </div>
                                                </div>
                                                <p className="text-xs text-slate-500 dark:text-slate-400 italic border-l-2 border-orange-300 pl-2">
                                                    Hypothesis: {test.hypothesis}
                                                </p>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <p className="text-xs text-orange-600/70 dark:text-orange-300/70 italic text-center py-2">
                                        Generate AI-driven A/B tests to optimize performance.
                                    </p>
                                )}
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                                    {formData.type === 'Email' ? 'Email Content & Strategy' : 'Description & Strategy'}
                                </label>
                                <textarea 
                                    value={formData.description || ''} 
                                    onChange={(e) => setFormData({...formData, description: e.target.value})} 
                                    rows={6}
                                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white resize-none font-sans" 
                                    placeholder={formData.type === 'Email' ? "Subject: ...\n\nBody: ..." : "Campaign goals and details..."}
                                />
                            </div>

                            {/* Target Audience Field */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Target Audience</label>
                                <textarea 
                                    value={formData.targetAudience || ''} 
                                    onChange={(e) => setFormData({...formData, targetAudience: e.target.value})} 
                                    rows={2}
                                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white resize-none font-sans text-sm" 
                                    placeholder="e.g. CTOs in Fintech companies with >50 employees..."
                                />
                            </div>

                            <div className="pt-4 flex gap-3 justify-end border-t border-slate-100 dark:border-slate-800">
                                {selectedCampaign && (
                                    <button 
                                        type="button"
                                        onClick={handleDelete}
                                        className="mr-auto px-4 py-2.5 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 rounded-xl hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors flex items-center"
                                    >
                                        <IconTrash className="w-4 h-4 mr-2" /> Delete
                                    </button>
                                )}
                                <button 
                                    type="button"
                                    onClick={() => setIsModalOpen(false)}
                                    className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                                >
                                    Cancel
                                </button>
                                <button 
                                    type="submit"
                                    className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 shadow-lg shadow-primary-500/25 transition-colors"
                                >
                                    {selectedCampaign ? 'Save Changes' : 'Create Campaign'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default Campaigns;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Visit, VisitStatus, VisitType, Account } from '../types';
import { 
    IconMapPin, IconCalendar, IconClock, IconPlus, IconSearch, 
    IconFilter, IconCheckCircle, IconX, IconUser, IconBuilding,
    IconArrowUp, IconArrowDown, IconEdit, IconTrash, IconChevronRight,
    IconSparkles, IconGlobe
} from './Icons';
import { findPlace } from '../services/geminiService';

interface VisitsProps {
    visits: Visit[];
    accounts?: Account[];
    onAddVisit: (visit: Visit) => void;
    onUpdateVisit: (visit: Visit) => void;
    onDeleteVisit: (id: string) => void;
}

const VISIT_TYPES: VisitType[] = ['Sales', 'Site Inspection', 'Service', 'Delivery', 'Demo'];
const VISIT_STATUSES: VisitStatus[] = ['Scheduled', 'In Progress', 'Completed', 'Cancelled'];
const DATE_FILTERS = ['All Time', 'This Week', 'This Month', 'This Quarter', 'This Year'];

const Visits: React.FC<VisitsProps> = ({ visits, accounts = [], onAddVisit, onUpdateVisit, onDeleteVisit }) => {
    const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('All');
    const [dateFilter, setDateFilter] = useState<string>('All Time');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedVisit, setSelectedVisit] = useState<Visit | null>(null);
    const [formData, setFormData] = useState<Partial<Visit>>({
        date: new Date().toISOString().split('T')[0],
        startTime: '09:00',
        endTime: '10:00',
        status: 'Scheduled',
        type: 'Sales',
        assignedTo: 'Alex Chen',
        location: '',
        mapLink: ''
    });

    const [showAccountSuggestions, setShowAccountSuggestions] = useState(false);
    const [filteredAccounts, setFilteredAccounts] = useState<Account[]>([]);
    const accountWrapperRef = useRef<HTMLDivElement>(null);
    const [isLookingUpMap, setIsLookingUpMap] = useState(false);

    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (accountWrapperRef.current && !accountWrapperRef.current.contains(event.target as Node)) {
                setShowAccountSuggestions(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [accountWrapperRef]);

    const today = new Date().toISOString().split('T')[0];
    const todayVisits = visits.filter(v => v.date === today);
    const completedCount = todayVisits.filter(v => v.status === 'Completed').length;
    const pendingCount = todayVisits.filter(v => v.status === 'Scheduled' || v.status === 'In Progress').length;

    const filteredVisits = useMemo(() => {
        return visits.filter(visit => {
            const matchesSearch = 
                visit.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                visit.relatedTo.toLowerCase().includes(searchQuery.toLowerCase()) ||
                visit.location.toLowerCase().includes(searchQuery.toLowerCase());

            const matchesStatus = statusFilter === 'All' || visit.status === statusFilter;

            let matchesDate = true;
            if (dateFilter !== 'All Time') {
                const visitDate = new Date(visit.date);
                const now = new Date();

                // Reset time part for accurate date comparison
                now.setHours(0,0,0,0); 
                const visitDateMidnight = new Date(visitDate.getFullYear(), visitDate.getMonth(), visitDate.getDate());

                if (dateFilter === 'This Week') {
                    const startOfWeek = new Date(now);
                    startOfWeek.setDate(now.getDate() - now.getDay()); 
                    startOfWeek.setHours(0, 0, 0, 0);
                    matchesDate = visitDateMidnight >= startOfWeek;
                } else if (dateFilter === 'This Month') {
                    matchesDate = visitDate.getMonth() === now.getMonth() && visitDate.getFullYear() === now.getFullYear();
                } else if (dateFilter === 'This Quarter') {
                    const currentQuarter = Math.floor(now.getMonth() / 3);
                    const visitQuarter = Math.floor(visitDate.getMonth() / 3);
                    matchesDate = currentQuarter === visitQuarter && visitDate.getFullYear() === now.getFullYear();
                } else if (dateFilter === 'This Year') {
                    matchesDate = visitDate.getFullYear() === now.getFullYear();
                }
            }

            return matchesSearch && matchesStatus && matchesDate;
        });
    }, [visits, searchQuery, statusFilter, dateFilter]);

    const handleOpenModal = (visit?: Visit) => {
        if (visit) {
            setSelectedVisit(visit);
            setFormData(visit);
        } else {
            setSelectedVisit(null);
            setFormData({
                date: new Date().toISOString().split('T')[0],
                startTime: '09:00',
                endTime: '10:00',
                status: 'Scheduled',
                type: 'Sales',
                assignedTo: 'Alex Chen',
                title: '',
                relatedTo: '',
                location: '',
                mapLink: ''
            });
        }
        setFilteredAccounts([]);
        setIsModalOpen(true);
    };

    const handleRelatedToChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setFormData({ ...formData, relatedTo: value });

        if (value && accounts.length > 0) {
            const matches = accounts.filter(a => a.name.toLowerCase().includes(value.toLowerCase()));
            setFilteredAccounts(matches);
            setShowAccountSuggestions(matches.length > 0);
        } else {
            setShowAccountSuggestions(false);
        }
    };

    const selectAccount = (account: Account) => {
        setFormData(prev => ({
            ...prev,
            relatedTo: account.name,
            location: account.address || prev.location,
            mapLink: account.address ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(account.address)}` : prev.mapLink
        }));
        setShowAccountSuggestions(false);
    };

    const handleVerifyLocation = async () => {
        if (!formData.location) {
            alert("Please enter a location name or address first.");
            return;
        }
        setIsLookingUpMap(true);
        const result = await findPlace(formData.location);
        if (result) {
            setFormData(prev => ({ 
                ...prev, 
                location: result.address, 
                mapLink: result.mapLink 
            }));
        }
        setIsLookingUpMap(false);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.title || !formData.relatedTo || !formData.date) {
            alert('Please fill in all required fields.');
            return;
        }

        const visitData = {
            id: selectedVisit ? selectedVisit.id : `V-${Date.now()}`,
            ...formData
        } as Visit;

        if (selectedVisit) {
            onUpdateVisit(visitData);
        } else {
            onAddVisit(visitData);
        }
        setIsModalOpen(false);
    };

    const handleCheckIn = (visit: Visit, e: React.MouseEvent) => {
        e.stopPropagation();
        onUpdateVisit({ ...visit, status: 'In Progress' });
    };

    const handleComplete = (visit: Visit, e: React.MouseEvent) => {
        e.stopPropagation();
        onUpdateVisit({ ...visit, status: 'Completed', outcome: 'Visit completed successfully.' });
    };

    const getStatusColor = (status: VisitStatus) => {
        switch (status) {
            case 'Scheduled': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
            case 'In Progress': return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400';
            case 'Completed': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
            case 'Cancelled': return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
            default: return 'bg-slate-100 text-slate-600';
        }
    };

    return (
        <div className="space-y-6 h-full flex flex-col animate-fade-in">
            {/* Header and Stats Cards */}
            <div className="flex justify-between items-center flex-shrink-0 md:pr-24">
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Field Visits</h1>
                <button 
                    onClick={() => handleOpenModal()}
                    className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
                >
                    <IconPlus className="w-4 h-4 mr-2" /> Schedule Visit
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-shrink-0">
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Today's Visits</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{todayVisits.length}</h3>
                        </div>
                        <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg text-blue-600 dark:text-blue-400">
                            <IconMapPin className="w-5 h-5" />
                        </div>
                    </div>
                </div>
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Pending</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{pendingCount}</h3>
                        </div>
                        <div className="p-2 bg-amber-50 dark:bg-amber-900/20 rounded-lg text-amber-600 dark:text-amber-400">
                            <IconClock className="w-5 h-5" />
                        </div>
                    </div>
                </div>
                <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Completed</p>
                            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{completedCount}</h3>
                        </div>
                        <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg text-emerald-600 dark:text-emerald-400">
                            <IconCheckCircle className="w-5 h-5" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
                <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                    <div className="relative flex-1 max-w-md">
                        <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="Search visits..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="flex items-center gap-2">
                             <IconCalendar className="w-4 h-4 text-slate-400" />
                             <select 
                                value={dateFilter}
                                onChange={(e) => setDateFilter(e.target.value)}
                                className="px-3 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 dark:text-slate-200 cursor-pointer"
                            >
                                {DATE_FILTERS.map(d => <option key={d} value={d}>{d}</option>)}
                            </select>
                        </div>
                        <div className="flex items-center gap-2">
                            <IconFilter className="w-4 h-4 text-slate-400" />
                            <select 
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="px-3 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 dark:text-slate-200 cursor-pointer"
                            >
                                <option value="All">All Status</option>
                                {VISIT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="overflow-auto flex-1 custom-scrollbar p-4">
                    <div className="space-y-3">
                        {filteredVisits.map(visit => (
                            <div key={visit.id} onClick={() => handleOpenModal(visit)} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-4 rounded-xl shadow-sm hover:shadow-md transition-shadow cursor-pointer flex flex-col md:flex-row gap-4 items-start md:items-center">
                                <div className="flex-1">
                                    <div className="flex items-center gap-3 mb-1">
                                        <h4 className="font-bold text-slate-900 dark:text-white">{visit.title}</h4>
                                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${getStatusColor(visit.status)}`}>{visit.status}</span>
                                    </div>
                                    <p className="text-sm text-slate-600 dark:text-slate-300 flex items-center gap-2">
                                        <IconBuilding className="w-3.5 h-3.5 text-slate-400" /> {visit.relatedTo}
                                        <span className="text-slate-300 dark:text-slate-600">|</span>
                                        <IconMapPin className="w-3.5 h-3.5 text-slate-400" /> {visit.location || 'No location'}
                                    </p>
                                </div>
                                <div className="flex flex-col items-end gap-1 text-sm text-slate-500 dark:text-slate-400 min-w-[140px]">
                                    <div className="flex items-center gap-2">
                                        <IconCalendar className="w-4 h-4" /> {visit.date}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <IconClock className="w-4 h-4" /> {visit.startTime} - {visit.endTime}
                                    </div>
                                </div>
                                <div className="flex items-center gap-2" onClick={e => e.stopPropagation()}>
                                    {visit.status === 'Scheduled' && (
                                        <button onClick={(e) => handleCheckIn(visit, e)} className="px-3 py-1.5 bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 rounded-lg text-xs font-bold hover:bg-blue-200 dark:hover:bg-blue-900/50 transition-colors">
                                            Check In
                                        </button>
                                    )}
