                            </div>
                        ) : (
                            <span className="text-slate-400 italic">None</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <button 
                        onClick={(e) => { e.stopPropagation(); handleOpenModal(meeting); }}
                        className="p-2 text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 opacity-0 group-hover:opacity-100 transition-all"
                        >
                        <IconEdit className="w-4 h-4" />
                        </button>
                    </td>
                    </tr>
                ))}
                {sortedMeetings.length === 0 && (
                    <tr>
                    <td colSpan={5} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                        <div className="flex flex-col items-center justify-center">
                        <IconCalendar className="w-12 h-12 text-slate-300 dark:text-slate-700 mb-3" />
                        <p className="text-lg font-medium">No meetings found</p>
                        <p className="text-sm">Try adjusting your filters or create a new meeting.</p>
                        </div>
                    </td>
                    </tr>
                )}
                </tbody>
            </table>
            </div>
        </div>
      ) : viewMode === 'calendar' ? (
        renderCalendar()
      ) : (
        renderDayView()
      )}

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                 <IconCalendar className="w-5 h-5 mr-3 text-primary-500" />
                 {selectedMeeting ? 'Edit Meeting' : 'Schedule Meeting'}
              </h2>
              <button 
                onClick={handleCloseModal} 
                className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
              >
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 overflow-y-auto">
              <form onSubmit={handleSubmit} className="space-y-5">
                 <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Meeting Title <span className="text-red-500">*</span></label>
                    <input 
                       type="text" 
                       name="title" 
                       value={formData.title} 
                       onChange={handleInputChange} 
                       required
                       placeholder="e.g. Weekly Sync"
                       className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                    />
                 </div>

                 <div className="grid grid-cols-2 gap-5">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Date <span className="text-red-500">*</span></label>
                        <input 
                            type="date" 
                            name="date" 
                            value={formData.date} 
                            onChange={handleInputChange} 
                            required
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Type</label>
                        <select 
                            name="type" 
                            value={formData.type} 
                            onChange={handleInputChange}
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white appearance-none cursor-pointer"
                        >
                            <option value="Online">Online</option>
                            <option value="Offline">Offline</option>
                        </select>
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-5">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Start Time <span className="text-red-500">*</span></label>
                        <input 
                            type="time" 
                            name="startTime" 
                            value={formData.startTime} 
                            onChange={handleInputChange}
                            required
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">End Time <span className="text-red-500">*</span></label>
                        <input 
                            type="time" 
                            name="endTime" 
                            value={formData.endTime} 
                            onChange={handleInputChange} 
                            required
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                 </div>

                 {/* Related To Dropdown */}
                 <div ref={relatedToDropdownRef} className="relative">
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Related To</label>
                    <div className="relative">
                        <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                           type="text" 
                           value={relatedToSearch} 
                           onChange={(e) => {
                               setRelatedToSearch(e.target.value);
                               setIsRelatedToDropdownOpen(true);
                           }}
                           onFocus={() => setIsRelatedToDropdownOpen(true)}
                           placeholder="Search Contacts or Accounts..."
                           className="w-full pl-9 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                    {isRelatedToDropdownOpen && (
                        <div className="absolute z-20 w-full mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl max-h-48 overflow-y-auto">
                            {filteredRelatedOptions.length > 0 ? (
                                filteredRelatedOptions.map(opt => (
                                    <button
                                        key={`${opt.type}-${opt.id}`}
                                        type="button"
                                        onClick={() => handleSelectRelatedTo(opt)}
                                        className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors border-b border-slate-100 dark:border-slate-700 last:border-0"
                                    >
                                        <span className="font-medium">{opt.name}</span>
                                        <span className="ml-2 text-xs text-slate-500 dark:text-slate-400">({opt.type})</span>
                                    </button>
                                ))
                            ) : (
                                <div className="px-4 py-3 text-sm text-slate-500 dark:text-slate-400 text-center">No results found.</div>
                            )}
                        </div>
                    )}
                 </div>

                 <div className="pt-4 flex gap-3 justify-end border-t border-slate-100 dark:border-slate-800">
                    {selectedMeeting && (
                        <button 
                            type="button"
                            onClick={handleDelete}
                            className="mr-auto px-4 py-2.5 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 rounded-xl hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors flex items-center"
                        >
                            <IconTrash className="w-4 h-4 mr-2" /> Delete
                        </button>
                    )}
                    <button 
                        type="button"
                        onClick={handleCloseModal}
                        className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                    >
                        Cancel
                    </button>
                    <button 
                        type="submit"
                        className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 shadow-lg shadow-primary-500/25 transition-colors"
                    >
                        {selectedMeeting ? 'Save Changes' : 'Schedule Meeting'}
                    </button>
                 </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Meetings;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Call, Lead, Contact, Account } from '../types';
import { summarizeCallNotes } from '../services/geminiService';
import { IconPhone, IconFilter, IconArrowUp, IconArrowDown, IconX, IconSparkles, IconSearch } from './Icons';

interface CallsProps {
  calls: Call[];
  leads: Lead[];
  contacts: Contact[];
  accounts: Account[];
  onAddCall: (callData: Omit<Call, 'id'>) => void;
}

const initialFormState: Omit<Call, 'id' | 'date'> = {
  subject: '',
  relatedTo: '',
  relatedToId: '',
  type: 'Outbound',
  outcome: 'Connected',
  notes: '',
  summary: ''
};

const Calls: React.FC<CallsProps> = ({ calls, leads, contacts, accounts, onAddCall }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newCallData, setNewCallData] = useState(initialFormState);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [sortConfig, setSortConfig] = useState<{ key: keyof Call; direction: 'asc' | 'desc' } | null>(null);

  // Searchable Dropdown State
  const [relatedToSearch, setRelatedToSearch] = useState('');
  const [isRelatedToDropdownOpen, setIsRelatedToDropdownOpen] = useState(false);
  const relatedToDropdownRef = useRef<HTMLDivElement>(null);

  // Click outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (relatedToDropdownRef.current && !relatedToDropdownRef.current.contains(event.target as Node)) {
        setIsRelatedToDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const sortedCalls = useMemo(() => {
    let sortableItems = [...calls];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [calls, sortConfig]);

  const requestSort = (key: keyof Call) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Call) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-4 h-4 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-4 h-4 text-primary-500" />;
    return <IconArrowDown className="w-4 h-4 text-primary-500" />;
  };

  const handleOpenModal = () => setIsModalOpen(true);
  const handleCloseModal = () => {
    setIsModalOpen(false);
    setNewCallData(initialFormState);
    setRelatedToSearch('');
    setIsSummarizing(false);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewCallData(prev => ({ ...prev, [name]: value }));
  };

  const handleGenerateSummary = async () => {
    if (!newCallData.notes) return;
    setIsSummarizing(true);
    const summary = await summarizeCallNotes(newCallData.notes);
    setNewCallData(prev => ({ ...prev, summary }));
    setIsSummarizing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCallData.relatedToId) {
        alert("Please select a valid Lead, Contact, or Account for 'Related To'");
        return;
    }
    onAddCall({ ...newCallData, date: new Date().toISOString() });
    handleCloseModal();
  };

  const relatedToOptions = useMemo(() => {
    const leadOptions = leads.map(l => ({ id: l.id, name: l.name, type: 'Lead', label: `${l.name} (Lead)` }));
    const contactOptions = contacts.map(c => ({ id: c.id, name: c.name, type: 'Contact', label: `${c.name} (Contact)` }));
    const accountOptions = accounts.map(a => ({ id: a.id, name: a.name, type: 'Account', label: `${a.name} (Account)` }));
    return [...leadOptions, ...contactOptions, ...accountOptions];
  }, [leads, contacts, accounts]);

  const filteredRelatedOptions = useMemo(() => {
    if (!relatedToSearch) return relatedToOptions;
    return relatedToOptions.filter(opt => opt.label.toLowerCase().includes(relatedToSearch.toLowerCase()));
  }, [relatedToOptions, relatedToSearch]);

  const handleSelectRelatedTo = (option: { id: string, name: string, type: string, label: string }) => {
      setNewCallData(prev => ({ ...prev, relatedToId: option.id, relatedTo: option.label }));
      setRelatedToSearch(option.label);
      setIsRelatedToDropdownOpen(false);
  };

  return (
    <>
      <div className="space-y-6">
        <div className="flex justify-between items-center md:pr-24">
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Call Logs</h1>
          <button onClick={handleOpenModal} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all">
            + New Call
          </button>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
          <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <IconFilter className="w-4 h-4 text-slate-400" />
              <span className="text-sm font-medium text-slate-700 dark:text-slate-300">All Calls</span>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
              <tr>
                <th className="px-6 py-4"><button onClick={() => requestSort('subject')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Subject {getSortIcon('subject')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('relatedTo')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Related To {getSortIcon('relatedTo')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('type')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Call Type {getSortIcon('type')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('outcome')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Outcome {getSortIcon('outcome')}</button></th>
                <th className="px-6 py-4"><button onClick={() => requestSort('date')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Date {getSortIcon('date')}</button></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {sortedCalls.map((call) => (
                <tr key={call.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                  <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center"><IconPhone className="w-4 h-4 mr-2 text-slate-400" />{call.subject}</td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{call.relatedTo}</td>
                  <td className="px-6 py-4"><span className={`px-2 py-1 text-sm font-medium rounded-full ${call.type === 'Inbound' ? 'bg-blue-100 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400' : 'bg-primary-100 text-primary-700 dark:bg-primary-500/10 dark:text-primary-400'}`}>{call.type}</span></td>
                  <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{call.outcome}</td>
                  <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">{new Date(call.date).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Log a Call</h2>
              <button onClick={handleCloseModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
            </div>

            <form onSubmit={handleSubmit} className="overflow-y-auto p-6 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Subject</label>
                  <input type="text" name="subject" required value={newCallData.subject} onChange={handleInputChange} placeholder="e.g., Follow-up on Proposal" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" />
                </div>

                {/* Searchable Select for Related To */}
                <div ref={relatedToDropdownRef} className="relative">
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Related To</label>
                  <div className="relative">
                    <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                        type="text" 
                        placeholder="Search leads, contacts, or accounts..." 
                        value={relatedToSearch}
                        onChange={(e) => {
                            setRelatedToSearch(e.target.value);
                            setIsRelatedToDropdownOpen(true);
                        }}
                        onFocus={() => setIsRelatedToDropdownOpen(true)}
                        className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white placeholder-slate-400"
                    />
                  </div>
                  {isRelatedToDropdownOpen && (
                    <div className="absolute z-10 w-full mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl max-h-60 overflow-y-auto">
                        {filteredRelatedOptions.length > 0 ? (
                            filteredRelatedOptions.map(opt => (
                                <button
                                    key={`${opt.type}-${opt.id}`}
                                    type="button"
                                    onClick={() => handleSelectRelatedTo(opt)}
                                    className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
                                >
                                    <span className="font-medium">{opt.name}</span>
                                    <span className="ml-2 text-xs text-slate-500 dark:text-slate-400">({opt.type})</span>
                                </button>
                            ))
                        ) : (
                            <div className="px-4 py-2 text-sm text-slate-500 dark:text-slate-400">No results found.</div>
                        )}
                    </div>
                  )}
                  {/* Hidden input for HTML5 validation if needed, or check on submit */}
                  <input type="hidden" name="relatedToId" value={newCallData.relatedToId} required />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Call Type</label>
                  <select name="type" value={newCallData.type} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white">
                    <option>Outbound</option>
                    <option>Inbound</option>
                  </select>
                </div>
                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Outcome</label>
                  <select name="outcome" value={newCallData.outcome} onChange={handleInputChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white">
                    <option>Connected</option>
                    <option>Left Voicemail</option>
                    <option>No Answer</option>
                    <option>Scheduled Follow-up</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Notes</label>
                <textarea name="notes" value={newCallData.notes} onChange={handleInputChange} rows={5} placeholder="Enter details about the conversation..." className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"></textarea>
              </div>
              <div>
                <div className="flex justify-between items-center mb-1">
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300">AI Summary</label>
                  <button type="button" onClick={handleGenerateSummary} disabled={isSummarizing || !newCallData.notes} className="flex items-center px-3 py-1 text-xs font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-sm transition-colors disabled:opacity-50">
                    <IconSparkles className="w-3 h-3 mr-1.5" />
                    {isSummarizing ? 'Generating...' : 'Generate Summary'}
                  </button>
                </div>
                <textarea name="summary" value={newCallData.summary} readOnly={isSummarizing} onChange={handleInputChange} rows={3} placeholder={isSummarizing ? "AI is thinking..." : "AI-generated summary will appear here."} className="w-full px-3 py-2 bg-slate-100 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none text-slate-600 dark:text-slate-300"></textarea>
              </div>
              <div className="pt-4 flex space-x-3">
                <button type="button" onClick={handleCloseModal} className="flex-1 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors">Save Call</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

export default Calls;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Ticket, TicketStatus, TicketPriority, TicketType, Account } from '../types';
import { 
  IconLifeBuoy, IconPlus, IconSearch, IconFilter, IconCheckCircle, 
  IconAlertCircle, IconClock, IconMessageCircle, IconX, IconSparkles, 
  IconUser, IconCopy, IconCheck, IconBuilding, IconChevronRight, IconZap
} from './Icons';
import { analyzeTicketSentiment, generateSupportResponse, classifySupportTicket } from '../services/geminiService';

interface SupportProps {
  tickets: Ticket[];
  accounts: Account[];
  onAddTicket: (ticket: Ticket) => void;
  onUpdateTicket: (ticket: Ticket) => void;
  onDeleteTicket: (id: string) => void;
}

const TICKET_STATUSES: TicketStatus[] = ['Open', 'In Progress', 'Waiting on Customer', 'Resolved', 'Closed'];
const TICKET_PRIORITIES: TicketPriority[] = ['Low', 'Medium', 'High', 'Urgent'];
const TICKET_TYPES: TicketType[] = ['Problem', 'Question', 'Feature Request', 'Billing'];

const Support: React.FC<SupportProps> = ({ tickets, accounts, onAddTicket, onUpdateTicket, onDeleteTicket }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTicket, setSelectedTicket] = useState<Ticket | null>(null);

  // AI States
  const [isAnalyzingSentiment, setIsAnalyzingSentiment] = useState(false);
  const [isGeneratingResponse, setIsGeneratingResponse] = useState(false);
  const [isClassifying, setIsClassifying] = useState(false);
  const [generatedResponse, setGeneratedResponse] = useState('');
  const [classificationReason, setClassificationReason] = useState<string | null>(null);

  // Account Selection State
  const [showAccountSuggestions, setShowAccountSuggestions] = useState(false);
  const [filteredAccounts, setFilteredAccounts] = useState<Account[]>([]);
  const accountWrapperRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState<Partial<Ticket>>({
    status: 'Open',
    priority: 'Medium',
    type: 'Question',
    assignedTo: 'Alex Chen',
    createdAt: new Date().toISOString().split('T')[0]
  });

  // Click outside to close suggestions
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (accountWrapperRef.current && !accountWrapperRef.current.contains(event.target as Node)) {
        setShowAccountSuggestions(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [accountWrapperRef]);

  // Metrics
  const openCount = tickets.filter(t => t.status === 'Open' || t.status === 'In Progress').length;
  const urgentCount = tickets.filter(t => t.priority === 'Urgent' && t.status !== 'Closed').length;
  const avgResponseTime = '4.2h'; // Mocked for now

  const filteredTickets = useMemo(() => {
    return tickets.filter(ticket => {
      const matchesSearch = ticket.subject.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            ticket.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
                            ticket.id.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesStatus = statusFilter === 'All' || ticket.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [tickets, searchQuery, statusFilter]);

  const handleOpenModal = (ticket?: Ticket) => {
    if (ticket) {
      setSelectedTicket(ticket);
      setFormData(ticket);
      setGeneratedResponse('');
    } else {
      setSelectedTicket(null);
      setFormData({
        status: 'Open',
        priority: 'Medium',
        type: 'Question',
        assignedTo: 'Alex Chen',
        createdAt: new Date().toISOString().split('T')[0],
        subject: '',
        description: '',
        customerName: '',
        accountId: ''
      });
      setGeneratedResponse('');
    }
    setFilteredAccounts([]);
    setShowAccountSuggestions(false);
    setClassificationReason(null);
    setIsModalOpen(true);
  };

  const handleCustomerInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value;
      setFormData(prev => ({ ...prev, customerName: value, accountId: undefined })); // Clear accountId if typing freely unless matched later

      if (value && accounts.length > 0) {
          const matches = accounts.filter(a => a.name.toLowerCase().includes(value.toLowerCase()));
          setFilteredAccounts(matches);
          setShowAccountSuggestions(matches.length > 0);
      } else {
          setShowAccountSuggestions(false);
      }
  };

  const selectAccount = (account: Account) => {
      setFormData(prev => ({
          ...prev,
          customerName: account.name,
          accountId: account.id
      }));
      setShowAccountSuggestions(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.subject || !formData.customerName) {
        alert("Subject and Customer Name are required");
        return;
    }

    const ticketData = {
        id: selectedTicket ? selectedTicket.id : `T-${Date.now()}`,
        ...formData
    } as Ticket;

    if (selectedTicket) {
        onUpdateTicket(ticketData);
    } else {
        onAddTicket(ticketData);
    }
    setIsModalOpen(false);
  };

  const handleSentimentAnalysis = async () => {
      if (!formData.description) return;
      setIsAnalyzingSentiment(true);
      const result = await analyzeTicketSentiment(formData.description);
      setFormData(prev => ({ ...prev, sentimentScore: result.score, sentimentMood: result.mood }));
      setIsAnalyzingSentiment(false);
  };

  const handleGenerateResponse = async () => {
      if (!formData.description) return;
      setIsGeneratingResponse(true);
      // We pass formData cast as Ticket (minimal required fields)
      const response = await generateSupportResponse(formData as Ticket);
      setGeneratedResponse(response);
      setIsGeneratingResponse(false);
  };

  const handleAutoClassify = async () => {
      if (!formData.subject || !formData.description) {
          alert("Please enter a subject and description first.");
          return;
      }
      setIsClassifying(true);
      setClassificationReason(null);
      const result = await classifySupportTicket(formData.subject, formData.description);

      setFormData(prev => ({
          ...prev,
          type: result.type,
          priority: result.priority,
          // Simple routing simulation logic
          assignedTo: result.type === 'Billing' ? 'Sarah Connor' : result.type === 'Feature Request' ? 'Miles Dyson' : 'Alex Chen'
      }));
      setClassificationReason(result.reasoning);
      setIsClassifying(false);
  };

  const getPriorityColor = (priority: string) => {
      switch(priority) {
          case 'Urgent': return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-red-200 dark:border-red-900/50';
          case 'High': return 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400 border-orange-200 dark:border-orange-900/50';
          case 'Medium': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 border-blue-200 dark:border-blue-900/50';
          case 'Low': return 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-400 border-slate-200 dark:border-slate-700';
          default: return 'bg-slate-100 text-slate-700';
      }
  };

  const getStatusColor = (status: string) => {
      switch(status) {
          case 'Open': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
          case 'Closed': return 'bg-slate-200 text-slate-600 dark:bg-slate-800 dark:text-slate-500';
          case 'In Progress': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
          default: return 'bg-slate-100 text-slate-600';
      }
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
        {/* Header */}
        <div className="flex justify-between items-center flex-shrink-0 md:pr-24">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Support Desk</h1>
            <button 
                onClick={() => handleOpenModal()}
                className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
            >
                <IconPlus className="w-4 h-4 mr-2" /> New Ticket
            </button>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-shrink-0">
            <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                <div className="flex justify-between items-start">
                    <div>
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Open Tickets</p>
                        <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{openCount}</h3>
                    </div>
                    <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg text-blue-600 dark:text-blue-400">
                        <IconLifeBuoy className="w-5 h-5" />
                    </div>
                </div>
            </div>
            <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                <div className="flex justify-between items-start">
                    <div>
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Urgent Issues</p>
                        <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{urgentCount}</h3>
                    </div>
                    <div className="p-2 bg-red-50 dark:bg-red-900/20 rounded-lg text-red-600 dark:text-red-400">
                        <IconAlertCircle className="w-5 h-5" />
                    </div>
                </div>
            </div>
            <div className="p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                <div className="flex justify-between items-start">
                    <div>
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Avg Response Time</p>
                        <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{avgResponseTime}</h3>
                    </div>
                    <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg text-emerald-600 dark:text-emerald-400">
                        <IconClock className="w-5 h-5" />
                    </div>
                </div>
            </div>
        </div>

        {/* Ticket List */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                <div className="relative flex-1 max-w-md">
                    <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                        type="text" 
                        placeholder="Search tickets by ID, subject, customer..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                </div>
                <div className="flex items-center space-x-2">
                    <IconFilter className="w-4 h-4 text-slate-400" />
                    <select 
                        value={statusFilter}
                        onChange={(e) => setStatusFilter(e.target.value)}
                        className="px-3 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 dark:text-slate-200 cursor-pointer"
                    >
                        <option value="All">All Status</option>
                        {TICKET_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>

            <div className="overflow-auto flex-1 custom-scrollbar">
                <table className="w-full text-left text-sm">
                    <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
                        <tr>
                            <th className="px-6 py-4 font-medium">Ticket ID</th>
                            <th className="px-6 py-4 font-medium">Subject</th>
                            <th className="px-6 py-4 font-medium">Customer</th>
                            <th className="px-6 py-4 font-medium">Priority</th>
                            <th className="px-6 py-4 font-medium">Status</th>
                            <th className="px-6 py-4 font-medium">Date</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                        {filteredTickets.map(ticket => (
                            <tr 
                                key={ticket.id} 
                                onClick={() => handleOpenModal(ticket)}
                                className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group"
                            >
                                <td className="px-6 py-4 text-slate-500 dark:text-slate-400 font-mono text-xs">{ticket.id}</td>
                                <td className="px-6 py-4 font-medium text-slate-900 dark:text-white">{ticket.subject}</td>
                                <td className="px-6 py-4 text-slate-600 dark:text-slate-300">
                                    {ticket.customerName}
                                    {ticket.accountId && <span className="ml-2 inline-block px-1.5 py-0.5 rounded text-[10px] bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500">Account</span>}
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`px-2 py-1 text-xs font-bold rounded-full border ${getPriorityColor(ticket.priority)}`}>
                                        {ticket.priority}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`px-2 py-1 text-xs font-bold rounded-full ${getStatusColor(ticket.status)}`}>
                                        {ticket.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-slate-500 dark:text-slate-400 text-xs">{ticket.createdAt}</td>
                            </tr>
                        ))}
                        {filteredTickets.length === 0 && (
                            <tr>
                                <td colSpan={6} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                                    <div className="flex flex-col items-center justify-center">
                                        <IconLifeBuoy className="w-12 h-12 text-slate-300 dark:text-slate-600 mb-3" />
                                        <p className="text-lg font-medium">No tickets found</p>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Modal */}
        {isModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="w-full max-w-4xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in flex flex-col max-h-[90vh]">
                    <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
