      { id: 'rose', name: 'Ruby Red', hex: '#f43f5e' },
      { id: 'cyan', name: 'Ocean Cyan', hex: '#06b6d4' },
      { id: 'blue', name: 'Azure Blue', hex: '#3b82f6' }, 
  ];

  // Fonts Config
  const FONTS = [
      { id: 'Plus Jakarta', name: 'Plus Jakarta', description: 'Modern Geometric', family: "'Plus Jakarta Sans', sans-serif" },
      { id: 'Inter UI', name: 'Inter UI', description: 'Neo-Grotesque', family: "'Inter', sans-serif" },
      { id: 'Montserrat', name: 'Montserrat', description: 'Urban Classic', family: "'Montserrat', sans-serif" },
      { id: 'Outfit', name: 'Outfit', description: 'Modern Geometric', family: "'Outfit', sans-serif" },
      { id: 'Lexend', name: 'Lexend', description: 'Readability Focused', family: "'Lexend', sans-serif" },
      { id: 'Playfair Display', name: 'Playfair Display', description: 'Elegance Serif', family: "'Playfair Display', serif" },
  ];

  useEffect(() => {
    if (!editingRole && roles.length > 0) {
        setEditingRole(roles[0]);
    }
  }, [roles]);

  useEffect(() => {
      if (roles.length > 0 && isInviteModalOpen) {
          if (!inviteRole) {
              setInviteRole(roles[0].id);
          }
      }
  }, [roles, isInviteModalOpen]);

  const handleSave = () => {
    setPipelineGoal(Number(goalInput));
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
  };

  const toggleWorkingDay = (day: string) => {
      if (workingDays.includes(day)) {
          setWorkingDays(workingDays.filter(d => d !== day));
      } else {
          setWorkingDays([...workingDays, day]);
      }
  };

  const handleUpdateUserRole = (userId: string, roleId: string) => {
      setUsers(users.map(u => u.id === userId ? { ...u, roleId } : u));
      if (currentUser.id === userId) {
          setCurrentUser({ ...currentUser, roleId });
      }
  };

  const handleTogglePermission = (roleId: string, permission: Permission) => {
      setRoles(roles.map(r => {
          if (r.id !== roleId) return r;
          const hasPermission = r.permissions.includes(permission);
          return {
              ...r,
              permissions: hasPermission 
                  ? r.permissions.filter(p => p !== permission)
                  : [...r.permissions, permission]
          };
      }));
  };

  const handleCreateRole = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newRoleName.trim()) {
          alert('Role name is required');
          return;
      }
      const roleId = newRoleName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
      const newRole: RoleDefinition = {
          id: roleId,
          name: newRoleName.trim(),
          description: newRoleDescription || 'Custom Role',
          isSystem: false,
          permissions: ['view_dashboard'] 
      };
      setRoles([...roles, newRole]);
      setIsCreateRoleModalOpen(false);
      setNewRoleName('');
      setNewRoleDescription('');
      setEditingRole(newRole); 
  };

  const handleInviteMember = (e: React.FormEvent) => {
      e.preventDefault();
      if (!inviteEmail || !inviteName) return;
      const selectedRoleId = inviteRole || (roles.length > 0 ? roles[0].id : 'sales_rep');
      const newUser: User = {
          id: `u-${Date.now()}`,
          name: inviteName,
          email: inviteEmail,
          roleId: selectedRoleId,
          status: 'Active',
          lastLogin: 'Never',
          avatar: `https://i.pravatar.cc/150?u=${Date.now()}`
      };
      setUsers([newUser, ...users]);
      setIsInviteModalOpen(false);
      setInviteName('');
      setInviteEmail('');
      alert(`User ${inviteName} added successfully!`);
  };

  const handleDeleteRole = (roleId: string) => {
      if (window.confirm('Delete role?')) {
          setRoles(roles.filter(r => r.id !== roleId));
          if (editingRole?.id === roleId) setEditingRole(roles.find(r => r.id !== roleId) || null);
      }
  };

  const generateSecurePassword = () => {
      const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";
      let retVal = "";
      for (let i = 0, n = charset.length; i < 12; ++i) {
          retVal += charset.charAt(Math.floor(Math.random() * n));
      }
      return retVal;
  };

  const handleGeneratePassword = (user: User) => {
      const newPassword = generateSecurePassword();
      setGeneratedPassword(newPassword);
      setSelectedUserForPassword(user);
      setUsers(users.map(u => u.id === user.id ? { ...u, tempPassword: newPassword } : u));
      setPasswordModalOpen(true);
  };

  const handleOpenKeyModal = () => {
      setNewKeyName('');
      setNewlyGeneratedKey(null);
      setIsKeyModalOpen(true);
  };

  const handleGenerateKey = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newKeyName) return;

      const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
      let randomStr = '';
      const randomValues = new Uint32Array(24);
      crypto.getRandomValues(randomValues);
      for(let i=0; i<24; i++) {
          randomStr += chars[randomValues[i] % chars.length];
      }

      const fullKey = `nova_live_${randomStr}`;
      setNewlyGeneratedKey(fullKey);

      const newKey: ApiKey = {
          id: `k-${Date.now()}`,
          name: newKeyName,
          prefix: `nova_live_${randomStr.substring(0, 4)}...`,
          created: new Date().toISOString().split('T')[0],
          status: 'Active'
      };
      setApiKeys(prev => [...prev, newKey]);
  };

  const handleRevokeKey = (id: string) => {
      if (window.confirm("Are you sure you want to revoke this key? This action cannot be undone.")) {
          setApiKeys(prev => prev.filter(k => k.id !== id));
      }
  };

  const PERMISSION_GROUPS = {
      'System Administration': ['manage_users', 'manage_settings'],
      'Sales Operations': ['view_leads', 'edit_leads', 'manage_pipeline', 'view_revenue'],
      'Data Governance': ['delete_records', 'export_data'],
      'Intelligence': ['use_ai_features', 'view_dashboard']
  };

  const PERMISSION_DETAILS: Record<Permission, { label: string, desc: string }> = {
      'view_dashboard': { label: 'View Dashboard', desc: 'Access to main analytics overview' },
      'manage_users': { label: 'Manage Users', desc: 'Invite team members and assign roles' },
      'manage_settings': { label: 'System Settings', desc: 'Configure global app preferences' },
      'view_leads': { label: 'View Leads', desc: 'Read access to lead database' },
      'edit_leads': { label: 'Edit Leads', desc: 'Create and modify lead records' },
      'delete_records': { label: 'Delete Records', desc: 'Permanent removal of data' },
      'export_data': { label: 'Export Data', desc: 'Download CSV/PDF reports' },
      'view_revenue': { label: 'View Revenue', desc: 'Access financial metrics and deal values' },
      'manage_pipeline': { label: 'Manage Pipeline', desc: 'Move deals through stages' },
      'use_ai_features': { label: 'AI Features', desc: 'Use generative AI tools' }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'company':
        return (
            <div className="max-w-4xl space-y-10 animate-fade-in pb-10">
                <div className="space-y-1">
                    <h3 className="text-xl font-bold text-slate-900 dark:text-white uppercase tracking-wider">Company Profile</h3>
                </div>
                <div className="flex items-center gap-8 py-4">
                    <div className="relative group">
                        <div className="w-24 h-24 rounded-3xl bg-slate-100 dark:bg-slate-800 border-2 border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center cursor-pointer hover:border-primary-500 hover:bg-primary-50 dark:hover:bg-primary-900/10 transition-all">
                            <IconBuilding className="w-8 h-8 text-slate-400 group-hover:text-primary-500" />
                        </div>
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wide">Organization Identity</h4>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 mb-3">Upload your logo to rebrand the dashboard.</p>
                        <button className="text-xs font-bold text-primary-600 dark:text-primary-400 uppercase tracking-wider hover:underline">
                            Upload Logo
                        </button>
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-3">
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Organization Name</label>
                        <input 
                            type="text" 
                            value={companyName}
                            onChange={(e) => setCompanyName(e.target.value)}
                            className="w-full px-5 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl font-medium text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500/50 shadow-sm"
                        />
                    </div>
                    <div className="space-y-3">
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Support Email</label>
                        <input 
                            type="text" 
                            value={companyEmail}
                            onChange={(e) => setCompanyEmail(e.target.value)}
                            className="w-full px-5 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl font-medium text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500/50 shadow-sm"
                        />
                    </div>
                </div>
                <div className="space-y-3">
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Website</label>
                    <input 
                        type="text" 
                        value={companyWebsite}
                        onChange={(e) => setCompanyWebsite(e.target.value)}
                        className="w-full px-5 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl font-medium text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500/50 shadow-sm"
                    />
                </div>
            </div>
        );

      case 'theme':
        return (
            <div className="max-w-5xl space-y-12 animate-fade-in pb-10">
                <div>
                    <h3 className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-6">Accent Configuration</h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                        {COLORS.map(color => (
                            <button
                                key={color.id}
                                onClick={() => setPrimaryColor(color.id)}
                                className={`group relative flex flex-col items-center p-6 rounded-[2rem] transition-all duration-300 ${
                                    primaryColor === color.id 
                                    ? 'bg-white dark:bg-slate-800 ring-2 ring-primary-500 shadow-xl scale-[1.02] z-10' 
                                    : 'bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 hover:shadow-lg hover:-translate-y-1'
                                }`}
                            >
                                <div 
                                    className={`w-20 h-20 rounded-3xl shadow-md mb-4 transition-transform duration-300 ${primaryColor === color.id ? 'scale-110' : 'group-hover:scale-110'}`}
                                    style={{ backgroundColor: color.hex }}
                                ></div>
                                <span className={`text-[10px] font-bold uppercase tracking-widest ${primaryColor === color.id ? 'text-primary-600 dark:text-primary-400' : 'text-slate-500 dark:text-slate-400'}`}>
                                    {color.name}
                                </span>
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-6">Typography Core</h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {FONTS.map(font => (
                            <button
                                key={font.id}
                                onClick={() => setFontFamily(font.id)}
                                className={`group relative flex flex-col items-start p-8 rounded-[2rem] transition-all duration-300 text-left overflow-hidden min-h-[180px] ${
                                    fontFamily === font.id
                                    ? 'bg-white dark:bg-slate-800 ring-2 ring-primary-500 shadow-xl scale-[1.02] z-10' 
                                    : 'bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 hover:shadow-lg hover:-translate-y-1'
                                }`}
                            >
                                <div className={`relative z-10 w-full flex flex-col h-full justify-center`}>
                                    <h4 className={`text-3xl font-bold mb-3 ${fontFamily === font.id ? 'text-slate-900 dark:text-white' : 'text-slate-800 dark:text-slate-200'}`} style={{ fontFamily: font.family }}>
                                        {font.name}
                                    </h4>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{font.description}</p>
                                </div>
                                {fontFamily === font.id && (
                                    <div className="absolute -bottom-10 -right-10 w-32 h-32 bg-primary-500/10 rounded-full blur-2xl"></div>
                                )}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 flex items-center justify-between">
                    <div>
                        <h4 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wide">Interface Mode</h4>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Switch between light and dark aesthetics.</p>
                    </div>
                    <button 
                        onClick={toggleTheme}
                        className={`w-16 h-8 rounded-full p-1 transition-colors duration-300 ${isDark ? 'bg-slate-700' : 'bg-slate-300'}`}
                    >
                        <div className={`w-6 h-6 bg-white rounded-full shadow-md transform transition-transform duration-300 flex items-center justify-center ${isDark ? 'translate-x-8' : 'translate-x-0'}`}>
                            {isDark ? <IconMoon className="w-3 h-3 text-slate-800" /> : <IconSun className="w-3 h-3 text-yellow-500" />}
                        </div>
                    </button>
                </div>
            </div>
        );

      case 'regional':
        return (
            <div className="max-w-5xl space-y-10 animate-fade-in pb-10">
                 <div className="flex items-center gap-3 border-b border-slate-200 dark:border-slate-800 pb-4 mb-2">
                    <div className="p-2 bg-primary-50 dark:bg-primary-900/20 rounded-lg text-primary-600 dark:text-primary-400">
                        <IconGlobe className="w-6 h-6" />
                    </div>
                    <h3 className="text-lg font-bold text-primary-600 dark:text-primary-400 uppercase tracking-widest">Calendar & Formatting</h3>
                 </div>
                 <div className="p-8 text-center text-slate-500">Regional settings content placeholder.</div>
            </div>
        );

      case 'security':
        return (
            <div className="max-w-5xl space-y-10 animate-fade-in pb-10">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    <div className="bg-rose-50 dark:bg-rose-900/10 rounded-[2rem] p-8 border border-rose-100 dark:border-rose-900/20">
                        <h4 className="text-xs font-bold text-rose-500 uppercase tracking-widest mb-8">Access Control Hardening</h4>
                        <div className="bg-white dark:bg-slate-900 rounded-2xl p-4 flex items-center justify-between shadow-sm mb-6">
                            <div>
                                <h5 className="font-bold text-slate-900 dark:text-white text-sm">MFA Protocol</h5>
                                <p className="text-xs text-rose-400 font-medium mt-0.5">Two-Factor Authentication</p>
                            </div>
                            <button 
                                onClick={() => setMfaEnabled(!mfaEnabled)}
                                className={`w-14 h-8 rounded-full p-1 transition-colors duration-300 ${mfaEnabled ? 'bg-rose-500' : 'bg-slate-200 dark:bg-slate-700'}`}
                            >
                                <div className={`w-6 h-6 bg-white rounded-full shadow-md transform transition-transform duration-300 ${mfaEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        );

      case 'team':
        return (
            <div className="space-y-10 animate-fade-in pb-10">
