interface ApiKey {
    id: string;
    name: string;
    prefix: string;
    created: string;
    status: 'Active' | 'Revoked';
}

const Settings: React.FC<SettingsProps> = ({ 
  isDark, 
  toggleTheme, 
  primaryColor, 
  setPrimaryColor,
  pipelineGoal,
  setPipelineGoal,
  fontFamily,
  setFontFamily,
  density,
  setDensity,
  weekStart,
  setWeekStart,
  dateFormat,
  setDateFormat,
  timeZone,
  setTimeZone,
  timeFormat,
  setTimeFormat,
  workingDays,
  setWorkingDays,
  fiscalYearStart,
  setFiscalYearStart,
  defaultPaymentTerm,
  setDefaultPaymentTerm,
  defaultTaxRate,
  setDefaultTaxRate,
  taxEnabled,
  setTaxEnabled,
  defaultCurrency,
  setDefaultCurrency,
  multiCurrency,
  setMultiCurrency,
  roles,
  setRoles,
  users,
  setUsers,
  currentUser,
  setCurrentUser
}) => {
  const [activeTab, setActiveTab] = useState('company');
  const [goalInput, setGoalInput] = useState(pipelineGoal.toString());
  const [isSaved, setIsSaved] = useState(false);

  // Local State
