        <div className={`w-11 h-6 rounded-full relative transition-colors duration-200 ease-in-out flex-shrink-0 flex items-center px-0.5 ${checked ? 'bg-primary-500' : 'bg-slate-300 dark:bg-slate-600'}`}>
