interface ApiKey {
    id: string;
    name: string;
    prefix: string;
    created: string;
    status: 'Active' | 'Revoked';
}

const Settings: React.FC<SettingsProps> = ({ 
  isDark, 
  toggleTheme, 
  primaryColor, 
  setPrimaryColor,
  pipelineGoal,
  setPipelineGoal,
  fontFamily,
  setFontFamily,
  density,
  setDensity,
  weekStart,
  setWeekStart,
  dateFormat,
  setDateFormat,
  timeZone,
  setTimeZone,
  timeFormat,
  setTimeFormat,
  workingDays,
  setWorkingDays,
  fiscalYearStart,
  setFiscalYearStart,
  defaultPaymentTerm,
  setDefaultPaymentTerm,
  defaultTaxRate,
  setDefaultTaxRate,
  taxEnabled,
  setTaxEnabled,
  defaultCurrency,
  setDefaultCurrency,
  multiCurrency,
  setMultiCurrency,
  roles,
  setRoles,
  users,
  setUsers,
  currentUser,
  setCurrentUser
}) => {
  const [activeTab, setActiveTab] = useState('company');
  const [teamView, setTeamView] = useState<'users' | 'roles'>('users');
  const [goalInput, setGoalInput] = useState(pipelineGoal.toString());
  const [isSaved, setIsSaved] = useState(false);

  // Local State
  const [companyName, setCompanyName] = useState('TalentSense AI');
  const [companyEmail, setCompanyEmail] = useState('ops@talentsense.ai');
  const [companyWebsite, setCompanyWebsite] = useState('https://talentsense.ai');

  const [editingRole, setEditingRole] = useState<RoleDefinition | null>(null);
  const [isCreateRoleModalOpen, setIsCreateRoleModalOpen] = useState(false);
  const [newRoleName, setNewRoleName] = useState('');
  const [newRoleDescription, setNewRoleDescription] = useState('');

  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const [inviteName, setInviteName] = useState('');
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState('');

  const [passwordModalOpen, setPasswordModalOpen] = useState(false);
  const [selectedUserForPassword, setSelectedUserForPassword] = useState<User | null>(null);
  const [generatedPassword, setGeneratedPassword] = useState('');

  const [apiKeys, setApiKeys] = useState<ApiKey[]>(() => {
      const saved = localStorage.getItem('nova_api_keys');
      return saved ? JSON.parse(saved) : [
          { id: '1', name: 'Zapier Integration', prefix: 'nova_live_8a...', created: '2023-10-15', status: 'Active' },
          { id: '2', name: 'Slack Bot', prefix: 'nova_live_9b...', created: '2023-11-02', status: 'Active' }
      ];
  });
  const [isKeyModalOpen, setIsKeyModalOpen] = useState(false);
  const [newKeyName, setNewKeyName] = useState('');
  const [newlyGeneratedKey, setNewlyGeneratedKey] = useState<string | null>(null);

  const [mfaEnabled, setMfaEnabled] = useState(false);
  const [sessionTimeout, setSessionTimeout] = useState('30');

  const [aiModel, setAiModel] = useState(() => localStorage.getItem('nova_ai_model') || 'gemini-3-flash-preview');
  const [aiFeatures, setAiFeatures] = useState({
      leadScoring: true,
      autoDraft: true,
      transcription: false,
      insights: true
  });

  const [alertSettings, setAlertSettings] = useState({
      hiring: true,
      attendance: true,
      leave: true,
      performance: true
  });
  const [digestFrequency, setDigestFrequency] = useState('realtime');

  useEffect(() => {
      localStorage.setItem('nova_api_keys', JSON.stringify(apiKeys));
  }, [apiKeys]);

  useEffect(() => {
      localStorage.setItem('nova_ai_model', aiModel);
  }, [aiModel]);

  // Colors Config - Synced with App.tsx Themes
  const COLORS = [
      { id: 'indigo', name: 'Default Indigo', hex: '#6366f1' },
      { id: 'slate', name: 'Midnight Blue', hex: '#0f172a' },
      { id: 'emerald', name: 'Emerald City', hex: '#10b981' },
      { id: 'purple', name: 'Royal Purple', hex: '#8b5cf6' }, // Changed to match Violet/Purple in App.tsx
      { id: 'orange', name: 'Sunset Orange', hex: '#f97316' },
      { id: 'rose', name: 'Ruby Red', hex: '#f43f5e' },
      { id: 'cyan', name: 'Ocean Cyan', hex: '#06b6d4' },
      { id: 'blue', name: 'Azure Blue', hex: '#3b82f6' }, 
  ];

  // Fonts Config
  const FONTS = [
      { id: 'Plus Jakarta', name: 'Plus Jakarta', description: 'Modern Geometric', family: "'Plus Jakarta Sans', sans-serif" },
      { id: 'Inter UI', name: 'Inter UI', description: 'Neo-Grotesque', family: "'Inter', sans-serif" },
      { id: 'Montserrat', name: 'Montserrat', description: 'Urban Classic', family: "'Montserrat', sans-serif" },
      { id: 'Outfit', name: 'Outfit', description: 'Modern Geometric', family: "'Outfit', sans-serif" },
      { id: 'Lexend', name: 'Lexend', description: 'Readability Focused', family: "'Lexend', sans-serif" },
      { id: 'Playfair Display', name: 'Playfair Display', description: 'Elegance Serif', family: "'Playfair Display', serif" },
  ];

  useEffect(() => {
    if (!editingRole && roles.length > 0) {
        setEditingRole(roles[0]);
    }
  }, [roles]);

  useEffect(() => {
      if (roles.length > 0 && isInviteModalOpen) {
          if (!inviteRole) {
              setInviteRole(roles[0].id);
          }
      }
  }, [roles, isInviteModalOpen]);

  const handleSave = () => {
    setPipelineGoal(Number(goalInput));
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
  };

  const toggleWorkingDay = (day: string) => {
      if (workingDays.includes(day)) {
          setWorkingDays(workingDays.filter(d => d !== day));
      } else {
          setWorkingDays([...workingDays, day]);
      }
  };

  const handleUpdateUserRole = (userId: string, roleId: string) => {
      setUsers(users.map(u => u.id === userId ? { ...u, roleId } : u));
      if (currentUser.id === userId) {
          setCurrentUser({ ...currentUser, roleId });
      }
  };

  const handleTogglePermission = (roleId: string, permission: Permission) => {
      setRoles(roles.map(r => {
          if (r.id !== roleId) return r;
          const hasPermission = r.permissions.includes(permission);
          return {
              ...r,
              permissions: hasPermission 
                  ? r.permissions.filter(p => p !== permission)
                  : [...r.permissions, permission]
          };
      }));
  };

  const handleCreateRole = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newRoleName.trim()) {
          alert('Role name is required');
          return;
      }
      const roleId = newRoleName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
      const newRole: RoleDefinition = {
          id: roleId,
          name: newRoleName.trim(),
          description: newRoleDescription || 'Custom Role',
          isSystem: false,
          permissions: ['view_dashboard'] 
      };
      setRoles([...roles, newRole]);
      setIsCreateRoleModalOpen(false);
      setNewRoleName('');
      setNewRoleDescription('');
      setEditingRole(newRole); 
  };

  const handleInviteMember = (e: React.FormEvent) => {
      e.preventDefault();
      if (!inviteEmail || !inviteName) return;
      const selectedRoleId = inviteRole || (roles.length > 0 ? roles[0].id : 'sales_rep');
      const newUser: User = {
          id: `u-${Date.now()}`,
          name: inviteName,
          email: inviteEmail,
          roleId: selectedRoleId,
          status: 'Active',
          lastLogin: 'Never',
          avatar: `https://i.pravatar.cc/150?u=${Date.now()}`
      };
      setUsers([newUser, ...users]);
      setIsInviteModalOpen(false);
      setInviteName('');
      setInviteEmail('');
      alert(`User ${inviteName} added successfully!`);
  };

  const handleDeleteRole = (roleId: string) => {
      if (window.confirm('Delete role?')) {
          setRoles(roles.filter(r => r.id !== roleId));
          if (editingRole?.id === roleId) setEditingRole(roles.find(r => r.id !== roleId) || null);
      }
  };

  const generateSecurePassword = () => {
      const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";
      let retVal = "";
      for (let i = 0, n = charset.length; i < 12; ++i) {
          retVal += charset.charAt(Math.floor(Math.random() * n));
      }
      return retVal;
  };

  const handleGeneratePassword = (user: User) => {
      const newPassword = generateSecurePassword();
      setGeneratedPassword(newPassword);
      setSelectedUserForPassword(user);
      setUsers(users.map(u => u.id === user.id ? { ...u, tempPassword: newPassword } : u));
      setPasswordModalOpen(true);
  };

  const handleOpenKeyModal = () => {
      setNewKeyName('');
      setNewlyGeneratedKey(null);
      setIsKeyModalOpen(true);
  };

  const handleGenerateKey = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newKeyName.trim()) return;

      const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
      let randomStr = '';
      const randomValues = new Uint32Array(24);
      crypto.getRandomValues(randomValues);
      for(let i=0; i<24; i++) {
          randomStr += chars[randomValues[i] % chars.length];
      }

      const fullKey = `nova_live_${randomStr}`;
      setNewlyGeneratedKey(fullKey);

      const newKey: ApiKey = {
          id: `k-${Date.now()}`,
          name: newKeyName,
          prefix: `nova_live_${randomStr.substring(0, 4)}...`,
          created: new Date().toISOString().split('T')[0],
          status: 'Active'
      };
      setApiKeys(prev => [...prev, newKey]);
  };

  const handleCloseKeyModal = () => {
      setIsKeyModalOpen(false);
      setNewKeyName('');
      setNewlyGeneratedKey(null);
  };

  const handleRevokeKey = (id: string) => {
      if (window.confirm("Are you sure you want to revoke this key? This action cannot be undone.")) {
          setApiKeys(prev => prev.filter(k => k.id !== id));
      }
  };

  const PERMISSION_GROUPS = {
      'System Administration': ['manage_users', 'manage_settings'],
      'Sales Operations': ['view_leads', 'edit_leads', 'manage_pipeline', 'view_revenue'],
      'Data Governance': ['delete_records', 'export_data'],
